import {
    ArrayProperty,
    EntityCollection,
    isPostgresCollection,
    isFirebaseCollection,
    NumberProperty,
    PostgresCollection,
    Properties,
    Property,
    Relation,
    RelationProperty,
    StringProperty
} from "@rebasepro/types";
import { deepEqual } from "fast-equals";

import { enumToObjectEntries, getSubcollections, getTableName, resolveCollectionRelations } from "../util";
import cloneDeep from "lodash/cloneDeep.js";
import { removeFunctions, mergeDeep } from "@rebasepro/utils";

export class CollectionRegistry {

    // Normalized runtime layer (used by Data Grid / UI)
    private collectionsByTableName = new Map<string, EntityCollection>();
    private collectionsBySlug = new Map<string, EntityCollection>();
    private rootCollections: EntityCollection[] = [];

    // Raw configuration layer (used by Collection Editor AST generator)
    private rawCollectionsByTableName = new Map<string, EntityCollection>();
    private rawCollectionsBySlug = new Map<string, EntityCollection>();
    private rawRootCollections: EntityCollection[] = [];

    // Snapshot of raw input for idempotency check — compared BEFORE normalization
    // to avoid the issue where normalization creates new objects that always fail equality.
    private lastRawInputSnapshot: ReturnType<typeof removeFunctions>[] | null = null;

    constructor(collections?: EntityCollection[]) {
        if (collections) {
            this.registerMultiple(collections);
        }
    }

    reset() {
        this.collectionsByTableName.clear();
        this.collectionsBySlug.clear();
        this.rootCollections = [];

        this.rawCollectionsByTableName.clear();
        this.rawCollectionsBySlug.clear();
        this.rawRootCollections = [];
    }

    /**
     * Registers a collection and its subcollections recursively.
     * Returns true if the collections have changed, false otherwise.
     *
     * Idempotent: compares the raw input (before normalization) against a stored
     * snapshot. Only re-normalizes and re-registers when the raw input actually changed.
     * @param collections
     */
    registerMultiple(collections: EntityCollection[]): boolean {
        // Compare raw input BEFORE normalization to detect actual changes.
        // This avoids the old issue where normalization creates new objects
        // that always fail deep-equal even when the source data is identical.
        const rawSnapshot = collections.map(c => removeFunctions(c));
        if (this.lastRawInputSnapshot && deepEqual(this.lastRawInputSnapshot, rawSnapshot)) {
            return false;
        }

        // Raw input has changed — normalize and register
        this.reset();

        const normalizedCollections = collections.map(c => this.normalizeCollection({ ...c }));

        // Phase 1: Register all top-level collections first (without recursion).
        // This ensures that injected entityViews (e.g. History tab) are preserved.
        // Without this, _registerRecursively could register a relation-target collection
        // (e.g. Tags from Posts.relations) using the raw module object (without injected views)
        // before the top-level Tags collection (with injected views) gets its turn.
        normalizedCollections.forEach((c, index) => {
            const raw = cloneDeep(collections[index]);
            this.rootCollections.push(c);
            this.rawRootCollections.push(raw);

            const normalized = this.normalizeCollection(c);
            this.collectionsByTableName.set(getTableName(normalized), normalized);
            this.rawCollectionsByTableName.set(getTableName(raw), raw);
            if (normalized.slug) {
                this.collectionsBySlug.set(normalized.slug, normalized);
            }
            if (raw.slug) {
                this.rawCollectionsBySlug.set(raw.slug, raw);
            }
        });

        // Phase 2: Now recurse into subcollections (relations, etc.)
        normalizedCollections.forEach((c, index) => {
            const subcollections = getSubcollections(c);
            const rawSubcollections = getSubcollections(collections[index]);
            if (subcollections && rawSubcollections) {
                subcollections.forEach((subCollection, subIndex) => {
                    this._registerRecursively(this.normalizeCollection(subCollection), cloneDeep(rawSubcollections[subIndex]));
                });
            }
        });

        // Store the snapshot for future comparisons
        this.lastRawInputSnapshot = rawSnapshot;

        return true;
    }

    register(collection: EntityCollection, rawCollection?: EntityCollection) {
        const raw = rawCollection ? cloneDeep(rawCollection) : cloneDeep(collection);

        this.rootCollections.push(collection);
        this.rawRootCollections.push(raw);

        this._registerRecursively(collection, raw);
    }

    private _registerRecursively(collection: EntityCollection, rawCollection: EntityCollection) {
        if (this.collectionsByTableName.has(getTableName(collection))) {
            return;
        }

        const normalizedCollection = this.normalizeCollection(collection);
        this.collectionsByTableName.set(getTableName(normalizedCollection), normalizedCollection);
        this.rawCollectionsByTableName.set(getTableName(rawCollection), rawCollection);

        if (normalizedCollection.slug) {
            this.collectionsBySlug.set(normalizedCollection.slug, normalizedCollection);
        }
        if (rawCollection.slug) {
            this.rawCollectionsBySlug.set(rawCollection.slug, rawCollection);
        }

        const subcollections = getSubcollections(collection);
        const rawSubcollections = getSubcollections(rawCollection);

        if (subcollections && rawSubcollections) {
            subcollections.forEach((subCollection, index) => {
                this._registerRecursively(this.normalizeCollection(subCollection), cloneDeep(rawSubcollections[index]));
            });
        }
    }

    public normalizeCollection(collection: EntityCollection): EntityCollection {
        const relations = isPostgresCollection(collection) ? (collection.relations ?? []) : [];
        const properties: Properties = this.normalizeProperties(collection.properties, relations);

        collection.properties = properties;

        // Populate childCollections from driver-specific fields
        if (!collection.childCollections) {
            if (isFirebaseCollection(collection) && collection.subcollections) {
                collection.childCollections = collection.subcollections;
            } else if (isPostgresCollection(collection) && collection.relations) {
                const manyRelations = collection.relations.filter(r => r.cardinality === "many");
                if (manyRelations.length > 0) {
                    collection.childCollections = () => manyRelations.map(r => {
                        const target = r.target();
                        return r.overrides ? mergeDeep(target, r.overrides) : target;
                    });
                }
            }
        }

        return collection;
    }

    private normalizeProperties(properties: Properties, relations: Relation[]): Properties {
        const newProperties: Properties = {};
        for (const key in properties) {
            newProperties[key] = this.normalizeProperty(properties[key], relations);
        }
        return newProperties;
    }

    private normalizeProperty(property: Property, relations: Relation[]): Property {
        const newProperty = { ...property };

        if (newProperty.type === "map" && newProperty.properties) {
            newProperty.properties = this.normalizeProperties(newProperty.properties, relations);
        } else if (newProperty.type === "array") {
            // Cast via unknown to get a properly typed mutable reference
            const arrayProp = newProperty as unknown as ArrayProperty;
            if (arrayProp.of) {
                if (Array.isArray(arrayProp.of)) {
                    (arrayProp as { of: Property | Property[] }).of = arrayProp.of.map(p => this.normalizeProperty(p, relations));
                } else {
                    arrayProp.of = this.normalizeProperty(arrayProp.of, relations);
                }
            } else if (arrayProp.oneOf && arrayProp.oneOf.properties) {
                arrayProp.oneOf.properties = this.normalizeProperties(arrayProp.oneOf.properties, relations);
            }
        } else if ((newProperty.type === "string" || newProperty.type === "number") && newProperty.enum) {
            const stringOrNumberProperty = newProperty as StringProperty | NumberProperty;
            if (typeof stringOrNumberProperty.enum === "object" && !Array.isArray(stringOrNumberProperty.enum)) {
                (stringOrNumberProperty as unknown as Record<string, unknown>).enum = enumToObjectEntries(stringOrNumberProperty.enum)?.filter((value) => value && (value.id || value.id === 0) && value.label) ?? [];
            }
        } else if (newProperty.type === "relation") {
            const relationProperty = newProperty as RelationProperty;
            const relation = relations.find(r => r.relationName === relationProperty.relationName);
            if (relation) {
                // we attach the resolved relation to the property
                (relationProperty as unknown as Record<string, unknown>).relation = relation;
            } else {
                console.warn(`Could not find relation for property with relationName: ${relationProperty.relationName}`);
            }
        }

        return newProperty;
    }

    get(path: string): EntityCollection | undefined {
        // First try slug lookup
        const bySlug = this.collectionsBySlug.get(path);
        if (bySlug) return bySlug;

        // Fallback to table name lookup
        return this.collectionsByTableName.get(path);
    }

    /**
     * Gets the pristine, un-normalized collection exactly as it was provided.
     * Useful for the AST editor so it doesn't accidentally serialize injected metadata back to disk.
     */
    getRaw(path: string): EntityCollection | undefined {
        const bySlug = this.rawCollectionsBySlug.get(path);
        if (bySlug) return bySlug;
        return this.rawCollectionsByTableName.get(path);
    }

    /**
     * Get collection by resolving multi-segment paths through relations
     * e.g., "authors/70/posts" resolves to the posts collection
     */
    getCollectionByPath(collectionPath: string): EntityCollection | undefined {
        // Handle simple single collection path
        if (!collectionPath.includes("/")) {
            return this.get(collectionPath);
        }

        // Handle multi-segment paths by resolving through relations
        const pathSegments = collectionPath.split("/").filter(p => p);

        if (pathSegments.length < 3 || pathSegments.length % 2 === 0) {
            throw new Error(`Invalid relation path: ${collectionPath}. Expected format: collection/id/relation or collection/id/relation/id/relation`);
        }

        // Start with the root collection
        const rootCollectionPath = pathSegments[0];
        let currentCollection = this.get(rootCollectionPath);

        if (!currentCollection) {
            throw new Error(`Root collection not found: ${rootCollectionPath}`);
        }

        // Navigate through the path using relations
        for (let i = 2; i < pathSegments.length; i += 2) {
            const relationKey = pathSegments[i];

            // Get relations for current collection
            if (!isPostgresCollection(currentCollection)) {
                throw new Error(`Relation path navigation requires a PostgreSQL collection, but '${currentCollection.slug}' uses driver '${currentCollection.driver}'`);
            }
            const resolvedRelations = resolveCollectionRelations(currentCollection);
            const relation = resolvedRelations[relationKey];

            if (!relation) {
                throw new Error(`Relation '${relationKey}' not found in collection '${currentCollection.slug}'`);
            }

            // Move to the target collection
            currentCollection = relation.target();

            // If there are more segments, continue navigation
            if (i + 1 < pathSegments.length) {
                // Skip entity ID segment
            }
        }

        return currentCollection;
    }

    getCollections(): EntityCollection[] {
        return Array.from(this.collectionsByTableName.values());
    }

    getRawCollections(): EntityCollection[] {
        return Array.from(this.rawCollectionsByTableName.values());
    }

    /**
     * Resolves a multi-segment path like "products/123/locales" and returns
     * information about the collections and entity IDs along the path
     */
    resolvePathToCollections(path: string): {
        collections: EntityCollection[],
        entityIds: (string | number)[],
        finalCollection: EntityCollection
    } {
        const pathSegments = path.split("/").filter(p => p);

        if (pathSegments.length === 0) {
            throw new Error(`Invalid path: ${path}`);
        }

        if (pathSegments.length % 2 !== 1) {
            throw new Error(`Invalid collection path: ${path}. It must have an odd number of segments.`);
        }

        const collections: EntityCollection[] = [];
        const entityIds: (string | number)[] = [];

        // Start with the first collection
        let currentCollection = this.get(pathSegments[0]);

        if (!currentCollection) {
            throw new Error(`Unknown collection path or slug: ${pathSegments[0]}`);
        }

        collections.push(currentCollection);

        // Process the rest of the path in pairs (entityId, subcollectionSlug)
        for (let i = 1; i < pathSegments.length; i += 2) {
            const entityId = pathSegments[i];
            entityIds.push(entityId);

            if (i + 1 < pathSegments.length) {
                const subcollectionSlug = pathSegments[i + 1];
                const subcollections: EntityCollection[] | undefined = getSubcollections(currentCollection);
                if (!subcollections || subcollections.length === 0) {
                    throw new Error(`No subcollections found for ${currentCollection.slug} in path: ${path}`);
                }

                const subcollection: EntityCollection | undefined = subcollections.find(c => c.slug === subcollectionSlug);
                if (!subcollection) {
                    throw new Error(`Subcollection '${subcollectionSlug}' not found in ${currentCollection.slug}`);
                }
                currentCollection = subcollection;
                collections.push(currentCollection);
            }
        }

        return {
            collections,
            entityIds,
            finalCollection: currentCollection
        };
    }

}

function areCollectionListsEqual(a: EntityCollection[], b: EntityCollection[]) {
    // console.log("Comparing collection lists", a, b);
    // return true;
    if (a.length !== b.length) {
        return false;
    }
    const aCopy = [...a];
    const bCopy = [...b];
    const aSorted = aCopy.sort((x, y) => x.slug.localeCompare(y.slug));
    const bSorted = bCopy.sort((x, y) => x.slug.localeCompare(y.slug));
    return aSorted.every((value, index) => areCollectionsEqual(value, bSorted[index]));
}

function areCollectionsEqual(a: EntityCollection, b: EntityCollection) {
    const subcollectionsA = getSubcollections(a);
    const subcollectionsB = getSubcollections(b);
    const { driver: _dA, ...restA } = a as Record<string, unknown>;
    const { driver: _dB, ...restB } = b as Record<string, unknown>;
    // Remove subcollections/relations from comparison objects (already handled above)
    delete restA.subcollections;
    delete restB.subcollections;
    delete restA.relations;
    delete restB.relations;
    if (!areCollectionListsEqual(subcollectionsA, subcollectionsB)) {
        return false;
    }
    return deepEqual(removeFunctions(restA), removeFunctions(restB));
}

import {
    DataDriver,
    RebaseData,
    CollectionAccessor,
    FindParams,
    FindResponse,
    Entity,
    EntityValues,
    FilterValues,
    WhereFilterOp
} from "@rebasepro/types";

/**
 * Convert PostgREST-style filter object to the internal DataDriver FilterValues format.
 *
 * PostgREST: { status: "eq.published", age: "gte.18" }
 * Internal:  { status: ["==", "published"], age: [">=", 18] }
 */
function convertWhereToFilter(where?: Record<string, string>): FilterValues<string> | undefined {
    if (!where) return undefined;

    const operatorMap: Record<string, WhereFilterOp> = {
        "eq": "==",
        "neq": "!=",
        "gt": ">",
        "gte": ">=",
        "lt": "<",
        "lte": "<=",
        "in": "in",
        "nin": "not-in",
        "cs": "array-contains",
        "csa": "array-contains-any",
    };

    const filter: FilterValues<string> = {};

    for (const [field, rawValue] of Object.entries(where)) {
        const dotIndex = rawValue.indexOf(".");
        if (dotIndex === -1) continue;

        const op = rawValue.substring(0, dotIndex);
        let value: unknown = rawValue.substring(dotIndex + 1);

        // Parse list values like "(admin,editor)"
        if (value.startsWith("(") && value.endsWith(")")) {
            value = value.slice(1, -1).split(",").map((v: string) => v.trim());
        }

        // Try to parse numbers
        if (typeof value === "string" && !isNaN(Number(value)) && value.trim() !== "") {
            value = Number(value);
        }

        const mappedOp = operatorMap[op];
        if (mappedOp) {
            filter[field] = [mappedOp, value];
        }
    }

    return Object.keys(filter).length > 0 ? filter : undefined;
}

/**
 * Parse an orderBy string like "created_at:desc" into [field, direction].
 */
function parseOrderBy(orderBy?: string): [string, "asc" | "desc"] | undefined {
    if (!orderBy) return undefined;
    const parts = orderBy.split(":");
    const field = parts[0];
    const direction = (parts[1] as "asc" | "desc") || "asc";
    return [field, direction];
}

/**
 * Create a CollectionAccessor that delegates to a DataDriver for a given collection slug.
 */
function createDriverAccessor<M extends Record<string, unknown> = Record<string, unknown>>(
    driver: DataDriver,
    slug: string
): CollectionAccessor<M> {
    return {
        async find(params?: FindParams): Promise<FindResponse<M>> {
            const orderParsed = parseOrderBy(params?.orderBy);
            const entities = await driver.fetchCollection<M>({
                path: slug,
                limit: params?.limit,
                startAfter: params?.offset,
                filter: convertWhereToFilter(params?.where),
                orderBy: orderParsed?.[0],
                order: orderParsed?.[1],
                searchString: params?.searchString,
            });
            const limit = params?.limit ?? 20;
            const offset = params?.offset ?? 0;
            return {
                data: entities,
                meta: {
                    total: entities.length,
                    limit,
                    offset,
                    hasMore: entities.length >= limit
                }
            };
        },

        async findById(id: string | number): Promise<Entity<M> | undefined> {
            return driver.fetchEntity<M>({ path: slug, entityId: id });
        },

        async create(data: Partial<EntityValues<M>>, id?: string | number): Promise<Entity<M>> {
            return driver.saveEntity<M>({
                path: slug,
                values: data,
                entityId: id,
                status: "new"
            });
        },

        async update(id: string | number, data: Partial<EntityValues<M>>): Promise<Entity<M>> {
            return driver.saveEntity<M>({
                path: slug,
                values: data,
                entityId: id,
                status: "existing"
            });
        },

        async delete(id: string | number): Promise<void> {
            return driver.deleteEntity({
                entity: { id, path: slug, values: {} as Record<string, unknown> }
            });
        },

        count: driver.countEntities
            ? async (params?: FindParams): Promise<number> => {
                return driver.countEntities!({
                    path: slug,
                    filter: convertWhereToFilter(params?.where),
                });
            }
            : undefined,

        listen: driver.listenCollection
            ? (params: FindParams | undefined, onUpdate: (response: FindResponse<M>) => void, onError?: (error: Error) => void) => {
                const orderParsed = parseOrderBy(params?.orderBy);
                const limit = params?.limit ?? 20;
                const offset = params?.offset ?? 0;
                return driver.listenCollection!<M>({
                    path: slug,
                    limit: params?.limit,
                    startAfter: params?.offset,
                    filter: convertWhereToFilter(params?.where),
                    orderBy: orderParsed?.[0],
                    order: orderParsed?.[1],
                    searchString: params?.searchString,
                    onUpdate: (entities) => {
                        onUpdate({
                            data: entities,
                            meta: {
                                total: entities.length,
                                limit,
                                offset,
                                hasMore: entities.length >= limit
                            }
                        });
                    },
                    onError
                });
            } : undefined,

        listenById: driver.listenEntity
            ? (id: string | number, onUpdate: (entity: Entity<M> | undefined) => void, onError?: (error: Error) => void) => {
                return driver.listenEntity!<M>({
                    path: slug,
                    entityId: id,
                    onUpdate: (entity) => onUpdate(entity ?? undefined),
                    onError
                });
            } : undefined
    };
}

/**
 * Build a `RebaseData` object from a `DataDriver` using JavaScript Proxy.
 *
 * This is the key bridge: any property access like `data.products` returns
 * a `CollectionAccessor` backed by the underlying DataDriver, without
 * needing per-collection code generation.
 *
 * @example
 * const data = buildRebaseData(driver);
 * await data.products.create({ name: "Camera", price: 299 });
 * const { data: items } = await data.products.find({ where: { status: "eq.published" } });
 */
export function buildRebaseData(driver: DataDriver): RebaseData {
    const cache = new Map<string, CollectionAccessor>();

    function getAccessor(slug: string): CollectionAccessor {
        let accessor = cache.get(slug);
        if (!accessor) {
            accessor = createDriverAccessor(driver, slug);
            cache.set(slug, accessor);
        }
        return accessor;
    }

    const target = {
        collection: getAccessor
    } as RebaseData;

    return new Proxy(target, {
        get(_target, prop: string | symbol) {
            if (prop === "collection") return getAccessor;
            // Ignore Symbol properties (e.g. Symbol.toPrimitive, Symbol.iterator)
            if (typeof prop === "symbol") return undefined;
            // Ignore internal JS properties
            if (prop === "then" || prop === "toJSON" || prop === "$$typeof") return undefined;
            return getAccessor(prop);
        }
    });
}

declare module "json-logic-js" {
    interface JsonLogic {
        apply(logic: any, data?: any): any;
        add_operation(name: string, fn: (...args: any[]) => any): void;
    }
    const jsonLogic: JsonLogic;
    export default jsonLogic;
}

import {
    AdditionalFieldDelegate,
    ArrayProperty,
    BooleanProperty,
    DateProperty,
    EntityCallbacks,
    EntityCollection,
    EnumValueConfig,
    EnumValues,
    GeopointProperty,
    MapProperty,
    NumberProperty, Properties,
    Property,
    ReferenceProperty,
    StringProperty,
    User
} from "@rebasepro/types";


/**
 * Identity function we use to defeat the type system of Typescript and build
 * collection views with all its properties
 * @param collection
 * @group Builder
 */
export function buildCollection<
    M extends Record<string, unknown> = Record<string, unknown>,
    USER extends User = User>
    (
        collection: EntityCollection<M, USER>
    ): EntityCollection<M, USER> {
    return collection;
}

/**
 * Identity function we use to defeat the type system of Typescript and preserve
 * the property keys.
 * @param property
 * @group Builder
 */
export function buildProperty<T, P extends Property = Property>(
    property: P
):
    P extends StringProperty ? StringProperty :
    P extends NumberProperty ? NumberProperty :
    P extends BooleanProperty ? BooleanProperty :
    P extends DateProperty ? DateProperty :
    P extends GeopointProperty ? GeopointProperty :
    P extends ReferenceProperty ? ReferenceProperty :
    P extends ArrayProperty ? ArrayProperty :
    P extends MapProperty ? MapProperty : never {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return property as unknown as ReturnType<typeof buildProperty<T, P>>;
}

/**
 * Identity function we use to defeat the type system of Typescript and preserve
 * the properties keys.
 * @param properties
 * @group Builder
 */
export function buildProperties<M extends Record<string, unknown>>(
    properties: Properties
): Properties {
    return properties;
}

/**
 * Identity function we use to defeat the type system of Typescript and preserve
 * the properties keys.
 * @param propertiesOrBuilder
 * @group Builder
 */
export function buildPropertiesOrBuilder<M extends Record<string, unknown>>(
    propertiesOrBuilder: Properties
): Properties {
    return propertiesOrBuilder;
}

/**
 * Identity function we use to defeat the type system of Typescript and preserve
 * the properties keys.
 * @param enumValues
 * @group Builder
 */
export function buildEnum(
    enumValues: EnumValues
): EnumValues {
    return enumValues;
}

/**
 * Identity function we use to defeat the type system of Typescript and preserve
 * the properties keys.
 * @param enumValueConfig
 * @group Builder
 */
export function buildEnumValueConfig(
    enumValueConfig: EnumValueConfig
): EnumValueConfig {
    return enumValueConfig;
}

/**
 * Identity function we use to defeat the type system of Typescript and preserve
 * the properties keys.
 * @param callbacks
 * @group Builder
 */
export function buildEntityCallbacks<M extends Record<string, unknown> = Record<string, unknown>>(
    callbacks: EntityCallbacks<M>
): EntityCallbacks<M> {
    return callbacks;
}

/**
 * Identity function we use to defeat the type system of Typescript and build
 * additional field delegates views with all its properties
 * @param additionalFieldDelegate
 * @group Builder
 */
export function buildAdditionalFieldDelegate<M extends Record<string, unknown>, USER extends User = User>(
    additionalFieldDelegate: AdditionalFieldDelegate<M, USER>
): AdditionalFieldDelegate<M, USER> {
    return additionalFieldDelegate;
}

import { EntityCallbacks, Properties } from "@rebasepro/types";
import { mergeDeep } from "@rebasepro/utils";

/**
 * Helper function to recursively check if there are any callbacks in the properties.
 */
function hasPropertyCallbacks(properties: Properties, callbackName: "afterRead" | "beforeSave"): boolean {
    if (!properties) return false;
    for (const property of Object.values(properties)) {
        if (property.callbacks?.[callbackName]) return true;
        if (property.type === "map" && property.properties) {
            if (hasPropertyCallbacks(property.properties, callbackName)) return true;
        } else if (property.type === "array" && property.of) {
            const ofs = Array.isArray(property.of) ? property.of : [property.of];
            for (const of of ofs) {
                if (of.callbacks?.[callbackName]) return true;
                if (of.type === "map" && of.properties && hasPropertyCallbacks(of.properties, callbackName)) return true;
            }
        }
    }
    return false;
}

/**
 * Recursively process properties to apply field-level hooks.
 */
async function processProperties(
    properties: Properties,
    values: Record<string, unknown>,
    previousValues: Record<string, unknown>,
    propsContext: unknown,
    callbackName: "afterRead" | "beforeSave"
): Promise<Record<string, unknown>> {
    if (!values || typeof values !== "object") return values;

    let result = { ...values };

    for (const [key, property] of Object.entries(properties)) {
        if (result[key] === undefined) continue;

        let currentValue = result[key];
        let previousValue = previousValues?.[key];

        // 1. Array Property
        if (property.type === "array" && Array.isArray(currentValue)) {
            // We only support traversing single-type arrays for hooks currently to avoid complex union matching
            if (property.of && !Array.isArray(property.of)) {
                currentValue = await Promise.all(currentValue.map(async (item, index) => {
                    const prevItem = Array.isArray(previousValue) ? previousValue[index] : undefined;
                    // Mock a properties object to process a single item
                    const singlePropData = { "_tmp": property.of } as Properties;
                    const res = await processProperties(singlePropData, { "_tmp": item }, { "_tmp": prevItem }, propsContext, callbackName);
                    return res["_tmp"];
                }));
            }
        }
        // 2. Map Property
        else if (property.type === "map" && property.properties && typeof currentValue === "object") {
            currentValue = await processProperties(property.properties, currentValue as Record<string, unknown>, (previousValue ?? {}) as Record<string, unknown>, propsContext, callbackName);
        }

        // 3. Property's own callback
        if (property.callbacks?.[callbackName]) {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const cbRes = await Promise.resolve(property.callbacks[callbackName]({
                ...(propsContext as Record<string, unknown>),
                value: currentValue,
                previousValue
            } as never));
            if (cbRes !== undefined) {
                currentValue = cbRes;
            }
        }

        result[key] = currentValue;
    }
    return result;
}

/**
 * Helper function to extract field-level PropertyCallbacks from a properties schema
 * and wrap them into an EntityCallbacks object recursively.
 */
export const buildPropertyCallbacks = (properties: Properties): EntityCallbacks | undefined => {
    if (!properties) return undefined;

    const propertyCallbacks: EntityCallbacks = {};

    if (hasPropertyCallbacks(properties, "afterRead")) {
        propertyCallbacks.afterRead = async (props) => {
            const processedValues = await processProperties(
                properties,
                props.entity.values as Record<string, unknown>,
                props.entity.values as Record<string, unknown>,
                props as unknown,
                "afterRead"
            );
            return { ...props.entity, values: processedValues };
        };
    }

    if (hasPropertyCallbacks(properties, "beforeSave")) {
        propertyCallbacks.beforeSave = async (props) => {
            return await processProperties(
                properties,
                props.values as Record<string, unknown>,
                (props.previousValues ?? {}) as Record<string, unknown>,
                props as unknown,
                "beforeSave"
            );
        };
    }

    return Object.keys(propertyCallbacks).length > 0 ? propertyCallbacks : undefined;
};

import {
    DefaultSelectedViewBuilder,
    DefaultSelectedViewParams,
    EntityCollection,
    Properties,
    Property,
} from "@rebasepro/types";
import { isPropertyBuilder } from "./entities";

export function sortProperties<M extends Record<string, unknown>>(properties: Properties, propertiesOrder?: string[]): Properties {
    try {
        const propertiesKeys = Object.keys(properties);
        // If no propertiesOrder, just use the original keys order
        if (!propertiesOrder || propertiesOrder.length === 0) {
            return propertiesKeys
                .map((key) => {
                    const property = properties[key] as Property;
                    if (!isPropertyBuilder(property) && property?.type === "map" && property.properties) {
                        return ({
                            [key]: {
                                ...property,
                                properties: sortProperties(property.properties, property.propertiesOrder)
                            }
                        });
                    } else {
                        return ({ [key]: property });
                    }
                })
                .reduce((a: Properties, b: Properties) => ({ ...a, ...b }), {}) as Properties;
        }

        // Filter propertiesOrder to only include TOP-LEVEL property keys that exist
        // (ignore nested keys like "data.mode" - they are for column ordering, not property filtering)
        const validOrderKeys = (propertiesOrder as string[]).filter(key => {
            // Only include top-level keys (no dots) that exist in properties
            return !key.includes(".") && properties[key];
        });

        // Track which properties we've processed
        const processedKeys = new Set<string>(validOrderKeys);

        // Build result starting with ordered properties
        const orderedResult = validOrderKeys
            .map((key) => {
                const property = properties[key] as Property;
                if (!isPropertyBuilder(property) && property?.type === "map" && property.properties) {
                    return ({
                        [key]: {
                            ...property,
                            properties: sortProperties(property.properties, property.propertiesOrder)
                        }
                    });
                } else {
                    return ({ [key]: property });
                }
            })
            .reduce((a: Properties, b: Properties) => ({ ...a, ...b }), {}) as Properties;

        // Append any properties that were NOT in propertiesOrder (so they don't disappear!)
        const missingProperties = propertiesKeys
            .filter(key => !processedKeys.has(key))
            .map((key) => {
                const property = properties[key] as Property;
                if (!isPropertyBuilder(property) && property?.type === "map" && property.properties) {
                    return ({
                        [key]: {
                            ...property,
                            properties: sortProperties(property.properties, property.propertiesOrder)
                        }
                    });
                } else {
                    return ({ [key]: property });
                }
            })
            .reduce((a: Properties, b: Properties) => ({ ...a, ...b }), {}) as Properties;

        return { ...orderedResult, ...missingProperties };
    } catch (e) {
        console.error("Error sorting properties", e);
        return properties;
    }
}

export function resolveDefaultSelectedView(
    defaultSelectedView: string | DefaultSelectedViewBuilder | undefined,
    params: DefaultSelectedViewParams
) {
    if (!defaultSelectedView) {
        return undefined;
    } else if (typeof defaultSelectedView === "string") {
        return defaultSelectedView;
    } else {
        return defaultSelectedView(params);
    }
}



export function getLocalChangesBackup(collection: EntityCollection) {
    if (!collection.localChangesBackup) {
        return "manual_apply";
    }

    return collection.localChangesBackup;
}

/**
 * Returns the primary keys for an entity collection by inspecting the properties
 * and finding any properties with `isId`.
 * Fallbacks to `["id"]` if no properties are marked as `isId: true`.
 * @param collection
 */
export function getPrimaryKeys<M extends Record<string, unknown>>(collection: EntityCollection<M>): Extract<keyof M, string>[] {
    const properties = collection.properties;
    if (!properties) {
        return ["id"] as Extract<keyof M, string>[];
    }
    const ids = Object.entries(properties)
        .filter(([key, prop]) => typeof prop === "object" && prop !== null && "isId" in prop && Boolean(prop.isId))
        .map(([key]) => key);

    if (ids.length > 0) {
        return ids as Extract<keyof M, string>[];
    }
    return ["id"] as Extract<keyof M, string>[];
}

import jsonLogic from "json-logic-js";
import {
    ArrayProperty,
    AuthController,
    ConditionContext,
    EnumValueConfig,
    JsonLogicRule,
    NumberProperty,
    PropertyConditions,
    Property,
    ReferenceProperty,
    StringProperty
} from "@rebasepro/types";

/**
 * Access a nested property from an object via dot notation.
 */
function getIn(obj: Record<string, unknown> | unknown, path: string): unknown {
    if (!obj || !path) return undefined;
    return path.split('.').reduce((acc: unknown, part: string) => acc && (acc as Record<string, unknown>)[part], obj);
}

let operationsRegistered = false;

/**
 * Register custom JSON Logic operations for Rebase.
 * Call this once at app initialization.
 */
export function registerConditionOperations(): void {
    if (operationsRegistered) return;

    // Check if user has a specific role by ID
    jsonLogic.add_operation("hasRole", function (this: ConditionContext, roleId: string) {
        return this?.user?.roles?.includes(roleId) ?? false;
    });

    // Check if user has any of the specified roles
    jsonLogic.add_operation("hasAnyRole", function (this: ConditionContext, roleIds: string[]) {
        if (!this?.user?.roles || !Array.isArray(roleIds)) return false;
        return roleIds.some(role => this.user.roles.includes(role));
    });

    // Check if a timestamp is today
    jsonLogic.add_operation("isToday", (timestamp: number) => {
        if (!timestamp) return false;
        const date = new Date(timestamp);
        const today = new Date();
        return date.getFullYear() === today.getFullYear() &&
            date.getMonth() === today.getMonth() &&
            date.getDate() === today.getDate();
    });

    // Check if a timestamp is in the past
    jsonLogic.add_operation("isPast", (timestamp: number) => {
        if (!timestamp) return false;
        return timestamp < Date.now();
    });

    // Check if a timestamp is in the future
    jsonLogic.add_operation("isFuture", (timestamp: number) => {
        if (!timestamp) return false;
        return timestamp > Date.now();
    });

    operationsRegistered = true;
}

/**
 * Evaluate a JSON Logic rule against the given context.
 */
export function evaluateCondition(rule: JsonLogicRule, context: ConditionContext): unknown {
    // Ensure operations are registered
    registerConditionOperations();
    return jsonLogic.apply(rule, context);
}

/**
 * Convert a value to a format suitable for JSON Logic evaluation.
 * Specifically handles Date objects by converting them to Unix timestamps.
 */
function serializeValueForConditions(value: unknown): unknown {
    if (value === null || value === undefined) {
        return value;
    }

    // Handle Date objects
    if (value instanceof Date) {
        return value.getTime();
    }

    // Handle Firestore Timestamp-like objects (have toDate or toMillis)
    if (typeof (value as { toMillis?: () => number })?.toMillis === "function") {
        return (value as { toMillis: () => number }).toMillis();
    }
    if (typeof (value as { toDate?: () => Date })?.toDate === "function") {
        return (value as { toDate: () => Date }).toDate().getTime();
    }

    // Handle arrays recursively
    if (Array.isArray(value)) {
        return value.map(serializeValueForConditions);
    }

    // Handle plain objects recursively
    if (typeof value === "object") {
        const result: Record<string, unknown> = {};
        for (const key of Object.keys(value as Record<string, unknown>)) {
            result[key] = serializeValueForConditions((value as Record<string, unknown>)[key]);
        }
        return result;
    }

    return value;
}

/**
 * Build a ConditionContext from the current property resolution context.
 */
export function buildConditionContext(params: {
    propertyKey?: string;
    values?: Record<string, unknown>;
    previousValues?: Record<string, unknown>;
    path: string;
    entityId?: string;
    index?: number;
    authController: AuthController;
}): ConditionContext {
    const {
        propertyKey,
        values,
        previousValues,
        path,
        entityId,
        index,
        authController
    } = params;

    const user = authController.user;
    const serializedValues = serializeValueForConditions(values ?? {});
    const serializedPreviousValues = serializeValueForConditions(previousValues ?? values ?? {});

    return {
        values: serializedValues as Record<string, unknown>,
        previousValues: serializedPreviousValues as Record<string, unknown>,
        propertyValue: propertyKey ? getIn(serializedValues, propertyKey) : undefined,
        path,
        entityId,
        isNew: !entityId,
        index,
        user: {
            uid: user?.uid ?? "",
            email: user?.email ?? null,
            displayName: user?.displayName ?? null,
            photoURL: user?.photoURL ?? null,
            roles: (user?.roles ?? []).map((r: unknown) => typeof r === "string" ? r : (r as { id: string }).id)
        },
        now: Date.now()
    };
}

/**
 * Apply PropertyConditions to a resolved property, evaluating all JSON Logic rules.
 */
export function applyPropertyConditions(
    property: Property,
    context: ConditionContext
): Property {
    const { conditions } = property;
    if (!conditions) return property;

    let result = { ...property };

    // ═══════════════════════════════════════════════════════════════════════
    // FIELD STATE CONDITIONS
    // ═══════════════════════════════════════════════════════════════════════

    // Evaluate disabled condition
    if (conditions.disabled) {
        const isDisabled = evaluateCondition(conditions.disabled, context);
        if (isDisabled) {
            result.disabled = {
                clearOnDisabled: conditions.clearOnDisabled ?? false,
                disabledMessage: conditions.disabledMessage,
                hidden: false
            };
        }
    }

    // Evaluate hidden condition
    if (conditions.hidden) {
        const isHidden = evaluateCondition(conditions.hidden, context);
        if (isHidden) {
            result.disabled = {
                ...(typeof result.disabled === "object" ? result.disabled : {}),
                hidden: true,
                clearOnDisabled: conditions.clearOnDisabled ?? false
            };
        }
    }

    // Evaluate readOnly condition
    if (conditions.readOnly) {
        const isReadOnly = evaluateCondition(conditions.readOnly, context);
        if (isReadOnly) {
            result.readOnly = true;
        }
    }

    // ═══════════════════════════════════════════════════════════════════════
    // VALIDATION CONDITIONS
    // ═══════════════════════════════════════════════════════════════════════

    // Evaluate required condition
    if (conditions.required !== undefined) {
        const isRequired = evaluateCondition(conditions.required, context) as boolean;
        result.validation = {
            ...result.validation,
            required: isRequired as boolean | undefined,
            requiredMessage: conditions.requiredMessage
        };
    }

    // ═══════════════════════════════════════════════════════════════════════
    // VALUE CONDITIONS
    // ═══════════════════════════════════════════════════════════════════════

    // Apply default value for new entities
    if (context.isNew && conditions.defaultValue !== undefined) {
        result.defaultValue = evaluateCondition(conditions.defaultValue, context) as Property["defaultValue"];
    }

    // ═══════════════════════════════════════════════════════════════════════
    // ENUM CONDITIONS
    // ═══════════════════════════════════════════════════════════════════════

    if ("enum" in result && result.enum && (conditions.enumConditions || conditions.allowedEnumValues || conditions.excludedEnumValues)) {
        (result as Record<string, unknown>).enum = applyEnumConditions(
            result.enum as EnumValueConfig[],
            conditions,
            context
        );
    }

    // ═══════════════════════════════════════════════════════════════════════
    // REFERENCE CONDITIONS
    // ═══════════════════════════════════════════════════════════════════════

    if (result.type === "reference") {
        if (conditions.referencePath) {
            (result as ReferenceProperty).path = evaluateCondition(conditions.referencePath, context) as string;
        }
        if (conditions.referenceFilter) {
            (result as ReferenceProperty).forceFilter = evaluateCondition(conditions.referenceFilter, context) as ReferenceProperty["forceFilter"];
        }
    }

    // ═══════════════════════════════════════════════════════════════════════
    // ARRAY CONDITIONS
    // ═══════════════════════════════════════════════════════════════════════

    if (result.type === "array") {
        if (conditions.canAddElements !== undefined) {
            (result as ArrayProperty).canAddElements = evaluateCondition(conditions.canAddElements, context) as boolean;
        }
        if (conditions.sortable !== undefined) {
            (result as ArrayProperty).sortable = evaluateCondition(conditions.sortable, context) as boolean;
        }
    }

    return result;
}

/**
 * Convert an object with numeric keys back to an array.
 * Firestore stores arrays as {"0": "a", "1": "b"} to avoid nested arrays.
 */
function objectToArray(obj: unknown): string[] {
    if (Array.isArray(obj)) return obj.map(String);
    if (obj && typeof obj === "object") {
        const keys = Object.keys(obj);
        if (keys.length > 0 && keys.every(k => !isNaN(Number(k)))) {
            return keys
                .sort((a, b) => Number(a) - Number(b))
                .map(k => (obj as Record<string, unknown>)[k])
                .filter((v): v is string => typeof v === "string" || typeof v === "number")
                .map(String);
        }
    }
    return [];
}

/**
 * Apply enum-specific conditions to filter and modify enum values.
 */
function applyEnumConditions(
    enumValues: EnumValueConfig[],
    conditions: PropertyConditions,
    context: ConditionContext
): EnumValueConfig[] {
    let result = [...enumValues];

    // Apply allowedEnumValues filter
    if (conditions.allowedEnumValues) {
        const allowed = evaluateCondition(conditions.allowedEnumValues, context);
        // Handle both array format and object-with-numeric-keys format (Firestore workaround)
        const allowedArray = objectToArray(allowed);
        if (allowedArray.length > 0) {
            result = result.filter(ev => allowedArray.includes(String(ev.id)));
        }
    }

    // Apply excludedEnumValues filter
    if (conditions.excludedEnumValues) {
        const excluded = evaluateCondition(conditions.excludedEnumValues, context);
        // Handle both array format and object-with-numeric-keys format
        const excludedArray = objectToArray(excluded);
        if (excludedArray.length > 0) {
            result = result.filter(ev => !excludedArray.includes(String(ev.id)));
        }
    }

    // Apply individual enum conditions
    if (conditions.enumConditions) {
        result = result
            .map(ev => {
                const evConditions = conditions.enumConditions?.[ev.id];
                if (!evConditions) return ev;

                // Check hidden condition first
                if (evConditions.hidden && evaluateCondition(evConditions.hidden, context)) {
                    return null; // Will be filtered out
                }

                // Check disabled condition
                if (evConditions.disabled && evaluateCondition(evConditions.disabled, context)) {
                    return {
                        ...ev,
                        disabled: true
                    };
                }

                return ev;
            })
            .filter((ev): ev is EnumValueConfig => ev !== null);
    }

    return result;
}

import {
    DataType,
    Entity,
    EntityReference,
    EntityRelation,
    EntityStatus,
    EntityValues,
    Properties,
    Property,
} from "@rebasepro/types";
import { DEFAULT_ONE_OF_TYPE, DEFAULT_ONE_OF_VALUE } from "./common";
import { mergeDeep } from "@rebasepro/utils";

export function isReadOnly(property: Property): boolean {
    if (property.readOnly)
        return true;
    if (property.type === "date") {
        if (property.autoValue)
            return true;
    }
    if (property.type === "reference") {
        return !property.path && !("Field" in property && property.Field);
    }
    return false;
}

export function isHidden(property: Property): boolean {
    return typeof property.disabled === "object" && Boolean(property.disabled.hidden);
}

export function isPropertyBuilder(property?: Property) {
    return typeof property?.dynamicProps === "function";
}

export function getDefaultValuesFor<M extends Record<string, any>>(properties: Properties): Partial<EntityValues<M>> {
    if (!properties) return {};
    return Object.entries(properties)
        .map(([key, property]) => {
            if (!property) return {};
            const value = getDefaultValueFor(property);
            return value === undefined ? {} : { [key]: value };
        })
        .reduce((a, b) => ({ ...a, ...b }), {}) as EntityValues<M>;
}

export function getDefaultValueFor(property?: Property) {
    if (!property) return undefined;
    if (isPropertyBuilder(property)) return undefined;
    if (property.defaultValue || property.defaultValue === null) {
        return property.defaultValue;
    } else if (property.type === "map" && property.properties) {
        const defaultValuesFor = getDefaultValuesFor(property.properties as Properties);
        if (Object.keys(defaultValuesFor).length === 0) return undefined;
        return defaultValuesFor;
    } else {
        return getDefaultValueFortype(property.type);
    }
}

export function getDefaultValueFortype(type: DataType) {
    if (type === "string") {
        return null;
    } else if (type === "number") {
        return null;
    } else if (type === "boolean") {
        return false;
    } else if (type === "date") {
        return null;
    } else if (type === "array") {
        return [];
    } else if (type === "map") {
        return {};
    } else {
        return null;
    }
}

/**
 * Update the automatic values in an entity before save
 * @group Driver
 */
export function updateDateAutoValues<M extends Record<string, any>>({
    inputValues,
    properties,
    status,
    timestampNowValue
}:
    {
        inputValues: Partial<EntityValues<M>>,
        properties: Properties,
        status: EntityStatus,
        timestampNowValue: unknown
    }): EntityValues<M> {
    return traverseValuesProperties(
        inputValues,
        properties,
        (inputValue, property) => {
            if (property.type === "date") {
                if (status === "existing" && property.autoValue === "on_update") {
                    return timestampNowValue;
                } else if ((status === "new" || status === "copy") &&
                    (property.autoValue === "on_update" || property.autoValue === "on_create")) {
                    return timestampNowValue;
                } else {
                    return inputValue;
                }
            } else {
                return inputValue;
            }
        }
    ) ?? {} as M;
}

/**
 * Add missing required fields, expected in the collection, to the values of an entity
 * @param values
 * @param properties
 * @group Driver
 */
export function sanitizeData<M extends Record<string, any>>
    (
        values: EntityValues<M>,
        properties: Properties
    ) {
    const result = values as Record<string, unknown>;
    Object.entries(properties)
        .forEach(([key, property]) => {
            if (values && values[key] !== undefined) result[key] = values[key];
            else if ((property as Property).validation?.required) result[key] = null;
        });
    return result;
}

export function getReferenceFrom<M extends Record<string, any>>(entity: Entity<M>): EntityReference {
    if (typeof entity.id !== "string")
        throw new Error("Only string IDs are supported in references");
    return new EntityReference({
        id: entity.id,
        path: entity.path,
        driver: entity.driver,
        databaseId: entity.databaseId
    });
}

export function getRelationFrom<M extends Record<string, any>>(entity: Entity<M>): EntityRelation {
    return new EntityRelation(entity.id, entity.path, entity);
}

/**
 * Normalize a value into a proper EntityRelation instance.
 * Handles EntityRelation class instances, and plain objects
 * with `__type === "relation"` or an `isEntityRelation()` method.
 *
 * Returns null if the value cannot be coerced.
 */
export function normalizeToEntityRelation(value: unknown): EntityRelation | null {
    if (value instanceof EntityRelation) return value;
    if (!value || typeof value !== "object" || Array.isArray(value)) return null;

    const obj = value as Record<string, unknown>;
    const isRelationLike =
        obj.__type === "relation" ||
        (typeof obj.isEntityRelation === "function" && (obj.isEntityRelation as () => boolean)());

    if (!isRelationLike) return null;

    return new EntityRelation(
        obj.id as string | number,
        obj.path as string,
        obj.data as Entity | undefined
    );
}

export function traverseValuesProperties<M extends Record<string, any>>(
    inputValues: Partial<EntityValues<M>>,
    properties: Properties,
    operation: (value: unknown, property: Property) => unknown
): EntityValues<M> | undefined {
    // Handle null/undefined inputValues - use empty object as base for mergeDeep
    const safeInputValues = inputValues ?? {};

    const updatedValues = Object.entries(properties)
        .map(([key, property]) => {
            const inputValue = safeInputValues && (safeInputValues)[key];
            const updatedValue = traverseValueProperty(inputValue, property as Property, operation);
            if (updatedValue === null) return null;
            if (updatedValue === undefined) return undefined;
            return ({ [key]: updatedValue });
        })
        .reduce((a, b) => ({ ...a, ...b }), {}) as EntityValues<M>;
    // Use mergeDeep to preserve class instances like EntityReference, GeoPoint
    const result = mergeDeep(safeInputValues, updatedValues);
    if (!result || Object.keys(result).length === 0) return undefined;
    return result;
}

export function traverseValueProperty(inputValue: unknown,
    property: Property,
    operation: (value: unknown, property: Property) => unknown): unknown {

    let value;
    if (property.type === "map" && property.properties) {
        value = traverseValuesProperties(inputValue as Partial<Record<string, unknown>>, property.properties, operation);
    } else if (property.type === "array") {
        const of = property.of;
        if (of && Array.isArray(inputValue) && !Array.isArray(of)) {
            value = inputValue.map((e) => traverseValueProperty(e, of, operation));
        } else if (of && Array.isArray(inputValue) && Array.isArray(of)) {
            value = inputValue.map((e, i) => {
                if (i < of.length)
                    return traverseValueProperty(e, of[i], operation);
                return null
            }).filter(Boolean);
        } else if (property.oneOf && Array.isArray(inputValue)) {
            const typeField = property.oneOf?.typeField ?? DEFAULT_ONE_OF_TYPE;
            const valueField = property.oneOf?.valueField ?? DEFAULT_ONE_OF_VALUE;
            value = inputValue.map((e) => {
                if (e === null) return null;
                if (typeof e !== "object") return e;
                const rec = e as Record<string, unknown>;
                const type = rec[typeField] as string;
                const childProperty = property.oneOf?.properties[type];
                if (!type || !childProperty) return e;
                return {
                    [typeField]: type,
                    [valueField]: traverseValueProperty(rec[valueField], childProperty, operation)
                };
            });
        } else {
            value = inputValue;
        }
    } else {
        value = operation(inputValue, property);
    }

    return value;
}

import { EntityCollection } from "@rebasepro/types";
type EntityCustomView<M extends Record<string, unknown> = Record<string, unknown>> = { key: string; [key: string]: unknown };
import { getCollectionPathsCombinations, removeInitialAndTrailingSlashes } from "./navigation_utils";
import { getSubcollections } from "./resolutions";

export type NavigationViewInternal<M extends Record<string, unknown> = Record<string, unknown>> =
    | NavigationViewEntityInternal<M>
    | NavigationViewCollectionInternal<M>
    | NavigationViewEntityCustomInternal<M>;

export interface NavigationViewEntityInternal<M extends Record<string, unknown>> {
    type: "entity";
    entityId: string | number;
    slug: string;
    path: string;
    parentCollection: EntityCollection<M>;
}

export interface NavigationViewCollectionInternal<M extends Record<string, unknown>> {
    type: "collection";
    id: string;
    slug: string;
    path: string;
    collection: EntityCollection<M>;
}

export interface NavigationViewEntityCustomInternal<M extends Record<string, unknown>> {
    type: "custom_view";
    slug: string;
    path: string;
    entityId: string | number;
    view: EntityCustomView<M>;
}

export function getNavigationEntriesFromPath(props: {
    path: string,
    collections: EntityCollection[] | undefined,
    currentFullPath?: string,
    contextEntityViews?: EntityCustomView[]
}): NavigationViewInternal[] {

    const {
        path,
        collections = [],
        currentFullPath,
    } = props;

    const subpaths = removeInitialAndTrailingSlashes(path).split("/");
    const subpathCombinations = getCollectionPathsCombinations(subpaths);

    const result: NavigationViewInternal[] = [];
    for (let i = 0; i < subpathCombinations.length; i++) {
        const subpathCombination = subpathCombinations[i];

        const collection = collections && collections.find((entry) => entry.slug === subpathCombination);

        if (collection) {
            const collectionPath = currentFullPath && currentFullPath.length > 0
                ? (currentFullPath + "/" + collection.slug)
                : collection.slug;
            result.push({
                type: "collection",
                id: collection.slug,
                slug: collectionPath,
                path: collectionPath,
                collection
            });
            const restOfThePath = removeInitialAndTrailingSlashes(removeInitialAndTrailingSlashes(path).replace(subpathCombination, ""));
            const nextSegments = restOfThePath.length > 0 ? restOfThePath.split("/") : [];
            if (nextSegments.length > 0) {
                const entityId = nextSegments[0];
                const path = collectionPath + "/" + entityId;
                result.push({
                    type: "entity",
                    entityId,
                    slug: collectionPath,
                    path,
                    parentCollection: collection
                });
                if (nextSegments.length > 1) {
                    const newPath = nextSegments.slice(1).join("/");
                    if (!collection) {
                        throw Error("collection not found resolving path: " + collection);
                    }
                    const entityViews = collection.entityViews;
                    const customView = entityViews && entityViews
                        .map((entry) => resolveEntityView(entry, props.contextEntityViews))
                        .filter((v): v is EntityCustomView => v != null)
                        .find((entry) => entry.key === newPath);
                    const subcollections = getSubcollections(collection);
                    if (customView) {
                        result.push({
                            type: "custom_view",
                            slug: collectionPath,
                            entityId: entityId,
                            path: path + "/" + customView.key,
                            view: customView
                        });
                    } else if (subcollections) {
                        result.push(...getNavigationEntriesFromPath({
                            path: newPath,
                            collections: subcollections,
                            currentFullPath: path,
                            contextEntityViews: props.contextEntityViews
                        }));
                    }
                }
            }
            break;
        }

    }
    return result;
}

function resolveEntityView(entityView: string | EntityCustomView, contextEntityViews?: EntityCustomView[]): EntityCustomView | undefined {
    if (typeof entityView === "string") {
        return contextEntityViews?.find((entry) => entry.key === entityView);
    } else {
        return entityView;
    }
}

import { EntityCollection, EntityReference } from "@rebasepro/types";
import { getCollectionPathsCombinations, removeInitialAndTrailingSlashes } from "./navigation_utils";
import { getSubcollections } from "./resolutions";

export function getParentReferencesFromPath(props: {
    path: string,
    collections: EntityCollection[] | undefined,
    currentFullPath?: string,
}): EntityReference[] {

    const {
        path,
        collections = [],
        currentFullPath,
    } = props;

    const subpaths = removeInitialAndTrailingSlashes(path).split("/");
    const subpathCombinations = getCollectionPathsCombinations(subpaths);

    const result: EntityReference[] = [];
    for (let i = 0; i < subpathCombinations.length; i++) {
        const subpathCombination = subpathCombinations[i];

        const collection: EntityCollection | undefined = collections && collections.find((entry) => entry.slug === subpathCombination);

        // If we find a collection, we add the reference and continue
        if (collection) {
            const collectionPath = currentFullPath && currentFullPath.length > 0
                ? (currentFullPath + "/" + collection.slug) // Use the current full path if provided
                : collection.slug;

            const restOfThePath = removeInitialAndTrailingSlashes(removeInitialAndTrailingSlashes(path).replace(subpathCombination, ""));
            const nextSegments = restOfThePath.length > 0 ? restOfThePath.split("/") : [];
            if (nextSegments.length > 0) {
                const entityId = nextSegments[0];
                const path = collectionPath + "/" + entityId;
                result.push(new EntityReference({ id: entityId, path: collectionPath }));
                if (nextSegments.length > 1) {
                    const newPath = nextSegments.slice(1).join("/");
                    if (!collection) {
                        throw Error("collection not found resolving path: " + collection);
                    }
                    if (getSubcollections(collection).length > 0) {
                        result.push(...getParentReferencesFromPath({
                            path: newPath,
                            collections: getSubcollections(collection),
                            currentFullPath: path
                        }));
                    }
                }
            }
            break;
        }

    }
    return result;
}

import { canCreateEntity, canEditEntity, canDeleteEntity, canReadCollection } from "./permissions";
import { EntityCollection, AuthController, Entity, User, SecurityRule } from "@rebasepro/types";

describe("Permissions Evaluator", () => {

    // ─── Test fixtures ───────────────────────────────────────────────────────────

    const mockUser: User = {
        uid: "user-123",
        email: "test@test.com",
        displayName: "Test User",
        providerId: "test",
        isAnonymous: false,
        photoURL: null,
        roles: ["author", "user"]
    };

    const adminUser: User = {
        uid: "admin-123",
        email: "admin@test.com",
        displayName: "Admin User",
        providerId: "test",
        isAnonymous: false,
        photoURL: null,
        roles: ["admin"]
    };

    const mockAuthController: AuthController<User> = {
        user: mockUser,
        initialLoading: false,
        authLoading: false,
        loginSkipped: false,
        signOut: async () => { },
        getAuthToken: async () => "token",
        setExtra: () => { },
        extra: undefined
    };

    const adminAuthController: AuthController<User> = {
        ...mockAuthController,
        user: adminUser
    };

    const unauthenticatedController: AuthController<User> = {
        ...mockAuthController,
        user: null
    };

    const createMockCollection = (rules?: SecurityRule[]): EntityCollection => ({
        slug: "test",
        name: "Test",
        table: "test",
        properties: {},
        securityRules: rules
    });

    const createMockEntity = (values: Record<string, unknown>): Entity => ({
        id: "entity-123",
        path: "test",
        values,
    });

    // ─── Section 1: Core Defaults ─────────────────────────────────────────────────

    test("1. Implicit fallback: no rules at all returns true (optimistic UI)", () => {
        const collection = createMockCollection();
        expect(canReadCollection(collection, mockAuthController)).toBe(true);
        expect(canCreateEntity(collection, mockAuthController, "test", null)).toBe(true);
        expect(canEditEntity(collection, mockAuthController, "test", null)).toBe(true);
        expect(canDeleteEntity(collection, mockAuthController, "test", null)).toBe(true);
    });

    test("2. Empty rules array [] also returns true", () => {
        const collection = createMockCollection([]);
        expect(canReadCollection(collection, mockAuthController)).toBe(true);
    });

    test("3. Undefined securityRules falls back to true", () => {
        const collection = createMockCollection(undefined);
        expect(canReadCollection(collection, mockAuthController)).toBe(true);
    });

    // ─── Section 2: Operation Filtering ──────────────────────────────────────────

    test("5. Only rules for matching operation are applied", () => {
        const collection = createMockCollection([
            { operation: "insert", access: "public" },
            { operations: ["select", "delete"], roles: ["admin"] }
        ]);
        // Public insert
        expect(canCreateEntity(collection, mockAuthController, "test", null)).toBe(true);
        // No update rule → denied
        expect(canEditEntity(collection, mockAuthController, "test", null)).toBe(false);
        // select/delete need admin → denied for author
        expect(canReadCollection(collection, mockAuthController)).toBe(false);
        expect(canDeleteEntity(collection, mockAuthController, "test", null)).toBe(false);
        // Admin can read and delete
        expect(canReadCollection(collection, adminAuthController)).toBe(true);
        expect(canDeleteEntity(collection, adminAuthController, "test", null)).toBe(true);
    });

    test("6. 'all' operation matches every CRUD action", () => {
        const collection = createMockCollection([
            { operation: "all", roles: ["author"] }
        ]);
        expect(canReadCollection(collection, mockAuthController)).toBe(true);
        expect(canCreateEntity(collection, mockAuthController, "test", null)).toBe(true);
        expect(canEditEntity(collection, mockAuthController, "test", null)).toBe(true);
        expect(canDeleteEntity(collection, mockAuthController, "test", null)).toBe(true);
        // Admin lacks 'author' role
        expect(canReadCollection(collection, adminAuthController)).toBe(false);
    });

    test("7. 'all' rule grants admin all operations; specific 'update' rule also grants author only update", () => {
        const collection = createMockCollection([
            { operation: "all", roles: ["admin"] },
            { operation: "update", roles: ["author"] }
        ]);
        // Admin: all operations
        expect(canReadCollection(collection, adminAuthController)).toBe(true);
        expect(canCreateEntity(collection, adminAuthController, "test", null)).toBe(true);
        expect(canEditEntity(collection, adminAuthController, "test", null)).toBe(true);
        expect(canDeleteEntity(collection, adminAuthController, "test", null)).toBe(true);
        // Author: only update, not read/create/delete
        expect(canEditEntity(collection, mockAuthController, "test", null)).toBe(true);
        expect(canReadCollection(collection, mockAuthController)).toBe(false);
        expect(canCreateEntity(collection, mockAuthController, "test", null)).toBe(false);
        expect(canDeleteEntity(collection, mockAuthController, "test", null)).toBe(false);
    });

    test("8. Unknown operation name in rule is silently ignored", () => {
        const collection = createMockCollection([
            { operation: "read" as any, access: "public" } // "read" not a valid op
        ]);
        // "read" does not match "select", so it is never applied → denied
        expect(canReadCollection(collection, mockAuthController)).toBe(false);
    });

    // ─── Section 3: Role Matching ─────────────────────────────────────────────────

    test("9. Role check: user with matching role is granted", () => {
        const collection = createMockCollection([
            { operation: "all", roles: ["admin", "editor"] }
        ]);
        expect(canReadCollection(collection, mockAuthController)).toBe(false); // author
        expect(canReadCollection(collection, adminAuthController)).toBe(true);  // admin
    });

    test("10. Roles on user are objects {id, name} — correctly mapped to strings", () => {
        const collection = createMockCollection([
            { operation: "select", roles: ["author"] }
        ]);
        // mockUser.roles = [{ id: "author" }, { id: "user" }]
        expect(canReadCollection(collection, mockAuthController)).toBe(true);
    });

    test("11. Empty roles array [] on rule grants access to everyone (public)", () => {
        const collection = createMockCollection([
            { operation: "insert", roles: [] }
        ]);
        expect(canCreateEntity(collection, mockAuthController, "test", null)).toBe(true);
        expect(canCreateEntity(collection, unauthenticatedController, "test", null)).toBe(true);
        expect(canCreateEntity(collection, adminAuthController, "test", null)).toBe(true);
    });

    test("12. Undefined roles on rule grants access to everyone (public)", () => {
        const collection = createMockCollection([
            { operation: "insert" }
        ]);
        expect(canCreateEntity(collection, mockAuthController, "test", null)).toBe(true);
        expect(canCreateEntity(collection, unauthenticatedController, "test", null)).toBe(true);
    });

    test("13. No rules match user's role → implicit deny", () => {
        const collection = createMockCollection([
            { operation: "all", roles: ["admin"] },
            { operation: "all", roles: ["moderator"] }
        ]);
        expect(canReadCollection(collection, mockAuthController)).toBe(false); // author
        expect(canReadCollection(collection, adminAuthController)).toBe(true);
    });

    test("14. 'public' pseudo-role in rule.roles grants access to unauthenticated users", () => {
        const collection = createMockCollection([
            { operation: "select", roles: ["public"] }
        ]);
        expect(canReadCollection(collection, unauthenticatedController)).toBe(true);
        expect(canReadCollection(collection, mockAuthController)).toBe(true);
        expect(canReadCollection(collection, adminAuthController)).toBe(true);
    });

    test("15. Multi-role overlap: user has ['author','user'], rule needs ['editor','user','moderator']", () => {
        const collection = createMockCollection([
            { operation: "insert", roles: ["editor", "user", "moderator"] }
        ]);
        expect(canCreateEntity(collection, mockAuthController, "test", null)).toBe(true); // 'user' matches
        expect(canCreateEntity(collection, adminAuthController, "test", null)).toBe(false); // 'admin' doesn't match
    });

    test("16. Unknown role in rule denies everyone", () => {
        const collection = createMockCollection([
            { operation: "insert", roles: ["unknown_role_xyz"] }
        ]);
        expect(canCreateEntity(collection, mockAuthController, "test", null)).toBe(false);
        expect(canCreateEntity(collection, adminAuthController, "test", null)).toBe(false);
        expect(canCreateEntity(collection, unauthenticatedController, "test", null)).toBe(false);
    });

    // ─── Section 4: Access Shortcuts (access: "public") ───────────────────────────

    test("17. access:'public' bypasses all role and SQL checks immediately", () => {
        const collection = createMockCollection([
            { operation: "select", access: "public" }
        ]);
        expect(canReadCollection(collection, unauthenticatedController)).toBe(true);
        expect(canReadCollection(collection, mockAuthController)).toBe(true);
    });

    // ─── Section 5: Owner Fields ───────────────────────────────────────────────────

    test("18. ownerField: user can edit their own entity, not others'", () => {
        const collection = createMockCollection([
            { operation: "update", ownerField: "user_id" }
        ]);
        const owned = createMockEntity({ user_id: "user-123" });
        const notOwned = createMockEntity({ user_id: "other-user" });
        expect(canEditEntity(collection, mockAuthController, "test", owned)).toBe(true);
        expect(canEditEntity(collection, mockAuthController, "test", notOwned)).toBe(false);
    });

    test("19. ownerField: unauthenticated user (no uid) cannot own any entity", () => {
        const collection = createMockCollection([
            { operation: "update", ownerField: "user_id" }
        ]);
        const entity = createMockEntity({ user_id: "user-123" });
        expect(canEditEntity(collection, unauthenticatedController, "test", entity)).toBe(false);
    });

    test("20. ownerField with null entity is OPTIMISTICALLY enabled (UI has no data yet)", () => {
        // NOTE: This is by design — the UI cannot know ownership before entity exists.
        // The backend will enforce the actual denial. This is documented behavior.
        const collection = createMockCollection([
            { operation: "update", ownerField: "user_uid" }
        ]);
        expect(canEditEntity(collection, mockAuthController, "test", null)).toBe(true);
        // Even unauthenticated! The button shows, backend blocks.
        expect(canEditEntity(collection, unauthenticatedController, "test", null)).toBe(true);
    });

    test("21. ownerField: admin cannot bypass ownerField without an 'admin' role rule", () => {
        const collection = createMockCollection([
            { operation: "update", ownerField: "user_id" }
        ]);
        const adminOwnedEntity = createMockEntity({ user_id: "admin-123" });
        const regularEntity = createMockEntity({ user_id: "user-123" });
        // Admin owns this entity
        expect(canEditEntity(collection, adminAuthController, "test", adminOwnedEntity)).toBe(true);
        // Admin does NOT own this entity — denied!
        expect(canEditEntity(collection, adminAuthController, "test", regularEntity)).toBe(false);
    });

    test("22. ownerField used in a delete rule", () => {
        const collection = createMockCollection([
            { operation: "delete", ownerField: "author_uid" }
        ]);
        const owned = createMockEntity({ author_uid: "user-123" });
        const notOwned = createMockEntity({ author_uid: "someone-else" });
        expect(canDeleteEntity(collection, mockAuthController, "test", owned)).toBe(true);
        expect(canDeleteEntity(collection, mockAuthController, "test", notOwned)).toBe(false);
    });

    // ─── Section 6: SQL AST Evaluation ───────────────────────────────────────────

    test("23. AST: simple equality check", () => {
        const collection = createMockCollection([
            { operation: "update", using: "status = 'published'" }
        ]);
        expect(canEditEntity(collection, mockAuthController, "test", createMockEntity({ status: "published" }))).toBe(true);
        expect(canEditEntity(collection, mockAuthController, "test", createMockEntity({ status: "draft" }))).toBe(false);
    });

    test("24. AST: simple inequality check", () => {
        const collection = createMockCollection([
            { operation: "update", using: "status != 'archived'" }
        ]);
        expect(canEditEntity(collection, mockAuthController, "test", createMockEntity({ status: "draft" }))).toBe(true);
        expect(canEditEntity(collection, mockAuthController, "test", createMockEntity({ status: "archived" }))).toBe(false);
    });

    test("25. AST: current_setting('app.user_id') comparison", () => {
        const collection = createMockCollection([
            { operation: "update", using: "author_uid = current_setting('app.user_id')" }
        ]);
        expect(canEditEntity(collection, mockAuthController, "test", createMockEntity({ author_uid: "user-123" }))).toBe(true);
        expect(canEditEntity(collection, mockAuthController, "test", createMockEntity({ author_uid: "other" }))).toBe(false);
    });

    test("26. AST: current_setting reversed operand order", () => {
        const collection = createMockCollection([
            { operation: "update", using: "current_setting('app.user_id') = author_uid" }
        ]);
        expect(canEditEntity(collection, mockAuthController, "test", createMockEntity({ author_uid: "user-123" }))).toBe(true);
        expect(canEditEntity(collection, mockAuthController, "test", createMockEntity({ author_uid: "other" }))).toBe(false);
    });

    test("27. AST: current_setting with extra whitespace in SQL string", () => {
        const collection = createMockCollection([
            { operation: "update", using: "author_uid=current_setting (  'app.user_id'  )" }
        ]);
        expect(canEditEntity(collection, mockAuthController, "test", createMockEntity({ author_uid: "user-123" }))).toBe(true);
        expect(canEditEntity(collection, mockAuthController, "test", createMockEntity({ author_uid: "other" }))).toBe(false);
    });

    test("28. AST: complex SQL with AND/OR is evaluated by the parser", () => {
        const collection = createMockCollection([
            { operation: "update", using: "status IN ('published', 'draft') AND author_id = current_setting('app.user_id')" }
        ]);
        // IN clause is optimistic true, but AND requires author_id to match user uid
        const mismatchEntity = createMockEntity({ status: "archived", author_id: "someone-else" });
        expect(canEditEntity(collection, mockAuthController, "test", mismatchEntity)).toBe(false);

        // When author_id matches the current user, AND passes
        const matchingEntity = createMockEntity({ status: "published", author_id: "user-123" });
        expect(canEditEntity(collection, mockAuthController, "test", matchingEntity)).toBe(true);
    });

    test("29. AST: null entity ALWAYS optimistically passes SQL evaluation", () => {
        const collection = createMockCollection([
            { operation: "update", using: "status = 'published'" }
        ]);
        // Even a simple parseable SQL works optimistically with null entity
        expect(canEditEntity(collection, mockAuthController, "test", null)).toBe(true);
    });

    // ─── Section 7: using AND withCheck (both must pass) ─────────────────────────

    test("30. using AND withCheck: both independently evaluated, both must pass", () => {
        const collection = createMockCollection([
            { operation: "update", using: "status = 'draft'", withCheck: "title_length > 5" }
        ]);
        // As the entity values are strings, title_length > 5 won't parse cleanly → optimistic true for withCheck
        // status = 'draft' WILL parse and must match
        expect(canEditEntity(collection, mockAuthController, "test", createMockEntity({ status: "draft" }))).toBe(true);
        expect(canEditEntity(collection, mockAuthController, "test", createMockEntity({ status: "published" }))).toBe(false);
    });

    test("31. using passes but withCheck fails → rule denied", () => {
        const collection = createMockCollection([
            { operation: "update", using: "status = 'draft'", withCheck: "visibility = 'public'" }
        ]);
        const entity = createMockEntity({ status: "draft", visibility: "private" });
        // using passes (status is 'draft'), withCheck fails (visibility is 'private')
        expect(canEditEntity(collection, mockAuthController, "test", entity)).toBe(false);
    });

    test("32. withCheck without using: evaluated independently", () => {
        const collection = createMockCollection([
            { operation: "update", withCheck: "status = 'draft'" }
        ]);
        expect(canEditEntity(collection, mockAuthController, "test", createMockEntity({ status: "draft" }))).toBe(true);
        expect(canEditEntity(collection, mockAuthController, "test", createMockEntity({ status: "published" }))).toBe(false);
    });

    // ─── Section 8: Permissive Mode ───────────────────────────────────────────────

    test("33. Two permissive rules = logical OR", () => {
        const collection = createMockCollection([
            { operation: "update", roles: ["admin"], mode: "permissive" },
            { operation: "update", ownerField: "user_id", mode: "permissive" }
        ]);
        const owned = createMockEntity({ user_id: "user-123" });
        const notOwned = createMockEntity({ user_id: "other" });
        // Admin: first rule passes
        expect(canEditEntity(collection, adminAuthController, "test", notOwned)).toBe(true);
        // Author: second rule passes for owned entity
        expect(canEditEntity(collection, mockAuthController, "test", owned)).toBe(true);
        // Author: neither rule passes for unowned entity
        expect(canEditEntity(collection, mockAuthController, "test", notOwned)).toBe(false);
    });

    test("34. A single permissive rule that fails → denied", () => {
        const collection = createMockCollection([
            { operation: "update", roles: ["admin"], mode: "permissive" }
        ]);
        expect(canEditEntity(collection, mockAuthController, "test", null)).toBe(false);
    });

    // ─── Section 9: Restrictive Mode ────────────────────────────────────────────

    test("35. A sole restrictive rule (no permissive) ALWAYS denies", () => {
        // In PostgreSQL: restrictive policies only filter from a permissive base.
        // No permissive base = no access.
        const collection = createMockCollection([
            { operation: "select", mode: "restrictive", using: "status = 'draft'" }
        ]);
        expect(canReadCollection(collection, mockAuthController)).toBe(false);
        expect(canReadCollection(collection, adminAuthController)).toBe(false);
        expect(canReadCollection(collection, unauthenticatedController)).toBe(false);
    });

    test("36. Permissive base + restrictive filter: entity matching restrictor passes", () => {
        const collection = createMockCollection([
            { operation: "update", access: "public", mode: "permissive" },
            { operation: "update", mode: "restrictive", using: "owner_id = current_setting('app.user_id')" }
        ]);
        const owned = createMockEntity({ owner_id: "user-123" });
        const notOwned = createMockEntity({ owner_id: "other-user" });
        expect(canEditEntity(collection, mockAuthController, "test", owned)).toBe(true);
        expect(canEditEntity(collection, mockAuthController, "test", notOwned)).toBe(false);
    });

    test("37. Restrictive rule with role filter: only applies to users with that role", () => {
        // A restrictive rule with roles: ["author"] applies ONLY to users with author role.
        // Users WITHOUT the role are NOT subject to this restrictive rule.
        const collection = createMockCollection([
            { operation: "update", access: "public", mode: "permissive" },
            { operation: "update", roles: ["author"], mode: "restrictive", using: "status = 'published'" }
        ]);
        const draftEntity = createMockEntity({ status: "draft" });
        const publishedEntity = createMockEntity({ status: "published" });

        // Admin has no "author" role → restrictive rule does NOT apply to admin → permissive grants true
        expect(canEditEntity(collection, adminAuthController, "test", draftEntity)).toBe(true);

        // Author HAS "author" role → restrictive rule applies → draft fails restrictive → denied
        expect(canEditEntity(collection, mockAuthController, "test", draftEntity)).toBe(false);

        // Author + published → restrictive passes → permissive grants true
        expect(canEditEntity(collection, mockAuthController, "test", publishedEntity)).toBe(true);
    });

    test("38. Restrictive rule fails immediately, does not continue to permissive", () => {
        const collection = createMockCollection([
            { operation: "insert", roles: ["author"], mode: "permissive" },
            { operation: "insert", roles: ["author"], mode: "restrictive", using: "status = 'draft'" }
        ]);

        // With null entity: evaluateAST("status = 'draft'", ..., null) → true (optimistic)
        // So restrictive passes → permissive also passes → true
        expect(canCreateEntity(collection, mockAuthController, "test", null)).toBe(true);

        // With real entity that fails the restrictive check: immediate deny
        const publishedEntity = createMockEntity({ status: "published" });
        expect(canCreateEntity(collection, mockAuthController, "test", publishedEntity)).toBe(false);

        const draftEntity = createMockEntity({ status: "draft" });
        expect(canCreateEntity(collection, mockAuthController, "test", draftEntity)).toBe(true);
    });

    // ─── Section 10: UI Enablability (null entity = optimistic) ─────────────────

    describe("UI enablability with null entities", () => {

        test("39. Create: role-gated rule → disabled for non-matching user", () => {
            const collection = createMockCollection([{ operation: "insert", roles: ["admin"] }]);
            expect(canCreateEntity(collection, mockAuthController, "test", null)).toBe(false);
            expect(canCreateEntity(collection, adminAuthController, "test", null)).toBe(true);
            expect(canCreateEntity(collection, unauthenticatedController, "test", null)).toBe(false);
        });

        test("40. Edit: role-gated rule → disabled for non-matching user", () => {
            const collection = createMockCollection([{ operation: "update", roles: ["admin"] }]);
            expect(canEditEntity(collection, mockAuthController, "test", null)).toBe(false);
            expect(canEditEntity(collection, adminAuthController, "test", null)).toBe(true);
        });

        test("41. Delete: role-gated rule → disabled for non-matching user", () => {
            const collection = createMockCollection([{ operation: "delete", roles: ["admin"] }]);
            expect(canDeleteEntity(collection, mockAuthController, "test", null)).toBe(false);
            expect(canDeleteEntity(collection, adminAuthController, "test", null)).toBe(true);
        });

        test("42. Read: role-gated rule → disabled for non-matching user", () => {
            const collection = createMockCollection([{ operation: "select", roles: ["admin"] }]);
            expect(canReadCollection(collection, mockAuthController)).toBe(false);
            expect(canReadCollection(collection, adminAuthController)).toBe(true);
        });

        test("43. Create: complex SQL condition → optimistically enabled (null entity)", () => {
            const collection = createMockCollection([
                { operation: "insert", using: "status = 'published' AND id IN (SELECT id FROM drafts)" }
            ]);
            expect(canCreateEntity(collection, mockAuthController, "test", null)).toBe(true);
        });

        test("44. Edit: ownerField with null entity → optimistically enabled", () => {
            const collection = createMockCollection([{ operation: "update", ownerField: "user_uid" }]);
            expect(canEditEntity(collection, mockAuthController, "test", null)).toBe(true);
            // Even unauth! Backend will block.
            expect(canEditEntity(collection, unauthenticatedController, "test", null)).toBe(true);
        });

        test("45. Delete: public rule → everyone enabled", () => {
            const collection = createMockCollection([{ operation: "delete", access: "public" }]);
            expect(canDeleteEntity(collection, unauthenticatedController, "test", null)).toBe(true);
            expect(canDeleteEntity(collection, mockAuthController, "test", null)).toBe(true);
            expect(canDeleteEntity(collection, adminAuthController, "test", null)).toBe(true);
        });

        test("46. Read: sole restrictive rule → disabled for everyone", () => {
            const collection = createMockCollection([
                { operation: "select", mode: "restrictive", using: "status = 'draft'" }
            ]);
            expect(canReadCollection(collection, mockAuthController)).toBe(false);
            expect(canReadCollection(collection, adminAuthController)).toBe(false);
            expect(canReadCollection(collection, unauthenticatedController)).toBe(false);
        });

        test("47. Create: public permissive + data-level restrictive → optimistically true (null entity)", () => {
            const collection = createMockCollection([
                { operation: "insert", access: "public", mode: "permissive" },
                { operation: "insert", mode: "restrictive", using: "status = 'published'" }
            ]);
            // null entity → restrictive evaluateAST returns true (optimistic) → passes → permissive grants → true
            expect(canCreateEntity(collection, mockAuthController, "test", null)).toBe(true);
            expect(canCreateEntity(collection, unauthenticatedController, "test", null)).toBe(true);
        });

        test("48. Create: admin-permissive + author-restrictive → admin enabled, author disabled (null entity)", () => {
            const collection = createMockCollection([
                { operation: "insert", roles: ["admin"], mode: "permissive" },
                { operation: "insert", roles: ["author"], mode: "restrictive", using: "status = 'draft'" }
            ]);
            // Admin: only the permissive rule applies → true
            expect(canCreateEntity(collection, adminAuthController, "test", null)).toBe(true);
            // Author: restrictive rule applies + passes (null-optimistic), BUT no permissive rule → false
            expect(canCreateEntity(collection, mockAuthController, "test", null)).toBe(false);
            // Unauth: no rules apply → false
            expect(canCreateEntity(collection, unauthenticatedController, "test", null)).toBe(false);
        });

        test("49. Edit: any rule without matching op → disabled", () => {
            const collection = createMockCollection([
                { operation: "insert", access: "public" }
            ]);
            expect(canEditEntity(collection, mockAuthController, "test", null)).toBe(false);
            expect(canEditEntity(collection, unauthenticatedController, "test", null)).toBe(false);
        });

        test("50. All CRUD disabled when all rules have unknown role", () => {
            const collection = createMockCollection([
                { operation: "all", roles: ["nonexistent_role"] }
            ]);
            expect(canCreateEntity(collection, mockAuthController, "test", null)).toBe(false);
            expect(canEditEntity(collection, mockAuthController, "test", null)).toBe(false);
            expect(canDeleteEntity(collection, mockAuthController, "test", null)).toBe(false);
            expect(canReadCollection(collection, mockAuthController)).toBe(false);
        });
    });

    // ─── Section 11: Multi-Rule Combinations ──────────────────────────────────────

    describe("Multi-rule combinations", () => {

        test("51. Admin OR author permissive → both can create, unauth cannot", () => {
            const collection = createMockCollection([
                { operation: "insert", roles: ["admin"], mode: "permissive" },
                { operation: "insert", roles: ["author"], mode: "permissive" }
            ]);
            expect(canCreateEntity(collection, adminAuthController, "test", null)).toBe(true);
            expect(canCreateEntity(collection, mockAuthController, "test", null)).toBe(true);
            expect(canCreateEntity(collection, unauthenticatedController, "test", null)).toBe(false);
        });

        test("52. Admin can delete anything, author only their own entities", () => {
            const collection = createMockCollection([
                { operation: "delete", roles: ["admin"] },
                { operation: "delete", ownerField: "author_uid" }
            ]);
            const authorEntity = createMockEntity({ author_uid: "user-123" });
            const hackerEntity = createMockEntity({ author_uid: "hacker" });

            expect(canDeleteEntity(collection, adminAuthController, "test", authorEntity)).toBe(true);
            expect(canDeleteEntity(collection, adminAuthController, "test", hackerEntity)).toBe(true);
            expect(canDeleteEntity(collection, mockAuthController, "test", authorEntity)).toBe(true);
            expect(canDeleteEntity(collection, mockAuthController, "test", hackerEntity)).toBe(false);
        });

        test("53. Role OR owner combinded: admin by role, others by ownership", () => {
            const collection = createMockCollection([
                { operation: "update", roles: ["admin"], mode: "permissive" },
                { operation: "update", ownerField: "user_id", mode: "permissive" }
            ]);
            const owned = createMockEntity({ user_id: "user-123" });
            const notOwned = createMockEntity({ user_id: "other" });

            expect(canEditEntity(collection, adminAuthController, "test", notOwned)).toBe(true);
            expect(canEditEntity(collection, mockAuthController, "test", owned)).toBe(true);
            expect(canEditEntity(collection, mockAuthController, "test", notOwned)).toBe(false);
        });

        test("54. 'all' rule permissive base + specific delete restrictive", () => {
            const collection = createMockCollection([
                { operation: "all", access: "public", mode: "permissive" },
                { operation: "delete", mode: "restrictive", using: "is_deletable = 'true'" }
            ]);
            const deletable = createMockEntity({ is_deletable: "true" });
            const notDeletable = createMockEntity({ is_deletable: "false" });

            // Reading still works (only 'all' permissive applies to select)
            expect(canReadCollection(collection, mockAuthController)).toBe(true);
            // Deletable entity passes restrictive
            expect(canDeleteEntity(collection, mockAuthController, "test", deletable)).toBe(true);
            // Non-deletable entity fails restrictive
            expect(canDeleteEntity(collection, mockAuthController, "test", notDeletable)).toBe(false);
        });

        test("55. Three-user-role scenario: platform role hierarchy", () => {
            const editorUser: User = {
                uid: "editor-1", email: "e@e.com", displayName: "Ed",
                providerId: "test", isAnonymous: false, photoURL: null,
                roles: ["editor"]
            };
            const editorAuth: AuthController<any> = { ...mockAuthController, user: editorUser };

            const collection = createMockCollection([
                { operation: "select", roles: ["admin", "editor", "author"] }, // read all three
                { operation: "insert", roles: ["admin", "editor"] },           // create admin/editor
                { operation: "update", roles: ["admin"] },                     // edit admin only
                { operation: "delete", roles: ["admin"] }                      // delete admin only
            ]);

            // Admin
            expect(canReadCollection(collection, adminAuthController)).toBe(true);
            expect(canCreateEntity(collection, adminAuthController, "test", null)).toBe(true);
            expect(canEditEntity(collection, adminAuthController, "test", null)).toBe(true);
            expect(canDeleteEntity(collection, adminAuthController, "test", null)).toBe(true);
            // Editor
            expect(canReadCollection(collection, editorAuth)).toBe(true);
            expect(canCreateEntity(collection, editorAuth, "test", null)).toBe(true);
            expect(canEditEntity(collection, editorAuth, "test", null)).toBe(false);
            expect(canDeleteEntity(collection, editorAuth, "test", null)).toBe(false);
            // Author (mockUser)
            expect(canReadCollection(collection, mockAuthController)).toBe(true);
            expect(canCreateEntity(collection, mockAuthController, "test", null)).toBe(false);
            expect(canEditEntity(collection, mockAuthController, "test", null)).toBe(false);
            expect(canDeleteEntity(collection, mockAuthController, "test", null)).toBe(false);
            // Unauth
            expect(canReadCollection(collection, unauthenticatedController)).toBe(false);
        });

        test("56. Publication workflow: draft/review/published state machine", () => {
            const collection = createMockCollection([
                // Anyone can read published content
                { operation: "select", using: "status = 'published'" },
                // Authors can only create drafts
                { operation: "insert", roles: ["author"], withCheck: "status = 'draft'" },
                // Authors can only edit their own draft or review content
                { operation: "update", roles: ["author"], ownerField: "author_id", using: "status != 'published'" },
                // Editors can move anything to/from review/published
                { operation: "update", roles: ["editor"] },
                // Only admins can delete
                { operation: "delete", roles: ["admin"] }
            ]);

            const draft = createMockEntity({ status: "draft", author_id: "user-123" });
            const published = createMockEntity({ status: "published", author_id: "user-123" });
            const othersDraft = createMockEntity({ status: "draft", author_id: "someone-else" });

            // Author can create (null entity, optimistic)
            expect(canCreateEntity(collection, mockAuthController, "test", null)).toBe(true);
            // Author can edit their own draft
            expect(canEditEntity(collection, mockAuthController, "test", draft)).toBe(true);
            // Author CANNOT edit their own published content (status = 'published' fails using)
            expect(canEditEntity(collection, mockAuthController, "test", published)).toBe(false);
            // Author CANNOT edit others' drafts
            expect(canEditEntity(collection, mockAuthController, "test", othersDraft)).toBe(false);
            // Author CANNOT delete
            expect(canDeleteEntity(collection, mockAuthController, "test", null)).toBe(false);
            // Admin CAN delete
            expect(canDeleteEntity(collection, adminAuthController, "test", null)).toBe(true);
        });

        test("57. Unauthenticated user: ownerField rule denies, SQL rule without roles still grants", () => {
            // Three update rules, each independently permissive (OR logic).
            // Rule 1: admin-only role → unauthenticated lacks it → filtered out
            // Rule 2: ownerField user_id → entity.user_id = null, auth.uid = undefined → null !== undefined → fails
            // Rule 3: using status = 'draft' → passes, has no role restriction → grants true
            // Result: true (rule 3 wins)
            const collection = createMockCollection([
                { operation: "update", roles: ["admin"] },
                { operation: "update", ownerField: "user_id" },
                { operation: "update", using: "status = 'draft'" }
            ]);
            const draftOwned = createMockEntity({ user_id: null, status: "draft" });
            expect(canEditEntity(collection, unauthenticatedController, "test", draftOwned)).toBe(true);

            // To actually restrict unauthenticated users, the 3rd rule needs a role guard:
            const restrictedCollection = createMockCollection([
                { operation: "update", roles: ["admin"] },
                { operation: "update", ownerField: "user_id" },
                { operation: "update", roles: ["author"], using: "status = 'draft'" }
            ]);
            expect(canEditEntity(collection, unauthenticatedController, "test", draftOwned)).toBe(true);
            expect(canEditEntity(restrictedCollection, unauthenticatedController, "test", draftOwned)).toBe(false);
        });

        test("58. Missing authController ('blankAuth') handled gracefully", () => {
            const collection = createMockCollection([{ operation: "insert", roles: ["admin"] }]);
            const blankAuth = { user: null } as any;
            expect(canCreateEntity(collection, blankAuth, "test", null)).toBe(false);
        });

        test("59. SQL injection-like string in 'using' is safely treated as unparseable → optimistic", () => {
            const collection = createMockCollection([
                { operation: "update", using: "\"); DROP TABLE users; --" }
            ]);
            // Frontend never executes SQL, just parses. Malformed string → optimistic pass
            expect(canEditEntity(collection, mockAuthController, "test", null)).toBe(true);
        });
    });
});

import { AuthController, Entity, EntityCollection, isPostgresCollection, SecurityRule, User } from "@rebasepro/types";

function evaluateAST(sqlString: string, auth: AuthController, entity: Entity<Record<string, unknown>> | null): boolean {
    // This is a client-side SQL evaluator used *only* for optimistic UI updates.
    // It parses basic AND / OR statements to evaluate RLS without backend roundtrips.
    if (!entity) return true;

    // 1. Clean outer parentheses
    let cleanedSQL = sqlString.trim();
    while (cleanedSQL.startsWith('(') && cleanedSQL.endsWith(')')) {
        let openCount = 0;
        let isEnclosing = true;
        for (let i = 0; i < cleanedSQL.length - 1; i++) {
            if (cleanedSQL[i] === '(') openCount++;
            else if (cleanedSQL[i] === ')') openCount--;
            if (openCount === 0) {
                isEnclosing = false;
                break;
            }
        }
        if (isEnclosing) {
            cleanedSQL = cleanedSQL.substring(1, cleanedSQL.length - 1).trim();
        } else {
            break;
        }
    }

    // 2. Split top-level OR / AND
    const splitByTopLevel = (str: string, delimiter: string) => {
        const parts: string[] = [];
        let current = "";
        let openCount = 0;
        let i = 0;
        while (i < str.length) {
            if (str[i] === '(') openCount++;
            else if (str[i] === ')') openCount--;

            if (openCount === 0 && str.substring(i).toUpperCase().startsWith(delimiter)) {
                parts.push(current);
                current = "";
                i += delimiter.length;
            } else {
                current += str[i];
                i++;
            }
        }
        parts.push(current);
        return parts;
    };

    const orParts = splitByTopLevel(cleanedSQL, " OR ");
    if (orParts.length > 1) {
        return orParts.some(part => evaluateAST(part, auth, entity));
    }

    const andParts = splitByTopLevel(cleanedSQL, " AND ");
    if (andParts.length > 1) {
        return andParts.every(part => evaluateAST(part, auth, entity));
    }

    const upperSQL = cleanedSQL.toUpperCase();

    // 3. Fallback for unparseable complex queries
    if (upperSQL.includes(" IN ") || upperSQL.includes(" EXISTS ")) {
        return true;
    }

    // 4. Role array checks
    // Pattern: `string_to_array(auth.roles(), ',') && ARRAY['admin', 'editor']`
    const roleIntersectMatch = cleanedSQL.match(/string_to_array\s*\(\s*auth\.roles\(\)\s*,\s*','\s*\)\s*&&\s*ARRAY\[(.*?)\]/i);
    if (roleIntersectMatch && roleIntersectMatch[1]) {
        const requiredRoles = roleIntersectMatch[1].split(',').map(r => r.trim().replace(/'/g, ''));
        const userRoles = auth.user?.roles || [];
        return requiredRoles.some(r => userRoles.includes(r));
    }

    // Pattern: `string_to_array(auth.roles(), ',') @> ARRAY['admin']`
    const roleContainMatch = cleanedSQL.match(/string_to_array\s*\(\s*auth\.roles\(\)\s*,\s*','\s*\)\s*@>\s*ARRAY\[(.*?)\]/i);
    if (roleContainMatch && roleContainMatch[1]) {
        const requiredRoles = roleContainMatch[1].split(',').map(r => r.trim().replace(/'/g, ''));
        const userRoles = auth.user?.roles || [];
        return requiredRoles.every(r => userRoles.includes(r));
    }

    // 5. Existing ID patterns
    const pattern1 = new RegExp(`^\\{?([a-zA-Z0-9_]+)\\}?\\s*=\\s*(?:current_setting\\s*\\(\\s*'app\\.user_id'\\s*\\)|auth\\.uid\\(\\))`);
    const pattern2 = new RegExp(`^(?:current_setting\\s*\\(\\s*'app\\.user_id'\\s*\\)|auth\\.uid\\(\\))\\s*=\\s*\\{?([a-zA-Z0-9_]+)\\}?`);

    const match1 = cleanedSQL.match(pattern1);
    if (match1 && match1[1]) {
        return entity.values[match1[1]] === auth.user?.uid;
    }

    const match2 = cleanedSQL.match(pattern2);
    if (match2 && match2[1]) {
        return entity.values[match2[1]] === auth.user?.uid;
    }

    // 6. Simple equality
    // Pattern: `field = 'value'` or `{field} != 'value'`
    const simpleEqualityMatch = cleanedSQL.match(/^\{?([\w_]+)\}?\s*(=|!=)\s*'([^']+)'$/i);
    if (simpleEqualityMatch) {
        const field = simpleEqualityMatch[1];
        const operator = simpleEqualityMatch[2];
        const value = simpleEqualityMatch[3];
        const entityValue = entity.values[field];
        if (operator === "=") return entityValue === value;
        if (operator === "!=") return entityValue !== value;
    }

    return true; // Optimistic fallback for anything else
}

function evaluateRule(rule: SecurityRule, auth: AuthController, entity: Entity<Record<string, unknown>> | null): boolean {

    if (rule.access === "public") return true;

    if (rule.ownerField) {
        if (!entity) {
            // null entity: optimistic — we can't evaluate ownership without data
            // Fall through to SQL checks below (if any). If none, will return true.
        } else {
            // Entity present: strictly check ownership. Fail immediately if mismatch.
            if (entity.values[rule.ownerField] !== auth.user?.uid) return false;
        }
    }

    // In PostgreSQL RLS, USING and WITH CHECK have distinct semantics:
    // USING applies to existing rows (SELECT/UPDATE/DELETE read phase)
    // WITH CHECK applies to new/modified values (INSERT/UPDATE write phase)
    // Both must pass. We evaluate both independently.
    if (rule.using && !evaluateAST(rule.using, auth, entity)) return false;
    if (rule.withCheck && !evaluateAST(rule.withCheck, auth, entity)) return false;

    return true;
}

function checkOperation(
    collection: EntityCollection<Record<string, unknown>>,
    authController: AuthController<User>,
    entity: Entity<Record<string, unknown>> | null,
    targetOperation: "select" | "insert" | "update" | "delete"
): boolean {
    const securityRules = isPostgresCollection(collection) ? collection.securityRules : undefined;
    if (!securityRules || securityRules.length === 0) {
        // According to our plan: Postgres RLS implicitly denies if enabled without rules.
        // But for Rebase we default to true if securityRules is undefined,
        // so as not to break everything without rules. Let's assume true for now.
        return true;
    }

    const applicableRules = securityRules.filter((r: SecurityRule) =>
        r.operation === targetOperation ||
        r.operation === "all" ||
        r.operations?.includes(targetOperation) ||
        r.operations?.includes("all")
    );

    if (applicableRules.length === 0) return false;

    // In Postgres, policies ONLY apply if the user matching the targeted roles.
    const userRoleIds = authController.user?.roles ?? [];
    const userRoles = [...userRoleIds, "public"];
    const roleApplicableRules = applicableRules.filter(rule => {
        if (!rule.roles || rule.roles.length === 0) return true; // APPLIES TO PUBLIC
        return rule.roles.some((r: string) => userRoles.includes(r));
    });

    // If no rules apply to this user's roles, the operation is implicitly denied.
    if (roleApplicableRules.length === 0) return false;

    let grantedByPermissive = false;
    let deniedByRestrictive = false;

    for (const rule of roleApplicableRules) {
        const mode = rule.mode || "permissive";
        const passed = evaluateRule(rule, authController, entity);

        if (mode === "restrictive" && !passed) {
            deniedByRestrictive = true;
            break; // Immediate deny
        }

        if (mode === "permissive" && passed) {
            grantedByPermissive = true;
        }
    }

    if (deniedByRestrictive) return false;

    const hasPermissive = roleApplicableRules.some(r => (r.mode || "permissive") === "permissive");
    if (hasPermissive) {
        return grantedByPermissive;
    } else {
        return false;
    }
}

export function canReadCollection<M extends Record<string, unknown>, USER extends User>
    (
        collection: EntityCollection<M>,
        authController: AuthController<USER>
    ): boolean {
    return checkOperation(collection, authController, null, "select");
}

export function canEditEntity<M extends Record<string, unknown>, USER extends User>
    (
        collection: EntityCollection<M>,
        authController: AuthController<USER>,
        path: string,
        entity: Entity<M> | null
    ): boolean {
    return checkOperation(collection, authController, entity, "update");
}

export function canCreateEntity<M extends Record<string, unknown>, USER extends User>
    (
        collection: EntityCollection<M>,
        authController: AuthController<USER>,
        path: string,
        entity: Entity<M> | null
    ): boolean {
    return checkOperation(collection, authController, entity, "insert");
}

export function canDeleteEntity<M extends Record<string, unknown>, USER extends User>
    (
        collection: EntityCollection<M>,
        authController: AuthController<USER>,
        path: string,
        entity: Entity<M> | null
    ): boolean {
    return checkOperation(collection, authController, entity, "delete");
}

import { EntityCollection, isPostgresCollection, PostgresCollection, Property, Relation } from "@rebasepro/types";
import { toSnakeCase } from "@rebasepro/utils";
import { generateForeignKeyName } from "@rebasepro/utils";

export function sanitizeRelation(relation: Partial<Relation>, sourceCollection: PostgresCollection): Relation {
    if (!relation.target) {
        throw new Error("Relation is missing a `target` collection.");
    }
    const targetCollection = relation.target();

    const newRelation: Partial<Relation> = { ...relation };

    // 1. Default relationName from target collection slug
    if (!newRelation.relationName) {
        newRelation.relationName = toSnakeCase(targetCollection.slug);
    }

    // 2. Infer or default direction if absent
    if (!newRelation.direction) {
        if (newRelation.foreignKeyOnTarget) newRelation.direction = "inverse";
        else if (newRelation.through) newRelation.direction = "owning";
        else if (newRelation.cardinality === "many") newRelation.direction = "inverse"; // Default has-many to be inverse
        else newRelation.direction = "owning"; // Default all others to owning
    }

    // Do not default keys if a custom joinPath is provided; it's an advanced override.
    if (!newRelation.joinPath) {
        const sourceName = toSnakeCase(sourceCollection.slug ?? sourceCollection.name);

        // 3. Default keys based on the relation type (cardinality and direction)
        if (newRelation.cardinality === "one" && newRelation.direction === "owning") {
            // Belongs-to / many-to-one
            if (!newRelation.localKey) {
                newRelation.localKey = generateForeignKeyName(newRelation.relationName);
            }
        } else if (newRelation.cardinality === "one" && newRelation.direction === "inverse") {
            // Inverse one-to-one: the foreign key is on the target table pointing back to this collection
            if (!newRelation.foreignKeyOnTarget) {
                // First, try to find the corresponding owning relation's localKey on the target collection
                let foundForeignKey = false;

                try {
                    // Look for an owning relation on the target that points back to this collection
                    const targetRelations = (targetCollection as PostgresCollection).relations || [];
                    for (const targetRel of targetRelations) {
                        if (targetRel.direction === "owning" &&
                            targetRel.cardinality === "one" &&
                            targetRel.localKey) {
                            try {
                                const targetRelTarget = targetRel.target();
                                if (targetRelTarget.slug === sourceCollection.slug) {
                                    // Found the corresponding owning relation, use its localKey
                                    newRelation.foreignKeyOnTarget = targetRel.localKey;
                                    foundForeignKey = true;
                                    break;
                                }
                            } catch (e) {
                                // Continue looking if we can't resolve this target
                                continue;
                            }
                        }
                    }
                } catch (e) {
                    // If we can't inspect the target collection, fall back to naming convention
                }

                // If we couldn't find an explicit foreign key, fall back to naming convention
                if (!foundForeignKey) {
                    const keyPrefix = newRelation.inverseRelationName
                        ? toSnakeCase(newRelation.inverseRelationName)
                        : sourceName;
                    newRelation.foreignKeyOnTarget = generateForeignKeyName(keyPrefix);
                }
            }
        } else if (newRelation.cardinality === "many" && newRelation.direction === "inverse") {
            // This could be either one-to-many or many-to-many inverse relation
            // We need to check if there's a corresponding owning many-to-many relation

            let isManyToManyInverse = false;

            // Try to determine if this is a many-to-many inverse relation
            if (newRelation.inverseRelationName && !newRelation.foreignKeyOnTarget) {
                try {
                    // Look for a corresponding owning many-to-many relation on the target collection.
                    // Note: we intentionally do NOT require `through` here because the raw (unsanitized)
                    // relations won't have `through` populated yet — sanitizeRelation fills it in later.
                    // `cardinality: "many" + direction: "owning"` is sufficient to identify owning M2M.
                    const targetRelations = (targetCollection as PostgresCollection).relations || [];
                    for (const targetRel of targetRelations) {
                        if (targetRel.cardinality === "many" &&
                            (targetRel.direction === "owning" || !targetRel.direction) &&
                            (targetRel.relationName === newRelation.inverseRelationName)) {
                            // Found a corresponding owning many-to-many relation
                            isManyToManyInverse = true;
                            break;
                        }
                    }
                } catch (e) {
                    // If we can't inspect the target collection, assume one-to-many
                }
            }

            // Only add foreignKeyOnTarget for one-to-many inverse relations
            if (!isManyToManyInverse && !newRelation.foreignKeyOnTarget) {
                newRelation.foreignKeyOnTarget = generateForeignKeyName(sourceName);
            }
        } else if (newRelation.cardinality === "many" && newRelation.direction === "owning") {

            // Many-to-many via junction table
            const sourceTableName = getTableName(sourceCollection);
            const targetTableName = getTableName(targetCollection);

            newRelation.through = {
                table: newRelation.through?.table ?? [sourceTableName, targetTableName].sort().join("_"),
                sourceColumn: newRelation.through?.sourceColumn ?? generateForeignKeyName(sourceName),
                targetColumn: newRelation.through?.targetColumn ?? generateForeignKeyName(newRelation.relationName),
            };
        }
    }

    // 4. Basic validation to catch configuration errors early
    if (newRelation.cardinality === "one" && newRelation.direction === "owning" && !newRelation.localKey && !newRelation.joinPath) {
        throw new Error(`Configuration Error in relation from '${sourceCollection.name}': An 'owning' one-to-one relation requires a 'localKey'. Check the relation config for '${newRelation.relationName}'`);
    }
    if (newRelation.cardinality === "one" && newRelation.direction === "inverse" && !newRelation.foreignKeyOnTarget && !newRelation.joinPath) {
        throw new Error(`Configuration Error in relation from '${sourceCollection.name}': An 'inverse' one-to-one relation requires a 'foreignKeyOnTarget'. Check the relation config for '${newRelation.relationName}'`);
    }
    if (newRelation.cardinality === "many" && newRelation.direction === "inverse" && !newRelation.foreignKeyOnTarget && !newRelation.joinPath && !newRelation.inverseRelationName) {
        throw new Error(`Configuration Error in relation from '${sourceCollection.name}': An 'inverse' one-to-many relation requires a 'foreignKeyOnTarget'. Check the relation config for '${newRelation.relationName}'`);
    }

    return newRelation as Relation;
}

export function resolveCollectionRelations(
    collection: PostgresCollection,
): Record<string, Relation> {
    const relations: Record<string, Relation> = {};

    // 1. Process explicit relations from the new `relations` field
    if (collection.relations) {
        collection.relations.forEach((relation) => {
            const normalizedRelation = sanitizeRelation(relation, collection);
            const relationKey = normalizedRelation.relationName;
            if (relationKey) {
                relations[relationKey] = normalizedRelation;
            }
        });
    }

    // 2. Process properties of type "relation"
    if (collection.properties) {
        Object.entries(collection.properties).forEach(([propKey, prop]) => {
            const relation = resolvePropertyRelation({
                propertyKey: propKey,
                property: prop as Property,
                sourceCollection: collection
            });
            if (relation) {
                // Use property name as relation key if not already defined
                if (!relations[propKey]) {
                    // FIX: Set relationName to propKey if not defined, before normalizing
                    if (!relation.relationName) {
                        relation.relationName = propKey;
                    }
                    relations[propKey] = sanitizeRelation(relation, collection); // Already normalized in collection.relations
                }
            }
        });
    }

    return relations;
}

export function resolvePropertyRelation({
    propertyKey,
    property,
    sourceCollection
}: {
    propertyKey: string;
    property: Property;
    sourceCollection: PostgresCollection;
}): Relation | undefined {
    if (property.type !== "relation") return undefined;

    const relation = (sourceCollection.relations ?? []).find((rel: Relation) => rel.relationName === property.relationName)
    if (!relation) {
        console.warn(`Unrecognized relation format for property '${propertyKey}' in collection '${sourceCollection.slug}'`);
        return undefined;
    }

    return relation as Relation;

}

export function getTableName(collection: EntityCollection): string {
    if (isPostgresCollection(collection)) {
        return collection.table ?? toSnakeCase(collection.slug) ?? toSnakeCase(collection.name);
    }
    return toSnakeCase(collection.slug) ?? toSnakeCase(collection.name);
}

export function getTableVarName(tableName: string): string {
    return tableName.replace(/_([a-z])/g, (_, char) => char.toUpperCase());
}

export function getEnumVarName(tableName: string, propName: string): string {
    const tableVar = getTableVarName(tableName);
    const propVar = propName.charAt(0).toUpperCase() + propName.slice(1);
    return `${tableVar}${propVar}`;
}

export function getColumnName(fullColumn: string): string {
    return fullColumn.includes(".") ? fullColumn.split(".").pop()! : fullColumn;
}

import {
    ArrayProperty,
    AuthController,
    EntityCollection,
    EnumValueConfig,
    EnumValues,
    NumberProperty,
    Properties,
    Property,
    Relation,
    RelationProperty,
    StringProperty,
    isPostgresCollection,
    isFirebaseCollection,
} from "@rebasepro/types";

type PropertyConfig = { property: unknown; [key: string]: unknown };
import { isPropertyBuilder } from "./entities";
import { enumToObjectEntries } from "./enums";
import { DEFAULT_ONE_OF_TYPE } from "./common";
import { isDefaultFieldConfigId } from "@rebasepro/utils";
import { getIn, mergeDeep } from "@rebasepro/utils";

/**
 * Resolve property builders, enums and arrays.
 */

export type ResolvePropertyProps<M extends Record<string, unknown> = Record<string, unknown>> = {
    property: Property
    propertyKey?: string,
    values?: Partial<M>,
    previousValues?: Partial<M>,
    path?: string,
    entityId?: string | number,
    index?: number,
    propertyConfigs?: Record<string, PropertyConfig>;
    ignoreMissingFields?: boolean;
    authController: AuthController;
}

export function resolveProperty<M extends Record<string, unknown> = Record<string, unknown>>(props: ResolvePropertyProps<M>): Property | null {

    const {
        property,
        ignoreMissingFields = false,
        ...rest
    } = props;

    let resultProperty: Property;

    if (isPropertyBuilder(property)) {
        const path = rest.path;
        if (!path)
            throw Error("Trying to resolve a property builder without specifying the entity path");

        const usedPropertyValue = rest.propertyKey ? getIn(rest.values, rest.propertyKey) : undefined;
        const dynamicProps = property.dynamicProps?.({
            ...rest,
            path,
            propertyValue: usedPropertyValue,
            values: rest.values ?? {},
            previousValues: rest.previousValues ?? rest.values ?? {}
        });
        resultProperty = mergeDeep(property, dynamicProps ?? {});
    } else {
        resultProperty = property as Property;
    }

    // Apply dynamic properties if they exist
    if (resultProperty.dynamicProps) {
        const path = rest.path;
        if (!path)
            throw Error("Trying to resolve dynamicProps without specifying the entity path");

        const usedPropertyValue = rest.propertyKey ? getIn(rest.values, rest.propertyKey) : undefined;
        const dynamicPropsResult = resultProperty.dynamicProps({
            ...rest,
            path,
            propertyValue: usedPropertyValue,
            values: rest.values ?? {},
            previousValues: rest.previousValues ?? rest.values ?? {}
        });

        if (dynamicPropsResult) {
            resultProperty = mergeDeep(resultProperty, dynamicPropsResult);
        }
    }

    let resolvedProperty: Property | null;

    if (resultProperty?.type === "map" && resultProperty.properties) {
        const properties = resolveProperties({
            ignoreMissingFields,
            ...rest,
            properties: resultProperty.properties,
        });
        resolvedProperty = {
            ...resultProperty,
            properties
        } as Property;
    } else if (resultProperty?.type === "array") {
        resolvedProperty = resultProperty;
    } else if ((resultProperty?.type === "string" || resultProperty?.type === "number") && resultProperty.enum) {
        resolvedProperty = resolvePropertyEnum(resultProperty);
    } else {
        resolvedProperty = resultProperty;
    }

    if (resolvedProperty?.propertyConfig && !isDefaultFieldConfigId(resolvedProperty.propertyConfig)) {
        const cmsFields = rest.propertyConfigs;
        if (!cmsFields && !ignoreMissingFields) {
            throw Error(`Trying to resolve a property with key '${resolvedProperty.propertyConfig}' that inherits from a custom property config but no custom property configs were provided. Use the property 'propertyConfigs' in your app config to provide them`);
        }
        const customField: PropertyConfig | undefined = cmsFields?.[resolvedProperty.propertyConfig];
        if (!customField) {
            console.warn(`Trying to resolve a property with key '${resolvedProperty.propertyConfig}' that inherits from a custom property config but no custom property config with that key was found. Check the 'propertyConfigs' in your app config`)
            return resolvedProperty;
        }
        if (customField.property) {
            const { propertyConfig: _unused, ...restConfigProperty } = customField.property;
            const customFieldProperty = resolveProperty({
                property: { name: "", ...restConfigProperty } as Property,
                ignoreMissingFields,
                ...rest
            });
            if (customFieldProperty) {
                resolvedProperty = mergeDeep(customFieldProperty, resolvedProperty);
            }
        }

    }

    return resolvedProperty;
}

export function resolveRelationProperty(property: RelationProperty, relations: Relation[]) {
    // find the relation by name
    const relation = relations.find((rel) => rel.relationName === property.relationName);
    if (!relation) {
        throw Error(`Relation ${property.relationName} not found`);
    }
    return {
        ...property,
        relation: relation
    } as RelationProperty;

}

/**
 * Resolve enum aliases for a string or number property
 * @param property
 */
export function resolvePropertyEnum(property: StringProperty | NumberProperty): StringProperty | NumberProperty {
    if (typeof property.enum === "object") {
        return {
            ...property,
            enum: enumToObjectEntries(property.enum)?.filter((value) => value && (value.id || value.id === 0) && value.label) ?? [],
        };
    }
    return property as StringProperty | NumberProperty;
}

/**
 * Resolve enums and arrays for properties
 * @param properties
 * @param value
 */
export function resolveProperties<M extends Record<string, unknown>>({
    propertyKey,
    properties,
    ignoreMissingFields,
    ...props
}: {
    propertyKey?: string,
    properties: Properties,
    values?: Partial<M>,
    previousValues?: Partial<M>,
    path?: string,
    entityId?: string | number,
    index?: number,
    propertyConfigs?: Record<string, PropertyConfig>;
    ignoreMissingFields?: boolean;
    authController: AuthController;
}): Properties {
    return Object.entries<Property>(properties as Record<string, Property>)
        .map(([key, property]) => {
            const childResolvedProperty = resolveProperty({
                propertyKey: propertyKey ? `${propertyKey}.${key}` : undefined,
                property: property,
                ignoreMissingFields,
                ...props
            });
            if (!childResolvedProperty) return {};
            return {
                [key]: childResolvedProperty
            };
        })
        .filter((a) => a !== null)
        .reduce((a, b) => ({ ...a, ...b }), {}) as Properties;
}

export function resolveArrayProperties<M>({
    propertyKey,
    property,
    ignoreMissingFields = false,
    ...props
}: {
    propertyKey?: string,
    property: ArrayProperty,
    values?: Partial<M>,
    previousValues?: Partial<M>,
    path?: string,
    entityId?: string | number,
    index?: number,
    propertyConfigs?: Record<string, PropertyConfig>;
    ignoreMissingFields?: boolean;
    authController: AuthController;
}): Property[] {
    const propertyValue = propertyKey ? getIn(props.values, propertyKey) : undefined;

    if (property.of) {
        if (Array.isArray(property.of)) {
            return property.of.map((p, index) => {
                return resolveProperty({
                    propertyKey: `${propertyKey}.${index}`,
                    property: p as Property,
                    ignoreMissingFields,
                    ...props,
                    index,
                });
            }) as Property[];
        } else {
            const of = property.of;
            const resolvedProperties = getArrayResolvedProperties({
                propertyValue,
                propertyKey,
                property,
                ignoreMissingFields,
                ...props
            });
            const {
                values,
                previousValues,
                ...rest
            } = props;
            const ofProperty = resolveProperty({ // we don't want to pass the values of the parent entity
                property: of,
                ignoreMissingFields,
                ...rest
            });
            if (!ofProperty && !ignoreMissingFields)
                throw Error("When using a property builder as the 'of' prop of an ArrayProperty, you must return a valid child property")
            return resolvedProperties;
        }
    } else if (property.oneOf) {
        const typeField = property.oneOf?.typeField ?? DEFAULT_ONE_OF_TYPE;
        const resolvedProperties: Property[] = Array.isArray(propertyValue)
            ? propertyValue.map((v, index) => {
                const type = v && v[typeField];
                const childProperty = property.oneOf?.properties[type];
                if (!type || !childProperty) return null;
                return resolveProperty({
                    propertyKey: `${propertyKey}.${index}`,
                    property: childProperty,
                    ignoreMissingFields,
                    ...props
                });
            }).filter(e => Boolean(e)) as Property[]
            : [];
        return resolvedProperties;
    } else if (!("Field" in property && property.Field)) {
        throw Error(`The array property (${propertyKey}) needs to declare an 'of' or a 'oneOf' property, or provide a custom \`Field\` component`);
    } else {
        return [];
    }

}

export function getArrayResolvedProperties({
    propertyKey,
    propertyValue,
    property,
    ...props
}: {
    propertyValue: unknown,
    propertyKey?: string,
    property: ArrayProperty,
    ignoreMissingFields: boolean,
    values?: object;
    previousValues?: object;
    path?: string;
    entityId?: string | number;
    index?: number;
    propertyConfigs?: Record<string, PropertyConfig>;
    authController: AuthController;
}) {

    const of = property.of;
    if (!of)
        throw Error(
            `Trying to resolve an array property (${propertyKey}) without providing an 'of' property`
        )
    return Array.isArray(propertyValue)
        ? propertyValue.map((v: unknown, index: number) => {
            return resolveProperty({
                propertyKey: `${propertyKey}.${index}`,
                property: Array.isArray(of) ? of[index] : of,
                ...props,
                index
            });
        }).filter(e => Boolean(e)) as Property[]
        : [];
}

export function resolveEnumValues(input: EnumValues): EnumValueConfig[] | undefined {
    if (typeof input === "object") {
        return Object.entries(input).map(([id, value]) =>
        (typeof value === "string"
            ? {
                id,
                label: value
            }
            : value));
    } else if (Array.isArray(input)) {
        return input as EnumValueConfig[];
    } else {
        return undefined;
    }
}



export function getSubcollections<M extends Record<string, unknown> = Record<string, unknown>>(collection: EntityCollection<M>): EntityCollection<Record<string, unknown>>[] {
    if (collection.childCollections) {
        return collection.childCollections();
    }

    if (isFirebaseCollection(collection) && collection.subcollections) {
        return collection.subcollections();
    }

    if (isPostgresCollection(collection) && collection.relations) {
        const manyRelations = collection.relations.filter(r => r.cardinality === "many");
        return manyRelations.map(r => {
            const target = r.target();
            return r.overrides ? mergeDeep(target, r.overrides) : target;
        });
    }

    return [];
}

import { ArrayProperty, EntityValues, StorageConfig, StringProperty, UploadedFileContext } from "@rebasepro/types";
import { randomString } from "@rebasepro/utils";

interface ResolveFilenameStringParams<M extends object> {
    input: string | ((context: UploadedFileContext) => (Promise<string> | string));
    storage: StorageConfig;
    values: EntityValues<M>;
    entityId?: string | number;
    path?: string;
    property: StringProperty | ArrayProperty,
    file: File;
    propertyKey: string;
}

export async function resolveStorageFilenameString<M extends object>(
    {
        input,
        storage,
        values,
        entityId,
        path,
        property,
        file,
        propertyKey
    }: ResolveFilenameStringParams<M>): Promise<string> {
    let result;

    if (typeof input === "function") {
        result = await input({
            path,
            entityId,
            values,
            property,
            file,
            storage,
            propertyKey
        });
        if (!result)
            console.warn("Storage callback returned empty result. Using default name value")
    } else {
        result = replacePlaceholders({
            file,
            input,
            entityId,
            propertyKey,
            path
        });
    }

    if (!result)
        result = randomString() + "_" + file.name;

    return result;
}

interface ResolveStoragePathStringParams<M extends object> {
    input: string | ((context: UploadedFileContext) => string);
    storage: StorageConfig;
    values: EntityValues<M>;
    entityId?: string | number;
    path?: string;
    property: StringProperty | ArrayProperty;
    file: File;
    propertyKey: string;
}

export function resolveStoragePathString<M extends object>(
    {
        input,
        storage,
        values,
        entityId,
        path,
        property,
        file,
        propertyKey
    }: ResolveStoragePathStringParams<M>): string {
    let result;
    if (typeof input === "function") {
        result = input({
            path,
            entityId,
            values,
            property,
            file,
            storage,
            propertyKey
        });
        if (!result)
            console.warn("Storage callback returned empty result. Using default name value")
    } else {
        result = replacePlaceholders({
            file,
            input,
            entityId,
            propertyKey,
            path
        });
    }

    if (!result)
        result = randomString() + "_" + file.name;

    return result;
}

interface Placeholders {
    file: File;
    input: string;
    entityId?: string | number;
    propertyKey: string;
    path?: string;
}

function replacePlaceholders({
    file,
    input,
    entityId,
    propertyKey,
    path
}: Placeholders) {
    const ext = file.name.split(".").pop();
    let result = input
        .replace("{propertyKey}", propertyKey)
        .replace("{rand}", randomString())
        .replace("{file}", file.name)
        .replace("{file.type}", file.type);
    if (entityId) {
        result = result.replace("{entityId}", String(entityId));
    }
    if (path) {
        result = result.replace("{path}", path);
    }
    if (ext) {
        result = result.replace("{file.ext}", ext);
        const name = file.name.replace(`.${ext}`, "");
        result = result.replace("{file.name}", name)
    }

    if (!result)
        result = randomString() + "_" + file.name;

    return result;
}

