import { ErrorHandler } from "hono";
import { ContentfulStatusCode } from "hono/utils/http-status";

/**
 * Standardized API error class.
 * Throw this from any route handler — the errorHandler middleware
 * will format it into `{ error: { message, code, details? } }`.
 */
export class ApiError extends Error {
    public readonly statusCode: number;
    public readonly code: string;
    public readonly details?: unknown;

    constructor(statusCode: number, code: string, message: string, details?: unknown) {
        super(message);
        this.name = "ApiError";
        this.statusCode = statusCode;
        this.code = code;
        this.details = details;
    }

    // ── Factory methods ──────────────────────────────────────────────

    static badRequest(message: string, code = "BAD_REQUEST", details?: unknown): ApiError {
        return new ApiError(400, code, message, details);
    }

    static unauthorized(message: string, code = "UNAUTHORIZED"): ApiError {
        return new ApiError(401, code, message);
    }

    static forbidden(message: string, code = "FORBIDDEN"): ApiError {
        return new ApiError(403, code, message);
    }

    static notFound(message: string, code = "NOT_FOUND"): ApiError {
        return new ApiError(404, code, message);
    }

    static conflict(message: string, code = "CONFLICT"): ApiError {
        return new ApiError(409, code, message);
    }

    static internal(message: string, code = "INTERNAL_ERROR"): ApiError {
        return new ApiError(500, code, message);
    }

    static serviceUnavailable(message: string, code = "SERVICE_UNAVAILABLE"): ApiError {
        return new ApiError(503, code, message);
    }
}

/**
 * Canonical error response shape:
 * `{ error: { message: string, code: string, details?: unknown } }`
 */
export interface ErrorResponse {
    error: {
        message: string;
        code: string;
        details?: unknown;
    };
}

/**
 * Hono error-handling middleware (`app.onError`).
 * Converts any error into the canonical `{ error: { message, code } }` shape.
 */
export const errorHandler: ErrorHandler = (err, c) => {
    // Typecast custom error properties
    const error = err as Error & { statusCode?: number; code?: string; details?: unknown };

    if (error instanceof ApiError) {
        // Operational errors — log at warn level
        console.warn(
            `⚠️ [API] ${c.req.method} ${c.req.path} → ${error.statusCode} ${error.code}: ${error.message}`
        );
        return c.json({
            error: {
                message: error.message,
                code: error.code,
                ...(error.details !== undefined && { details: error.details })
            }
        } satisfies ErrorResponse, (error.statusCode || 500) as ContentfulStatusCode);
    }

    const statusCode = error.statusCode || codeToStatus(error.code) || 500;
    const code = error.code || "INTERNAL_ERROR";

    // Unexpected errors — log at error level with full stack
    console.error(
        `❌ [API] ${c.req.method} ${c.req.path} → ${statusCode} ${code}: ${error.message}`
    );
    console.error(error.stack || error);

    return c.json({
        error: {
            message: error.message || "An unexpected error occurred",
            code,
            ...(error.details !== undefined && { details: error.details })
        }
    } satisfies ErrorResponse, statusCode as ContentfulStatusCode);
};

/**
 * Map known error codes to HTTP status codes.
 */
function codeToStatus(code?: string): number | undefined {
    if (!code) return undefined;
    const map: Record<string, number> = {
        BAD_REQUEST: 400,
        INVALID_INPUT: 400,
        WEAK_PASSWORD: 400,
        UNAUTHORIZED: 401,
        INVALID_CREDENTIALS: 401,
        INVALID_TOKEN: 401,
        FORBIDDEN: 403,
        NOT_FOUND: 404,
        CONFLICT: 409,
        EMAIL_EXISTS: 409,
        ROLE_EXISTS: 409,
        INTERNAL_ERROR: 500,
        NOT_CONFIGURED: 503,
        SERVICE_UNAVAILABLE: 503,
    };
    return map[code];
}

import {
    GraphQLSchema,
    GraphQLObjectType,
    GraphQLString,
    GraphQLInt,
    GraphQLFloat,
    GraphQLBoolean,
    GraphQLList,
    GraphQLNonNull,
    GraphQLFieldConfig,
    GraphQLInputObjectType,
} from "graphql";
import { DataDriver, EntityCollection, FetchCollectionProps, Property } from "@rebasepro/types";

/**
 * Lightweight GraphQL schema generator that leverages existing DataDriver
 * No duplication - uses your existing data layer and services
 */
export class GraphQLSchemaGenerator {
    private collections: EntityCollection[];
    private driver: DataDriver;
    private typeRegistry = new Map<string, GraphQLObjectType>();
    private inputTypeRegistry = new Map<string, GraphQLInputObjectType>();

    constructor(collections: EntityCollection[], driver: DataDriver) {
        this.collections = collections;
        this.driver = driver;
    }

    /**
     * Generate complete GraphQL schema using existing DataDriver
     */
    generateSchema(): GraphQLSchema {
        // Create all types first
        this.collections.forEach(collection => {
            this.createEntityType(collection);
            this.createInputType(collection);
        });

        const queryType = this.createQueryType();
        const mutationType = this.createMutationType();

        return new GraphQLSchema({
            query: queryType,
            mutation: mutationType,
        });
    }

    /**
     * Create GraphQL type for an entity collection
     */
    private createEntityType(collection: EntityCollection): GraphQLObjectType {
        const typeName = this.getTypeName(collection);

        if (this.typeRegistry.has(typeName)) {
            return this.typeRegistry.get(typeName)!;
        }

        const fields: Record<string, GraphQLFieldConfig<unknown, unknown>> = {};

        // Add ID field
        fields.id = {
            type: new GraphQLNonNull(GraphQLString),
            description: "Unique identifier",
            resolve: (source) => source.id
        };

        // Convert properties to GraphQL fields
        Object.entries(collection.properties).forEach(([key, property]) => {
            if (property.type !== "relation" && key !== "id") {
                const fieldConfig = this.convertPropertyToField(property);
                fieldConfig.resolve = (source) => source.values?.[key];
                fields[key] = fieldConfig;
            }
        });

        const entityType = new GraphQLObjectType({
            name: typeName,
            description: collection.description || `${collection.singularName} entity`,
            fields: () => fields
        });

        this.typeRegistry.set(typeName, entityType);
        return entityType;
    }

    private convertPropertyToField(property: Property): GraphQLFieldConfig<unknown, unknown> {
        let type;

        switch (property.type) {
            case "string":
                type = GraphQLString;
                break;
            case "number":
                type = GraphQLFloat;
                break;
            case "boolean":
                type = GraphQLBoolean;
                break;
            case "date":
                type = GraphQLString;
                break;
            case "array":
                type = new GraphQLList(GraphQLString);
                break;
            default:
                type = GraphQLString;
        }

        return {
            type: property.validation?.required ? new GraphQLNonNull(type) : type,
            description: property.name || property.description
        };
    }

    private createInputType(collection: EntityCollection): GraphQLInputObjectType {
        const typeName = `${this.getTypeName(collection)}Input`;

        if (this.inputTypeRegistry.has(typeName)) {
            return this.inputTypeRegistry.get(typeName)!;
        }

        const fields: Record<string, unknown> = {};

        Object.entries(collection.properties).forEach(([key, property]) => {
            if (property.type !== "relation") {
                fields[key] = {
                    type: this.convertPropertyToInputType(property)
                };
            }
        });

        const inputType = new GraphQLInputObjectType({
            name: typeName,
            description: `Input for creating/updating ${collection.singularName}`,
            fields
        });

        this.inputTypeRegistry.set(typeName, inputType);
        return inputType;
    }

    private convertPropertyToInputType(property: Property) {
        switch (property.type) {
            case "string":
                return GraphQLString;
            case "number":
                return GraphQLFloat;
            case "boolean":
                return GraphQLBoolean;
            case "date":
                return GraphQLString;
            case "array":
                return new GraphQLList(GraphQLString);
            default:
                return GraphQLString;
        }
    }

    /**
     * Create Query type using existing DataDriver methods
     */
    private createQueryType(): GraphQLObjectType {
        const fields: Record<string, GraphQLFieldConfig<unknown, unknown>> = {};

        this.collections.forEach(collection => {
            const typeName = this.getTypeName(collection);
            const entityType = this.typeRegistry.get(typeName);

            if (!entityType) return;

            // Single entity query - uses existing fetchEntity
            fields[this.getSingleQueryName(collection)] = {
                type: entityType,
                args: {
                    id: { type: new GraphQLNonNull(GraphQLString) }
                },
                resolve: async (_, args, context: { driver: DataDriver }) => {
                    const ds = context.driver || this.driver;
                    const entity = await ds.fetchEntity({
                        path: collection.slug,
                        entityId: args.id,
                        collection
                    });
                    return entity;
                }
            };

            // List query - uses existing fetchCollection
            fields[this.getListQueryName(collection)] = {
                type: new GraphQLList(entityType),
                args: {
                    limit: { type: GraphQLInt, defaultValue: 20 },
                    offset: { type: GraphQLInt, defaultValue: 0 },
                    where: { type: GraphQLString },
                    orderBy: { type: GraphQLString }
                },
                resolve: async (_, args, context: { driver: DataDriver }) => {
                    const ds = context.driver || this.driver;
                    let filter: FetchCollectionProps["filter"] | undefined;
                    if (args.where) {
                        try {
                            const parsed = JSON.parse(args.where);
                            if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
                                throw new Error("Filter must be a JSON object");
                            }
                            filter = parsed;
                        } catch (e) {
                            throw new Error(`Invalid 'where' filter: ${e instanceof Error ? e.message : "malformed JSON"}`);
                        }
                    }
                    const entities = await ds.fetchCollection({
                        path: collection.slug,
                        collection,
                        filter,
                        limit: args.limit,
                        startAfter: args.offset ? String(args.offset) : undefined
                    });
                    return entities;
                }
            };
        });

        return new GraphQLObjectType({
            name: "Query",
            fields
        });
    }

    /**
     * Create Mutation type using existing DataDriver methods
     */
    private createMutationType(): GraphQLObjectType {
        const fields: Record<string, GraphQLFieldConfig<unknown, unknown>> = {};

        this.collections.forEach(collection => {
            const typeName = this.getTypeName(collection);
            const entityType = this.typeRegistry.get(typeName);
            const inputType = this.inputTypeRegistry.get(`${typeName}Input`);

            if (!entityType || !inputType) return;

            // Create mutation - uses existing saveEntity
            fields[`create${typeName}`] = {
                type: entityType,
                args: {
                    input: { type: new GraphQLNonNull(inputType) }
                },
                resolve: async (_, args, context: { driver: DataDriver }) => {
                    const ds = context.driver || this.driver;
                    const path = collection.slug;
                    const entity = await ds.saveEntity({
                        path,
                        values: args.input,
                        collection,
                        status: "new"
                    });
                    return entity;
                }
            };

            // Update mutation - uses existing saveEntity
            fields[`update${typeName}`] = {
                type: entityType,
                args: {
                    id: { type: new GraphQLNonNull(GraphQLString) },
                    input: { type: new GraphQLNonNull(inputType) }
                },
                resolve: async (_, args, context: { driver: DataDriver }) => {
                    const ds = context.driver || this.driver;
                    const entity = await ds.saveEntity({
                        path: collection.slug,
                        entityId: args.id,
                        values: args.input,
                        collection,
                        status: "existing"
                    });
                    return entity;
                }
            };

            // Delete mutation - uses existing deleteEntity
            fields[`delete${typeName}`] = {
                type: GraphQLBoolean,
                args: {
                    id: { type: new GraphQLNonNull(GraphQLString) }
                },
                resolve: async (_, args, context: { driver: DataDriver }) => {
                    try {
                        const ds = context.driver || this.driver;
                        const existingEntity = await ds.fetchEntity({
                            path: collection.slug,
                            entityId: args.id,
                            collection
                        });
                        if (!existingEntity) return false;
                        await ds.deleteEntity({
                            entity: existingEntity,
                            collection
                        });
                        return true;
                    } catch {
                        return false;
                    }
                }
            };
        });

        return new GraphQLObjectType({
            name: "Mutation",
            fields
        });
    }

    // Helper methods
    private getTypeName(collection: EntityCollection): string {
        return collection.singularName?.replace(/\s+/g, "") ||
            collection.name.slice(0, -1).replace(/\s+/g, "");
    }

    private getSingleQueryName(collection: EntityCollection): string {
        return this.getTypeName(collection).toLowerCase();
    }

    private getListQueryName(collection: EntityCollection): string {
        return collection.slug;
    }
}

import { EntityCollection, Property } from "@rebasepro/types";

export function generateOpenApiSpec(collections: EntityCollection[], basePath: string = "/api"): Record<string, unknown> {
    const spec = {
        openapi: "3.0.0",
        info: {
            title: "Rebase Auto-Generated API",
            version: "1.0.0",
            description: "Automatically generated REST API from Rebase collections"
        },
        servers: [
            {
                url: basePath,
                description: "API Server"
            }
        ],
        paths: {} as Record<string, unknown>,
        components: {
            schemas: {} as Record<string, unknown>
        }
    };

    (collections || []).forEach(collection => {
        const schemaName = collection.singularName || collection.name;
        spec.components.schemas[schemaName] = {
            type: "object",
            properties: {
                id: { type: "string" },
                ...Object.entries(collection.properties).reduce((props, [key, property]) => {
                    if (property.type !== "relation") {
                        props[key] = convertPropertyToOpenApiType(property);
                    }
                    return props;
                }, {} as Record<string, unknown>)
            }
        };

        const collectionPath = `/${collection.slug}`;

        spec.paths[collectionPath] = {
            get: {
                summary: `List ${collection.name}`,
                parameters: [
                    { name: "limit", in: "query", schema: { type: "integer", default: 20 } },
                    { name: "offset", in: "query", schema: { type: "integer", default: 0 } },
                    { name: "where", in: "query", schema: { type: "string" } },
                    { name: "orderBy", in: "query", schema: { type: "string" } }
                ],
                responses: {
                    200: {
                        description: "Success",
                        content: {
                            "application/json": {
                                schema: {
                                    type: "object",
                                    properties: {
                                        data: {
                                            type: "array",
                                            items: { $ref: `#/components/schemas/${schemaName}` }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            },
            post: {
                summary: `Create ${schemaName}`,
                requestBody: {
                    content: {
                        "application/json": {
                            schema: { $ref: `#/components/schemas/${schemaName}` }
                        }
                    }
                },
                responses: {
                    201: {
                        description: "Created",
                        content: {
                            "application/json": {
                                schema: { $ref: `#/components/schemas/${schemaName}` }
                            }
                        }
                    }
                }
            }
        };

        spec.paths[`${collectionPath}/{id}`] = {
            get: {
                summary: `Get ${schemaName} by ID`,
                parameters: [
                    { name: "id", in: "path", required: true, schema: { type: "string" } }
                ],
                responses: {
                    200: {
                        description: "Success",
                        content: {
                            "application/json": {
                                schema: { $ref: `#/components/schemas/${schemaName}` }
                            }
                        }
                    }
                }
            },
            put: {
                summary: `Update ${schemaName}`,
                parameters: [
                    { name: "id", in: "path", required: true, schema: { type: "string" } }
                ],
                requestBody: {
                    content: {
                        "application/json": {
                            schema: { $ref: `#/components/schemas/${schemaName}` }
                        }
                    }
                },
                responses: {
                    200: {
                        description: "Updated",
                        content: {
                            "application/json": {
                                schema: { $ref: `#/components/schemas/${schemaName}` }
                            }
                        }
                    }
                }
            },
            delete: {
                summary: `Delete ${schemaName}`,
                parameters: [
                    { name: "id", in: "path", required: true, schema: { type: "string" } }
                ],
                responses: {
                    204: { description: "Deleted" }
                }
            }
        };
    });

    return spec;
}

function convertPropertyToOpenApiType(property: Property): Record<string, unknown> {
    switch (property.type) {
        case "string":
            return { type: "string" };
        case "number":
            return { type: "number" };
        case "boolean":
            return { type: "boolean" };
        case "date":
            return { type: "string", format: "date-time" };
        case "array":
            return { type: "array", items: { type: "string" } };
        default:
            return { type: "string" };
    }
}

import { Hono } from "hono";
import { DataDriver, Entity, EntityCollection, FetchCollectionProps } from "@rebasepro/types";
import { QueryOptions, HonoEnv } from "../types";
import { ApiError } from "../errors";
import { parseQueryOptions } from "./query-parser";


/**
 * Lightweight REST API generator that leverages existing Rebase DataDriver.
 * Supports `include` query parameter for eager-loading relations via Drizzle.
 */
export class RestApiGenerator {
    private collections: EntityCollection[];
    private router: Hono<HonoEnv>;
    private driver: DataDriver;

    constructor(collections: EntityCollection[], driver: DataDriver) {
        this.collections = collections;
        this.driver = driver;
        this.router = new Hono<HonoEnv>();
    }

    /**
     * Generate REST routes using existing DataDriver
     */
    generateRoutes(): Hono<HonoEnv> {
        this.collections.forEach(collection => {
            this.createCollectionRoutes(collection);
        });

        // Catch-all routes for subcollection paths like
        // /authors/111094/posts  and  /authors/111094/posts/43
        // The DataDriver already knows how to resolve nested relation paths.
        this.createSubcollectionRoutes();

        return this.router;
    }

    /**
     * Get the EntityFetchService from a driver if it exposes one (for include support)
     */
    private getFetchService(driver: DataDriver): Record<string, Function> | null {
        if ("entityService" in driver && typeof driver.entityService === "object" && driver.entityService) {
            const es = driver.entityService as Record<string, unknown>;
            if (typeof es.getFetchService === "function") {
                return es.getFetchService();
            }
        }
        return null;
    }

    /**
     * Create REST routes for a collection using existing Rebase patterns
     */
    private createCollectionRoutes(collection: EntityCollection): void {
        const basePath = `/${collection.slug}`;
        const resolvedCollection = collection;

        // GET /collection - List entities
        this.router.get(basePath, async (c) => {
            const queryDict = c.req.query();
            const queryOptions = parseQueryOptions(queryDict);

            const driver = c.get("driver") || this.driver;
            const fetchService = this.getFetchService(driver);

            // Use include-aware path when available
            if (fetchService) {
                const collectionPath = collection.slug;
                const entities = await fetchService.fetchCollectionForRest(
                    collectionPath,
                    {
                        filter: queryOptions.where as FetchCollectionProps["filter"],
                        limit: queryOptions.limit,
                        orderBy: queryOptions.orderBy?.[0]?.field,
                        order: queryOptions.orderBy?.[0]?.direction === "desc" ? "desc" : "asc",
                        searchString: queryDict.searchString as string | undefined,
                    },
                    queryOptions.include
                );

                const total = await this.countRawEntities(driver, resolvedCollection, queryOptions);

                return c.json({
                    data: entities,
                    meta: {
                        total,
                        limit: queryOptions.limit,
                        offset: queryOptions.offset,
                        hasMore: (queryOptions.offset || 0) + entities.length < total
                    }
                });
            }

            // Fallback for non-Postgres drivers
            const entities = await this.fetchRawCollection(driver, resolvedCollection, queryOptions);
            const total = await this.countRawEntities(driver, resolvedCollection, queryOptions);

            return c.json({
                data: entities,
                meta: {
                    total,
                    limit: queryOptions.limit,
                    offset: queryOptions.offset,
                    hasMore: (queryOptions.offset || 0) + entities.length < total
                }
            });
        });

        // GET /collection/:id - Get single entity
        this.router.get(`${basePath}/:id`, async (c) => {
            const id = c.req.param("id");
            const queryDict = c.req.query();
            const queryOptions = parseQueryOptions(queryDict);
            const driver = c.get("driver") || this.driver;
            const fetchService = this.getFetchService(driver);

            // Use include-aware path when available
            if (fetchService) {
                const collectionPath = collection.slug;
                const entity = await fetchService.fetchEntityForRest(
                    collectionPath,
                    String(id),
                    queryOptions.include
                );

                if (!entity) {
                    throw ApiError.notFound("Entity not found");
                }

                return c.json(entity);
            }

            // Fallback
            const entity = await this.fetchRawEntity(driver, resolvedCollection, String(id));

            if (!entity) {
                throw ApiError.notFound("Entity not found");
            }

            return c.json(entity);
        });

        // POST /collection - Create entity
        this.router.post(basePath, async (c) => {
            try {
                const driver = c.get("driver") || this.driver;
                const path = collection.slug;

                const body = await c.req.json().catch(() => ({}));

                const entity = await driver.saveEntity({
                    path,
                    values: body,
                    collection: resolvedCollection,
                    status: "new"
                });

                return c.json(this.formatResponse(entity), 201);
            } catch (error) {
                const err = error as Error & { code?: string };
                err.code = err.code || "BAD_REQUEST";
                throw err;
            }
        });

        // PUT /collection/:id - Update entity
        this.router.put(`${basePath}/:id`, async (c) => {
            try {
                const id = c.req.param("id");
                const driver = c.get("driver") || this.driver;

                const existingEntity = await driver.fetchEntity({
                    path: collection.slug,
                    entityId: String(id),
                    collection: resolvedCollection
                });

                if (!existingEntity) {
                    throw ApiError.notFound("Entity not found");
                }

                const body = await c.req.json().catch(() => ({}));

                const entity = await driver.saveEntity({
                    path: collection.slug,
                    entityId: String(id),
                    values: body,
                    collection: resolvedCollection,
                    status: "existing"
                });

                return c.json(this.formatResponse(entity));
            } catch (error) {
                const err = error as Error & { code?: string };
                err.code = err.code || "BAD_REQUEST";
                throw err;
            }
        });

        // DELETE /collection/:id - Delete entity
        this.router.delete(`${basePath}/:id`, async (c) => {
            const id = c.req.param("id");
            const driver = c.get("driver") || this.driver;

            const existingEntity = await driver.fetchEntity({
                path: collection.slug,
                entityId: String(id),
                collection: resolvedCollection
            });

            if (!existingEntity) {
                throw ApiError.notFound("Entity not found");
            }

            await driver.deleteEntity({
                entity: existingEntity,
                collection: resolvedCollection
            });

            return new Response(null, { status: 204 });
        });
    }

    /**
     * Catch-all routes for subcollection paths.
     *
     * Matches URL patterns like:
     *   GET    /authors/111094/posts          → list child collection
     *   GET    /authors/111094/posts/43       → get child entity
     *   POST   /authors/111094/posts          → create child entity
     *   PUT    /authors/111094/posts/43       → update child entity
     *   DELETE /authors/111094/posts/43       → delete child entity
     *
     * The wildcard `*` captures the full remainder of the URL path.
     * We split it into segments and reconstruct the `collectionPath`
     * (e.g. "authors/111094/posts") and optional `entityId` (e.g. "43").
     *
     * The DataDriver.saveEntity / fetchCollection / etc. already know how to
     * resolve multi-segment relation paths, so we just forward to them.
     */
    private createSubcollectionRoutes(): void {
        // Helper: parse a path like "authors/111094/posts/43" into
        // { collectionPath: "authors/111094/posts", entityId: "43" }
        // or "authors/111094/posts" into
        // { collectionPath: "authors/111094/posts", entityId: undefined }
        const parseSubPath = (rawPath: string): { collectionPath: string; entityId?: string } | null => {
            const segments = rawPath.split("/").filter(Boolean);
            // Need at least 3 segments for a subcollection path (parent/id/child)
            if (segments.length < 3) return null;

            // Odd segment count → collection path (parent/id/child or parent/id/child/id2/grandchild)
            // Even segment count → entity path   (parent/id/child/entityId)
            if (segments.length % 2 === 1) {
                return { collectionPath: segments.join("/") };
            } else {
                const entityId = segments.pop()!;
                return { collectionPath: segments.join("/"), entityId };
            }
        };

        // GET /<subcollection-path> — list or get single entity
        this.router.get("/*", async (c) => {
            const rawPath = c.req.path.replace(/^\//, "");
            const parsed = parseSubPath(rawPath);
            if (!parsed) return c.notFound();

            const driver = c.get("driver") || this.driver;

            if (parsed.entityId) {
                // GET /parent/:parentId/child/:id — single entity
                const entity = await driver.fetchEntity({
                    path: parsed.collectionPath,
                    entityId: parsed.entityId
                });
                if (!entity) throw ApiError.notFound("Entity not found");
                return c.json(this.flattenEntity(entity));
            } else {
                // GET /parent/:parentId/child — list entities
                const queryDict = c.req.query();
                const queryOptions = parseQueryOptions(queryDict);
                const entities = await driver.fetchCollection({
                    path: parsed.collectionPath,
                    filter: queryOptions.where as FetchCollectionProps["filter"],
                    limit: queryOptions.limit,
                    orderBy: queryOptions.orderBy?.[0]?.field,
                    order: queryOptions.orderBy?.[0]?.direction === "desc" ? "desc" : "asc",
                    searchString: queryDict.searchString as string | undefined
                });
                return c.json({
                    data: entities.map(e => this.flattenEntity(e)),
                    meta: {
                        total: entities.length,
                        limit: queryOptions.limit,
                        offset: queryOptions.offset,
                        hasMore: false
                    }
                });
            }
        });

        // POST /<subcollection-path> — create entity
        this.router.post("/*", async (c) => {
            const rawPath = c.req.path.replace(/^\//, "");
            const parsed = parseSubPath(rawPath);
            if (!parsed || parsed.entityId) return c.notFound();

            const driver = c.get("driver") || this.driver;
            const body = await c.req.json().catch(() => ({}));

            const entity = await driver.saveEntity({
                path: parsed.collectionPath,
                values: body,
                status: "new"
            });

            return c.json(this.formatResponse(entity), 201);
        });

        // PUT /<subcollection-path>/:id — update entity
        this.router.put("/*", async (c) => {
            const rawPath = c.req.path.replace(/^\//, "");
            const parsed = parseSubPath(rawPath);
            if (!parsed || !parsed.entityId) return c.notFound();

            const driver = c.get("driver") || this.driver;
            const body = await c.req.json().catch(() => ({}));

            const entity = await driver.saveEntity({
                path: parsed.collectionPath,
                entityId: parsed.entityId,
                values: body,
                status: "existing"
            });

            return c.json(this.formatResponse(entity));
        });

        // DELETE /<subcollection-path>/:id — delete entity
        this.router.delete("/*", async (c) => {
            const rawPath = c.req.path.replace(/^\//, "");
            const parsed = parseSubPath(rawPath);
            if (!parsed || !parsed.entityId) return c.notFound();

            const driver = c.get("driver") || this.driver;

            const existingEntity = await driver.fetchEntity({
                path: parsed.collectionPath,
                entityId: parsed.entityId
            });

            if (!existingEntity) throw ApiError.notFound("Entity not found");

            await driver.deleteEntity({ entity: existingEntity });

            return new Response(null, { status: 204 });
        });
    }

    /**
     * Format successful API response - flattened for traditional REST API
     */
    private formatResponse<T>(data: T, meta?: Record<string, unknown>): unknown {
        if (Array.isArray(data)) {
            const flattenedData = data.map(entity => this.flattenEntity(entity));
            if (meta) {
                return {
                    data: flattenedData,
                    meta
                };
            }
            return flattenedData;
        }

        if (data && typeof data === "object" && "values" in data) {
            return this.flattenEntity(data as unknown as Entity<Record<string, unknown>>);
        }

        if (meta) {
            return {
                data,
                meta
            };
        }
        return data;
    }

    /**
     * Flatten Rebase entity structure to traditional REST format
     */
    private flattenEntity(entity: Entity<Record<string, unknown>>): Record<string, unknown> {
        if (!entity || typeof entity !== "object") {
            return entity;
        }

        if ("values" in entity && typeof entity.values === "object") {
            return {
                id: entity.id,
                ...entity.values
            };
        }

        return entity as unknown as Record<string, unknown>;
    }

    /**
     * Fetch raw collection data without Entity wrapper (fallback for non-Postgres)
     */
    private async fetchRawCollection(driver: DataDriver, collection: EntityCollection, queryOptions: QueryOptions) {
        const entities = await driver.fetchCollection({
            path: collection.slug,
            collection,
            filter: queryOptions.where as FetchCollectionProps["filter"],
            limit: queryOptions.limit,
            orderBy: queryOptions.orderBy?.[0]?.field,
            order: queryOptions.orderBy?.[0]?.direction === "desc" ? "desc" : "asc",
            startAfter: queryOptions.offset ? String(queryOptions.offset) : undefined
        });

        return entities.map(entity => this.flattenEntity(entity));
    }

    /**
     * Count raw entities for a collection
     */
    private async countRawEntities(driver: DataDriver, collection: EntityCollection, queryOptions: QueryOptions): Promise<number> {
        return driver.countEntities ? await driver.countEntities({
            path: collection.slug,
            collection,
            filter: queryOptions.where as FetchCollectionProps["filter"]
        }) : 0;
    }

    /**
     * Fetch single entity raw data without Entity wrapper (fallback)
     */
    private async fetchRawEntity(driver: DataDriver, collection: EntityCollection, entityId: string) {
        const entity = await driver.fetchEntity({
            path: collection.slug,
            entityId,
            collection
        });

        return entity ? this.flattenEntity(entity) : null;
    }
}

import { Hono } from "hono";
import { cors } from "hono/cors";
import { secureHeaders } from "hono/secure-headers";
import { graphqlServer } from "@hono/graphql-server";
import { serve } from "@hono/node-server";
import { GraphQLSchemaGenerator } from "./graphql/graphql-schema-generator";
import { RestApiGenerator } from "./rest/api-generator";
import { DataDriver, EntityCollection, Relation } from "@rebasepro/types";
import { ApiConfig, HonoEnv } from "./types";
import { loadCollectionsFromDirectory } from "../collections/loader";
import { createSchemaEditorRoutes } from "./schema-editor-routes";
import { createAuthMiddleware, requireAuth, requireAdmin } from "../auth/middleware";
import { errorHandler } from "./errors";
import { generateOpenApiSpec } from "./openapi-generator";

/**
 * Simplified API server that leverages existing Rebase infrastructure
 * Can be used standalone or mounted on existing Hono app
 */
export class RebaseApiServer {
    private app: Hono<HonoEnv>;
    private router: Hono<HonoEnv>;
    private config: ApiConfig;
    private driver: DataDriver;

    private constructor(config: ApiConfig & { driver: DataDriver }) {
        this.config = {
            basePath: "/api",
            enableGraphQL: true,
            enableREST: true,
            pagination: {
                defaultLimit: 20,
                maxLimit: 100
            },
            ...config
        };

        this.driver = config.driver;

        this.app = new Hono<HonoEnv>();
        this.router = new Hono<HonoEnv>();

        this.setupMiddleware();
    }

    /**
     * Factory method to create an asynchronously initialized ApiServer instance
     */
    public static async create(config: ApiConfig & { driver: DataDriver }): Promise<RebaseApiServer> {
        if (config.collectionsDir && (!config.collections || config.collections.length === 0)) {
            config.collections = await loadCollectionsFromDirectory(config.collectionsDir);
        } else if (!config.collections) {
            config.collections = [];
        }

        const server = new RebaseApiServer(config);
        server.setupRoutes();
        // Since we mount routes directly to router, we can let consumer attach it
        server.app.route("/", server.router);

        // Hono global error handler on the root app
        server.app.onError(errorHandler);
        server.router.onError(errorHandler);

        return server;
    }

    /**
     * Setup Hono middleware
     */
    private setupMiddleware(): void {
        // Security headers
        this.router.use("/*", secureHeaders());

        // CORS — only applied if explicitly configured via `cors` option.
        // If omitted, the user is expected to configure CORS on their own
        // Hono app before mounting the API (recommended approach).
        if (this.config.cors) {
            const origin = this.config.cors.origin;
            this.router.use("/*", cors({
                origin: typeof origin === "boolean"
                    ? (origin ? ((o: string) => o) : "")
                    : (origin ?? "*"),
                credentials: this.config.cors.credentials ?? false
            }));
        }

        // Auth middleware
        this.router.use("/*", createAuthMiddleware({
            driver: this.driver,
            requireAuth: this.config.requireAuth ?? true,
            validator: this.config.authValidator
        }));
    }

    /**
     * Setup API routes using existing services
     */
    private setupRoutes(): void {
        const basePath = this.config.basePath!;

        // Health check
        this.router.get(`${basePath}/health`, (c) => {
            return c.json({
                status: "healthy",
                timestamp: new Date().toISOString(),
                collections: this.config.collections?.map((col: EntityCollection) => col.slug) || [],
                driver: this.driver.key
            });
        });

        // Collections metadata endpoint
        this.router.get(`${basePath}/collections`, (c) => {
            const collectionsMetadata = (this.config.collections || []).map((col: EntityCollection) => ({
                slug: col.slug,
                name: col.name,
                singularName: col.singularName,
                description: col.description,
                properties: Object.keys(col.properties),
                relations: (col as EntityCollection & { relations?: Relation[] }).relations?.map((r: Relation) => ({
                    relationName: r.relationName,
                    target: typeof r.target === 'function' ? r.target().slug : r.target,
                    cardinality: r.cardinality,
                    direction: r.direction
                })) || []
            }));

            return c.json({ data: collectionsMetadata });
        });

        // GraphQL endpoint
        if (this.config.enableGraphQL) {
            const schemaGenerator = new GraphQLSchemaGenerator(this.config.collections || [], this.driver);
            const schema = schemaGenerator.generateSchema();

            // Context is automatically passed to resolvers via contextValue containing Hono's 'c'
            this.router.use(`${basePath}/graphql`, graphqlServer({
                schema
            }));

            // Lightweight GraphiQL IDE
            if (process.env.NODE_ENV !== "production") {
                this.router.get(`${basePath}/graphiql`, (c) => {
                    return c.html(`<!DOCTYPE html>
<html>
<head>
  <meta charset=utf-8/>
  <title>Rebase GraphiQL</title>
  <link rel="stylesheet" href="https://unpkg.com/graphiql/graphiql.min.css" />
  <style>body,html,#graphiql{height:100%;margin:0;width:100%;}</style>
</head>
<body>
<div id="graphiql">Loading...</div>
<script crossorigin src="https://unpkg.com/react/umd/react.production.min.js"></script>
<script crossorigin src="https://unpkg.com/react-dom/umd/react-dom.production.min.js"></script>
<script src="https://unpkg.com/graphiql/graphiql.min.js"></script>
<script>
  const fetcher = GraphiQL.createFetcher({ url: '${basePath}/graphql' });
  ReactDOM.render(
    React.createElement(GraphiQL, { fetcher }),
    document.getElementById('graphiql'),
  );
</script>
</body>
</html>`);
                });
            }
        }

        if (this.config.enableREST) {
            const restGenerator = new RestApiGenerator(this.config.collections || [], this.driver);
            const restRoutes = restGenerator.generateRoutes();
            this.router.route(basePath, restRoutes);
        }

        // Schema Editor endpoints
        if (this.config.collectionsDir) {
            if (process.env.NODE_ENV === "production") {
                console.warn("[RebaseApiServer] Schema Editor is disabled in production environments for security.");
            } else {
                const schemaEditorRoutes = createSchemaEditorRoutes(this.config.collectionsDir);
                this.router.route(`${basePath}/schema-editor`, schemaEditorRoutes);
                // Auth middlewares applied to schema-editor via the router prefix
                this.router.use(`${basePath}/schema-editor/*`, requireAuth, requireAdmin);
            }
        }

        // OpenAPI endpoint
        this.router.get(`${basePath}/docs`, (c) => {
            const openApiSpec = generateOpenApiSpec(this.config.collections || [], this.config.basePath);
            return c.json(openApiSpec);
        });

        // Simple Swagger UI
        if (process.env.NODE_ENV !== "production") {
            this.router.get(`${basePath}/swagger`, (c) => {
                return c.html(`
                    <!DOCTYPE html>
                    <html>
                    <head>
                        <title>Rebase API Documentation</title>
                        <link rel="stylesheet" type="text/css" href="https://unpkg.com/swagger-ui-dist@4.15.5/swagger-ui.css" />
                    </head>
                    <body>
                        <div id="swagger-ui"></div>
                        <script src="https://unpkg.com/swagger-ui-dist@4.15.5/swagger-ui-bundle.js"></script>
                        <script>
                            SwaggerUIBundle({
                                url: '${basePath}/docs',
                                dom_id: '#swagger-ui'
                            });
                        </script>
                    </body>
                    </html>
                `);
            });
        }
    }

    /**
     * Get the Hono router with all API routes
     */
    getRouter(): Hono<HonoEnv> {
        return this.router;
    }

    /**
     * Get the standalone Hono app
     */
    getApp(): Hono<HonoEnv> {
        return this.app;
    }

    /**
     * Start the server (standalone mode) via @hono/node-server
     */
    listen(port: number = 3000, callback?: () => void): void {
        serve({
            fetch: this.app.fetch,
            port
        }, () => {
            if (callback) callback();
        });
    }
}

import { EntityCollection } from "@rebasepro/types";
import { AuthResult } from "../auth/middleware";
import { NodePgDatabase } from "drizzle-orm/node-postgres";
import { DataDriver } from "@rebasepro/types";

/**
 * Hono Environment Variables
 * Passed to generic Hono<HonoEnv> to type `c.get()`
 */
export type HonoEnv = {
    Variables: {
        user?: AuthResult | { userId?: string, roles?: string[] };
        driver?: DataDriver;
    }
};

/**
 * Configuration for API generation
 */
/**
 * Configuration for API generation
 */
export interface ApiConfig {
    collections?: EntityCollection[];
    collectionsDir?: string;
    basePath?: string;
    enableGraphQL?: boolean;
    enableREST?: boolean;
    cors?: {
        origin?: string | string[] | boolean;
        credentials?: boolean;
    };
    /** Whether auth is required for API endpoints (default: true) */
    requireAuth?: boolean;
    /** Optional custom validator for authentication */
    authValidator?: (c: import("hono").Context<import("./types").HonoEnv>) => Promise<AuthResult>;
    pagination?: {
        defaultLimit: number;
        maxLimit: number;
    };
}

/**
 * Context passed to resolvers and handlers
 */
export interface ApiContext {
    user?: AuthResult;
    collections: Map<string, EntityCollection>;
    db: NodePgDatabase; // Drizzle DB instance
}

/**
 * Standard API response format
 */
export interface ApiResponse<T = unknown> {
    data?: T;
    error?: {
        message: string;
        code?: string;
        details?: unknown;
    };
    meta?: {
        total?: number;
        page?: number;
        limit?: number;
        hasMore?: boolean;
    };
}

/**
 * Query options for API endpoints
 */
export interface QueryOptions {
    limit?: number;
    offset?: number;
    where?: Record<string, unknown>;
    orderBy?: Array<{ field: string; direction: 'asc' | 'desc' }>;
    include?: string[];
    /** Columns to return in the response (field-level selection) */
    fields?: string[];
}

/**
 * Relation resolution configuration
 */
export interface RelationConfig {
    relationName: string;
    depth?: number;
    include?: string[];
}

import { Hono } from "hono";
import { ApiError } from "../api/errors";
import type { AuthRepository } from "./interfaces";
import { requireAuth, requireAdmin } from "./middleware";
import { hashPassword, validatePasswordStrength } from "./password";
import { AuthModuleConfig } from "./routes";
import { HonoEnv } from "../api/types";
import { randomBytes, createHash } from "crypto";
import { getUserInvitationTemplate, getPasswordResetTemplate } from "../email/templates";

/**
 * Generate a cryptographically secure random password that meets strength requirements.
 */
function generateSecurePassword(): string {
    const upper = "ABCDEFGHJKLMNPQRSTUVWXYZ";
    const lower = "abcdefghjkmnpqrstuvwxyz";
    const digits = "23456789";
    const all = upper + lower + digits;

    // Guarantee at least one of each required class
    const pick = (chars: string) => chars[Math.floor(Math.random() * chars.length)];
    const parts = [pick(upper), pick(lower), pick(digits)];

    // Fill remaining with random chars (16 total)
    for (let i = parts.length; i < 16; i++) {
        parts.push(pick(all));
    }

    // Shuffle
    for (let i = parts.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [parts[i], parts[j]] = [parts[j], parts[i]];
    }
    return parts.join("");
}

/**
 * Generate a secure random token
 */
function generateSecureToken(): string {
    return randomBytes(40).toString("hex");
}

/**
 * Hash a token for database storage
 */
function hashToken(token: string): string {
    return createHash("sha256").update(token).digest("hex");
}

/**
 * Create admin routes for user and role management
 */
export function createAdminRoutes(config: AuthModuleConfig): Hono<HonoEnv> {
    const router = new Hono<HonoEnv>();
    const authRepo = config.authRepo;
    const { emailService, emailConfig } = config;

    // Apply auth middleware to all routes
    router.use("/*", requireAuth);

    router.post("/bootstrap", async (c) => {
        const user = c.get("user");
        if (!user || typeof user !== "object") {
            throw ApiError.unauthorized("Not authenticated");
        }

        const users = await authRepo.listUsers();
        let hasAdmin = false;

        for (const u of users) {
            const roles = await authRepo.getUserRoleIds(u.id);
            if (roles.includes("admin")) {
                hasAdmin = true;
                break;
            }
        }

        if (hasAdmin) {
            throw ApiError.forbidden("Admin users already exist. Bootstrap not allowed.");
        }

        const userId = "userId" in user ? user.userId : undefined;
        if (!userId) {
            throw ApiError.unauthorized("User ID not found in auth context");
        }
        await authRepo.setUserRoles(userId, ["admin"]);

        return c.json({
            success: true,
            message: "You are now an admin",
            user: {
                uid: userId,
                roles: ["admin"]
            }
        });
    });

    router.get("/users", requireAdmin, async (c) => {
        const limitParam = c.req.query("limit");
        const offsetParam = c.req.query("offset");
        const search = c.req.query("search");
        const orderBy = c.req.query("orderBy");
        const orderDir = c.req.query("orderDir") as "asc" | "desc" | undefined;

        // If pagination params are provided, use the paginated path
        if (limitParam !== undefined || search) {
            const limit = limitParam ? parseInt(limitParam, 10) : 25;
            const offset = offsetParam ? parseInt(offsetParam, 10) : 0;

            const result = await authRepo.listUsersPaginated({
                limit,
                offset,
                search: search || undefined,
                orderBy: orderBy || undefined,
                orderDir: orderDir || undefined
            });

            const usersWithRoles = await Promise.all(
                result.users.map(async (u) => {
                    const roles = await authRepo.getUserRoleIds(u.id);
                    return {
                        uid: u.id,
                        email: u.email,
                        displayName: u.displayName,
                        photoURL: u.photoUrl,
                        provider: u.provider,
                        roles,
                        createdAt: u.createdAt,
                        updatedAt: u.updatedAt
                    };
                })
            );

            return c.json({
                users: usersWithRoles,
                total: result.total,
                limit: result.limit,
                offset: result.offset
            });
        }

        // Legacy: return all users (no pagination)
        const users = await authRepo.listUsers();
        const usersWithRoles = await Promise.all(
            users.map(async (u) => {
                const roles = await authRepo.getUserRoleIds(u.id);
                return {
                    uid: u.id,
                    email: u.email,
                    displayName: u.displayName,
                    photoURL: u.photoUrl,
                    provider: u.provider,
                    roles,
                    createdAt: u.createdAt,
                    updatedAt: u.updatedAt
                };
            })
        );
        return c.json({ users: usersWithRoles });
    });

    router.get("/users/:userId", requireAdmin, async (c) => {
        const userId = c.req.param("userId");
        const result = await authRepo.getUserWithRoles(userId);

        if (!result) {
            throw ApiError.notFound("User not found");
        }

        return c.json({
            user: {
                uid: result.user.id,
                email: result.user.email,
                displayName: result.user.displayName,
                photoURL: result.user.photoUrl,
                provider: result.user.provider,
                roles: result.roles.map(r => r.id),
                createdAt: result.user.createdAt,
                updatedAt: result.user.updatedAt
            }
        });
    });

    router.post("/users", requireAdmin, async (c) => {
        const body = await c.req.json();
        const { email, displayName, password, roles } = body;

        if (!email) {
            throw ApiError.badRequest("Email is required", "INVALID_INPUT");
        }

        const existing = await authRepo.getUserByEmail(email);
        if (existing) {
            throw ApiError.conflict("Email already exists", "EMAIL_EXISTS");
        }

        // Use provided password or auto-generate one
        const clearPassword = password || generateSecurePassword();

        const validation = validatePasswordStrength(clearPassword);
        if (!validation.valid) {
            throw ApiError.badRequest(validation.errors.join(". "), "WEAK_PASSWORD");
        }
        const passwordHash = await hashPassword(clearPassword);

        const user = await authRepo.createUser({
            email: email.toLowerCase(),
            displayName: displayName || null,
            passwordHash,
            provider: "email"
        });

        if (roles && Array.isArray(roles) && roles.length > 0) {
            await authRepo.setUserRoles(user.id, roles);
        } else if (config.defaultRole) {
            await authRepo.assignDefaultRole(user.id, config.defaultRole);
        }

        const userRoles = await authRepo.getUserRoleIds(user.id);

        // Determine if we can send an invitation email
        const isEmailConfigured = !!(emailService && emailService.isConfigured());
        let invitationSent = false;
        let temporaryPassword: string | undefined;

        if (isEmailConfigured && !password) {
            // Send invitation email via password-reset token flow
            try {
                const token = generateSecureToken();
                const tokenHash = hashToken(token);
                const expiresAt = new Date(Date.now() + 60 * 60 * 1000); // 1 hour

                await authRepo.createPasswordResetToken(user.id, tokenHash, expiresAt);

                const baseUrl = emailConfig?.resetPasswordUrl || "";
                const setPasswordUrl = `${baseUrl}/reset-password?token=${token}`;

                const appName = emailConfig?.appName || "Rebase";
                const templateFn = emailConfig?.templates?.userInvitation;
                const emailContent = templateFn
                    ? templateFn(setPasswordUrl, { email: user.email, displayName: user.displayName })
                    : getUserInvitationTemplate(setPasswordUrl, { email: user.email, displayName: user.displayName }, appName);

                await emailService!.send({
                    to: user.email,
                    subject: emailContent.subject,
                    html: emailContent.html,
                    text: emailContent.text
                });
                invitationSent = true;
            } catch (emailError: unknown) {
                console.error("Failed to send invitation email:", emailError instanceof Error ? emailError.message : emailError);
                // Fall back to returning the temporary password
                temporaryPassword = clearPassword;
            }
        } else if (!password) {
            // No email service — return the auto-generated password one-time
            temporaryPassword = clearPassword;
        }
        // If admin provided a password explicitly, don't return it or send email

        return c.json({
            user: {
                uid: user.id,
                email: user.email,
                displayName: user.displayName,
                roles: userRoles
            },
            invitationSent,
            ...(temporaryPassword ? { temporaryPassword } : {})
        }, 201);
    });

    router.post("/users/:userId/reset-password", requireAdmin, async (c) => {
        const userId = c.req.param("userId");
        const existing = await authRepo.getUserById(userId);
        if (!existing) {
            throw ApiError.notFound("User not found");
        }

        const isEmailConfigured = !!(emailService && emailService.isConfigured());
        let invitationSent = false;
        let temporaryPassword: string | undefined;

        if (isEmailConfigured) {
            try {
                const token = generateSecureToken();
                const tokenHash = hashToken(token);
                const expiresAt = new Date(Date.now() + 60 * 60 * 1000); // 1 hour

                await authRepo.createPasswordResetToken(existing.id, tokenHash, expiresAt);

                const baseUrl = emailConfig?.resetPasswordUrl || "";
                const setPasswordUrl = `${baseUrl}/reset-password?token=${token}`;

                const appName = emailConfig?.appName || "Rebase";
                const templateFn = emailConfig?.templates?.passwordReset;
                const emailContent = templateFn
                    ? templateFn(setPasswordUrl, { email: existing.email, displayName: existing.displayName })
                    : getPasswordResetTemplate(setPasswordUrl, { email: existing.email, displayName: existing.displayName }, appName);

                await emailService!.send({
                    to: existing.email,
                    subject: emailContent.subject,
                    html: emailContent.html,
                    text: emailContent.text
                });
                invitationSent = true;
            } catch (emailError: unknown) {
                console.error("Failed to send reset email:", emailError instanceof Error ? emailError.message : emailError);
                // Fall back to returning the temporary password
                const clearPassword = generateSecurePassword();
                const passwordHash = await hashPassword(clearPassword);
                await authRepo.updatePassword(existing.id, passwordHash);
                temporaryPassword = clearPassword;
            }
        } else {
            // No email service — generate password, set it, and return one-time
            const clearPassword = generateSecurePassword();
            const passwordHash = await hashPassword(clearPassword);
            await authRepo.updatePassword(existing.id, passwordHash);
            temporaryPassword = clearPassword;
        }

        const userRoles = await authRepo.getUserRoleIds(existing.id);

        return c.json({
            user: {
                uid: existing.id,
                email: existing.email,
                displayName: existing.displayName,
                roles: userRoles
            },
            invitationSent,
            ...(temporaryPassword ? { temporaryPassword } : {})
        }, 200);
    });

    router.put("/users/:userId", requireAdmin, async (c) => {
        const userId = c.req.param("userId");
        const body = await c.req.json();
        const { email, displayName, password, roles } = body;

        const existing = await authRepo.getUserById(userId);
        if (!existing) {
            throw ApiError.notFound("User not found");
        }

        const updates: Record<string, unknown> = {};
        if (email !== undefined) updates.email = email.toLowerCase();
        if (displayName !== undefined) updates.displayName = displayName;

        if (password) {
            const validation = validatePasswordStrength(password);
            if (!validation.valid) {
                throw ApiError.badRequest(validation.errors.join(". "), "WEAK_PASSWORD");
            }
            updates.passwordHash = await hashPassword(password);
        }

        if (Object.keys(updates).length > 0) {
            await authRepo.updateUser(userId, updates);
        }

        if (roles !== undefined && Array.isArray(roles)) {
            await authRepo.setUserRoles(userId, roles);
        }

        const result = await authRepo.getUserWithRoles(userId);

        return c.json({
            user: {
                uid: result!.user.id,
                email: result!.user.email,
                displayName: result!.user.displayName,
                roles: result!.roles.map(r => r.id)
            }
        });
    });

    router.delete("/users/:userId", requireAdmin, async (c) => {
        const userId = c.req.param("userId");
        const user = c.get("user");

        const currentUserId = user && typeof user === "object" && "userId" in user ? user.userId : undefined;
        if (currentUserId === userId) {
            throw ApiError.badRequest("Cannot delete your own account", "SELF_DELETE");
        }

        const existing = await authRepo.getUserById(userId);
        if (!existing) {
            throw ApiError.notFound("User not found");
        }

        await authRepo.deleteUser(userId);

        return c.json({ success: true });
    });

    router.get("/roles", requireAdmin, async (c) => {
        const roles = await authRepo.listRoles();

        return c.json({
            roles: roles.map(r => ({
                id: r.id,
                name: r.name,
                isAdmin: r.isAdmin,
                defaultPermissions: r.defaultPermissions,
                config: r.config
            }))
        });
    });

    router.get("/roles/:roleId", requireAdmin, async (c) => {
        const roleId = c.req.param("roleId");
        const role = await authRepo.getRoleById(roleId);

        if (!role) {
            throw ApiError.notFound("Role not found");
        }

        return c.json({ role });
    });

    router.post("/roles", requireAdmin, async (c) => {
        const body = await c.req.json();
        const { id, name, isAdmin, defaultPermissions, config } = body;

        if (!id || !name) {
            throw ApiError.badRequest("Role ID and name are required", "INVALID_INPUT");
        }

        const existing = await authRepo.getRoleById(id);
        if (existing) {
            throw ApiError.conflict("Role already exists", "ROLE_EXISTS");
        }

        const role = await authRepo.createRole({
            id,
            name,
            isAdmin: isAdmin ?? false,
            defaultPermissions: defaultPermissions ?? null,
            config: config ?? null
        });

        return c.json({ role }, 201);
    });

    router.put("/roles/:roleId", requireAdmin, async (c) => {
        const roleId = c.req.param("roleId");
        const body = await c.req.json();
        const { name, isAdmin, defaultPermissions, config } = body;

        const existing = await authRepo.getRoleById(roleId);
        if (!existing) {
            throw ApiError.notFound("Role not found");
        }

        const role = await authRepo.updateRole(roleId, {
            name,
            isAdmin,
            defaultPermissions,
            config
        });

        return c.json({ role });
    });

    router.delete("/roles/:roleId", requireAdmin, async (c) => {
        const roleId = c.req.param("roleId");

        if (["admin", "editor", "viewer"].includes(roleId)) {
            throw ApiError.badRequest("Cannot delete built-in roles", "BUILTIN_ROLE");
        }

        const existing = await authRepo.getRoleById(roleId);
        if (!existing) {
            throw ApiError.notFound("Role not found");
        }

        await authRepo.deleteRole(roleId);

        return c.json({ success: true });
    });

    return router;
}

/**
 * Authentication Abstraction Interfaces
 * 
 * These interfaces define the contracts for authentication-related operations.
 * Implementations can use different databases (PostgreSQL, MongoDB, etc.) to
 * store user, role, and token data.
 */

/**
 * User data structure
 */
export interface UserData {
    id: string;
    email: string;
    passwordHash?: string | null;
    displayName?: string | null;
    photoUrl?: string | null;
    provider: string;
    googleId?: string | null;
    emailVerified: boolean;
    emailVerificationToken?: string | null;
    emailVerificationSentAt?: Date | null;
    createdAt: Date;
    updatedAt: Date;
}

/**
 * Data for creating a new user
 */
export interface CreateUserData {
    email: string;
    passwordHash?: string;
    displayName?: string;
    photoUrl?: string;
    provider?: string;
    googleId?: string;
    emailVerified?: boolean;
}

/**
 * Role data structure
 */
export interface RoleData {
    id: string;
    name: string;
    isAdmin: boolean;
    defaultPermissions: {
        read?: boolean;
        create?: boolean;
        edit?: boolean;
        delete?: boolean;
    } | null;
    collectionPermissions: Record<string, {
        read?: boolean;
        create?: boolean;
        edit?: boolean;
        delete?: boolean;
    }> | null;
    config: Record<string, unknown> | null;
}

/**
 * Data for creating a new role
 */
export interface CreateRoleData {
    id: string;
    name: string;
    isAdmin?: boolean;
    defaultPermissions?: RoleData["defaultPermissions"];
    collectionPermissions?: RoleData["collectionPermissions"];
    config?: RoleData["config"];
}

/**
 * Refresh token info
 */
export interface RefreshTokenInfo {
    id: string;
    userId: string;
    tokenHash: string;
    expiresAt: Date;
    createdAt: Date;
    userAgent?: string | null;
    ipAddress?: string | null;
}

/**
 * Password reset token info
 */
export interface PasswordResetTokenInfo {
    userId: string;
    expiresAt: Date;
}

// =============================================================================
// AUTH REPOSITORY INTERFACES
// =============================================================================

/**
 * Options for paginated user listing
 */
export interface ListUsersOptions {
    /** Max results per page (default 25) */
    limit?: number;
    /** Number of results to skip (default 0) */
    offset?: number;
    /** Search term — matches against email and displayName (case-insensitive) */
    search?: string;
    /** Field to sort by (default "createdAt") */
    orderBy?: string;
    /** Sort direction (default "desc") */
    orderDir?: "asc" | "desc";
}

/**
 * Result of a paginated user listing
 */
export interface PaginatedUsersResult {
    users: UserData[];
    /** Total number of users matching the filters (ignoring limit/offset) */
    total: number;
    limit: number;
    offset: number;
}

/**
 * Abstract user repository interface.
 * Handles all user-related database operations.
 */
export interface UserRepository {
    /**
     * Create a new user
     */
    createUser(data: CreateUserData): Promise<UserData>;

    /**
     * Get a user by ID
     */
    getUserById(id: string): Promise<UserData | null>;

    /**
     * Get a user by email
     */
    getUserByEmail(email: string): Promise<UserData | null>;

    /**
     * Get a user by Google ID
     */
    getUserByGoogleId(googleId: string): Promise<UserData | null>;

    /**
     * Update a user
     */
    updateUser(id: string, data: Partial<Omit<CreateUserData, "id">>): Promise<UserData | null>;

    /**
     * Delete a user
     */
    deleteUser(id: string): Promise<void>;

    /**
     * List all users (unbounded — use listUsersPaginated for large datasets)
     */
    listUsers(): Promise<UserData[]>;

    /**
     * List users with server-side pagination, search, and sorting.
     */
    listUsersPaginated(options?: ListUsersOptions): Promise<PaginatedUsersResult>;

    /**
     * Update user's password hash
     */
    updatePassword(id: string, passwordHash: string): Promise<void>;

    /**
     * Set email verification status
     */
    setEmailVerified(id: string, verified: boolean): Promise<void>;

    /**
     * Set email verification token
     */
    setVerificationToken(id: string, token: string | null): Promise<void>;

    /**
     * Find user by email verification token
     */
    getUserByVerificationToken(token: string): Promise<UserData | null>;

    /**
     * Get roles for a user
     */
    getUserRoles(userId: string): Promise<RoleData[]>;

    /**
     * Get role IDs for a user
     */
    getUserRoleIds(userId: string): Promise<string[]>;

    /**
     * Set roles for a user (replaces existing roles)
     */
    setUserRoles(userId: string, roleIds: string[]): Promise<void>;

    /**
     * Assign a specific role to a new user
     */
    assignDefaultRole(userId: string, roleId: string): Promise<void>;

    /**
     * Get user with their roles
     */
    getUserWithRoles(userId: string): Promise<{ user: UserData; roles: RoleData[] } | null>;
}

/**
 * Abstract role repository interface.
 * Handles all role-related database operations.
 */
export interface RoleRepository {
    /**
     * Get a role by ID
     */
    getRoleById(id: string): Promise<RoleData | null>;

    /**
     * List all roles
     */
    listRoles(): Promise<RoleData[]>;

    /**
     * Create a new role
     */
    createRole(data: CreateRoleData): Promise<RoleData>;

    /**
     * Update a role
     */
    updateRole(id: string, data: Partial<Omit<RoleData, "id">>): Promise<RoleData | null>;

    /**
     * Delete a role
     */
    deleteRole(id: string): Promise<void>;
}

/**
 * Abstract token repository interface.
 * Handles refresh tokens and password reset tokens.
 */
export interface TokenRepository {
    // Refresh tokens

    /**
     * Create a new refresh token
     */
    createRefreshToken(userId: string, tokenHash: string, expiresAt: Date, userAgent?: string, ipAddress?: string): Promise<void>;

    /**
     * Find a refresh token by hash
     */
    findRefreshTokenByHash(tokenHash: string): Promise<RefreshTokenInfo | null>;

    /**
     * Delete a refresh token by hash
     */
    deleteRefreshToken(tokenHash: string): Promise<void>;

    /**
     * Delete all refresh tokens for a user
     */
    deleteAllRefreshTokensForUser(userId: string): Promise<void>;

    /**
     * List all refresh tokens for a user
     */
    listRefreshTokensForUser(userId: string): Promise<RefreshTokenInfo[]>;

    /**
     * Delete a specific refresh token by its primary key ID
     */
    deleteRefreshTokenById(id: string, userId: string): Promise<void>;

    // Password reset tokens

    /**
     * Create a password reset token
     */
    createPasswordResetToken(userId: string, tokenHash: string, expiresAt: Date): Promise<void>;

    /**
     * Find a valid (not expired, not used) password reset token by hash
     */
    findValidPasswordResetToken(tokenHash: string): Promise<PasswordResetTokenInfo | null>;

    /**
     * Mark a password reset token as used
     */
    markPasswordResetTokenUsed(tokenHash: string): Promise<void>;

    /**
     * Delete all password reset tokens for a user
     */
    deleteAllPasswordResetTokensForUser(userId: string): Promise<void>;

    /**
     * Clean up expired tokens
     */
    deleteExpiredTokens(): Promise<void>;
}

/**
 * Combined auth repository interface for convenience
 */
export interface AuthRepository extends UserRepository, RoleRepository, TokenRepository { }

import jwt from "jsonwebtoken";
import { createHash, randomBytes } from "crypto";

export interface JwtConfig {
    secret: string;
    accessExpiresIn?: string;
    refreshExpiresIn?: string;
}

export interface AccessTokenPayload {
    userId: string;
    roles: string[];
}

let jwtConfig: JwtConfig = {
    secret: "",
    accessExpiresIn: "1h",
    refreshExpiresIn: "30d"
};

/**
 * Configure JWT settings - call this during initialization.
 * Validates the secret strength to prevent deployment with default/weak secrets.
 */
export function configureJwt(config: JwtConfig): void {
    // Reject obviously weak/default secrets
    const weakSecrets = new Set([
        "secret",
        "jwt-secret",
        "jwt_secret",
        "your-secret",
        "your-super-secret-jwt-key-change-in-production",
        "change-me",
        "changeme",
        "password",
        "test"
    ]);

    if (!config.secret || config.secret.length < 32) {
        throw new Error(
            "JWT secret is too short. Must be at least 32 characters. " +
            "Generate one with: node -e \"console.log(require('crypto').randomBytes(48).toString('base64'))\""
        );
    }

    if (weakSecrets.has(config.secret.toLowerCase())) {
        throw new Error(
            "JWT secret is a known default/weak value. Please use a strong, randomly generated secret. " +
            "Generate one with: node -e \"console.log(require('crypto').randomBytes(48).toString('base64'))\""
        );
    }

    jwtConfig = {
        ...jwtConfig,
        ...config
    };
}

/**
 * Generate an access token (short-lived, 1 hour by default)
 */
export function generateAccessToken(userId: string, roles: string[]): string {
    if (!jwtConfig.secret) {
        throw new Error("JWT secret not configured. Call configureJwt() first.");
    }

    const payload: AccessTokenPayload = { userId, roles };

    return jwt.sign(payload, jwtConfig.secret, {
        expiresIn: jwtConfig.accessExpiresIn as jwt.SignOptions["expiresIn"],
        algorithm: "HS256"
    });
}

/**
 * Get the expiration time of an access token in milliseconds from now
 */
export function getAccessTokenExpiryMs(): number {
    const duration = jwtConfig.accessExpiresIn || "1h";
    const match = duration.match(/^(\d+)([dhms])$/);

    if (!match) {
        // Default to 1 hour
        return 60 * 60 * 1000;
    }

    const value = parseInt(match[1], 10);
    const unit = match[2];

    switch (unit) {
        case "d": return value * 24 * 60 * 60 * 1000;
        case "h": return value * 60 * 60 * 1000;
        case "m": return value * 60 * 1000;
        case "s": return value * 1000;
        default: return 60 * 60 * 1000;
    }
}

/**
 * Get the expiration timestamp for an access token
 */
export function getAccessTokenExpiry(): number {
    return Date.now() + getAccessTokenExpiryMs();
}

/**
 * Verify and decode an access token
 */
export function verifyAccessToken(token: string): AccessTokenPayload | null {
    if (!jwtConfig.secret) {
        throw new Error("JWT secret not configured. Call configureJwt() first.");
    }

    try {
        const decoded = jwt.verify(token, jwtConfig.secret, { algorithms: ["HS256"] }) as jwt.JwtPayload & AccessTokenPayload;
        return {
            userId: decoded.userId,
            roles: decoded.roles
        };
    } catch (error) {
        return null;
    }
}

/**
 * Generate a random refresh token (long-lived, 30 days by default)
 */
export function generateRefreshToken(): string {
    return randomBytes(40).toString("hex");
}

/**
 * Hash a refresh token for database storage (don't store raw tokens)
 */
export function hashRefreshToken(token: string): string {
    return createHash("sha256").update(token).digest("hex");
}

/**
 * Calculate refresh token expiration date
 */
export function getRefreshTokenExpiry(): Date {
    const duration = jwtConfig.refreshExpiresIn || "30d";
    const match = duration.match(/^(\d+)([dhms])$/);

    if (!match) {
        // Default to 30 days
        return new Date(Date.now() + 30 * 24 * 60 * 60 * 1000);
    }

    const value = parseInt(match[1], 10);
    const unit = match[2];

    let ms: number;
    switch (unit) {
        case "d": ms = value * 24 * 60 * 60 * 1000; break;
        case "h": ms = value * 60 * 60 * 1000; break;
        case "m": ms = value * 60 * 1000; break;
        case "s": ms = value * 1000; break;
        default: ms = 30 * 24 * 60 * 60 * 1000;
    }

    return new Date(Date.now() + ms);
}

import { MiddlewareHandler, Context } from "hono";
import { DataDriver } from "@rebasepro/types";
import { verifyAccessToken, AccessTokenPayload } from "./jwt";
import { HonoEnv } from "../api/types";

/**
 * Result from a custom auth validator.
 * - `false`/`null`/`undefined` = not authenticated
 * - `true` = authenticated as default user
 * - object with `userId` or `uid` = authenticated with user info
 */
export type AuthResult = boolean | null | undefined | { userId?: string; uid?: string; roles?: string[]; [key: string]: unknown };

/**
 * Options for creating an auth middleware via createAuthMiddleware()
 */
export interface AuthMiddlewareOptions {
    /** DataDriver to scope via withAuth() for RLS */
    driver: DataDriver;
    /** If true, return 401 when no valid token is present (default: false) */
    requireAuth?: boolean;
    /** Optional custom validator (for non-JWT auth, e.g. Firebase Auth) */
    validator?: (c: Context<HonoEnv>) => Promise<AuthResult>;
}

/**
 * Express middleware that requires a valid JWT token
 * Returns 401 if token is missing or invalid
 */
export const requireAuth: MiddlewareHandler<HonoEnv> = async (
    c,
    next
) => {
    const authHeader = c.req.header("authorization");
    const queryToken = c.req.query("token");
    const hasBearer = authHeader && authHeader.startsWith("Bearer ");

    if (!hasBearer && !queryToken) {
        return c.json({
            error: {
                message: "Authorization header or token query parameter missing or invalid",
                code: "UNAUTHORIZED"
            }
        }, 401);
    }

    const token = hasBearer ? authHeader!.substring(7) : queryToken!;
    const payload = verifyAccessToken(token);

    if (!payload) {
        return c.json({
            error: {
                message: "Invalid or expired token",
                code: "UNAUTHORIZED"
            }
        }, 401);
    }

    c.set("user", payload);
    return next();
};

/**
 * Middleware that requires the user to have an admin or schema-admin role.
 * Must be used AFTER requireAuth or on a route where user is guaranteed.
 */
export const requireAdmin: MiddlewareHandler<HonoEnv> = async (
    c,
    next
) => {
    const user = c.get("user");
    if (!user) {
        return c.json({
            error: {
                message: "User not authenticated. requireAuth middleware is missing?",
                code: "UNAUTHORIZED"
            }
        }, 401);
    }

    const roles = (typeof user === "object" && user !== null && "roles" in user) ? (user.roles || []) : [];
    const isAdmin = roles.some((role: string) => {
        return role === "admin" || role === "schema-admin";
    });

    if (!isAdmin) {
        return c.json({
            error: {
                message: "Admin privileges required for this operation",
                code: "FORBIDDEN"
            }
        }, 403);
    }

    return next();
};


/**
 * Middleware that optionally extracts user from JWT
 * Does not return 401 if token is missing - allows anonymous access
 */
export const optionalAuth: MiddlewareHandler<HonoEnv> = async (
    c,
    next
) => {
    const authHeader = c.req.header("authorization");
    const queryToken = c.req.query("token");
    const hasBearer = authHeader && authHeader.startsWith("Bearer ");

    if (hasBearer || queryToken) {
        const token = hasBearer ? authHeader!.substring(7) : queryToken!;
        const payload = verifyAccessToken(token);
        if (payload) {
            c.set("user", payload);
        }
    }

    return next();
};

/**
 * Extract user from token - for WebSocket authentication
 */
export function extractUserFromToken(token: string): AccessTokenPayload | null {
    return verifyAccessToken(token);
}

/**
 * Helper to scope a DataDriver via withAuth() for RLS.
 * SECURITY: If withAuth() is available but fails, the error is re-thrown
 * so the request is denied rather than proceeding with unscoped access.
 */
async function scopeDataDriver(
    driver: DataDriver,
    user: { uid: string; roles?: string[] }
): Promise<DataDriver> {
    if ("withAuth" in driver && typeof (driver as Record<string, unknown>).withAuth === "function") {
        // Fail closed — do NOT catch and swallow errors here.
        // If RLS scoping fails the request must be rejected.
        return await (driver as unknown as { withAuth: (user: Record<string, unknown>) => Promise<DataDriver> }).withAuth(user);
    }
    return driver;
}

/**
 * Create a configurable auth middleware that handles:
 * 1. Token extraction (via custom validator or JWT Bearer token)
 * 2. RLS-scoped DataDriver via withAuth()
 * 3. Optional enforcement (401 when requireAuth is true and no user)
 *
 * This is the single source of truth for HTTP auth in Rebase.
 * Use this instead of manually parsing tokens in route handlers.
 */
export function createAuthMiddleware(options: AuthMiddlewareOptions): MiddlewareHandler<HonoEnv> {
    const { driver, requireAuth: enforceAuth = false, validator } = options;

    return async (c, next) => {
        if (validator) {
            // Custom validator path (e.g., Firebase Auth, API keys)
            try {
                const authResult = await validator(c);
                if (authResult && typeof authResult === "object") {
                    const id = ("userId" in authResult ? authResult.userId : undefined)
                        || ("uid" in authResult ? authResult.uid : undefined);
                    if (id) {
                        const roles = authResult.roles || [];
                        c.set("user", { userId: id, roles });
                        const user = { uid: id, roles, ...authResult };
                        c.set("driver", await scopeDataDriver(driver, user));
                    } else {
                        c.set("driver", driver);
                    }
                } else if (authResult === true) {
                    c.set("user", { userId: "default", roles: [] });
                    c.set("driver", driver);
                } else {
                    // Not authenticated - inject anon scope explicitly
                    try {
                        c.set("driver", await scopeDataDriver(driver, { uid: "anon", roles: ["anon"] }));
                    } catch (error) {
                        c.set("driver", driver);
                    }
                }
            } catch (error) {
                return c.json({ error: { message: "Unauthorized", code: "UNAUTHORIZED" } }, 401);
            }
        } else {
            // Default JWT path
            try {
                const authHeader = c.req.header("authorization");
                const queryToken = c.req.query("token");
                const hasBearer = authHeader && authHeader.startsWith("Bearer ");

                if (hasBearer || queryToken) {
                    const token = hasBearer ? authHeader!.substring(7) : queryToken!;
                    const payload = extractUserFromToken(token);

                    if (payload) {
                        c.set("user", payload);
                        const user = { uid: payload.userId, roles: payload.roles };
                        c.set("driver", await scopeDataDriver(driver, user));
                    } else {
                        console.error("[AUTH] Token payload empty or invalid (length: " + token.length + ")");
                        c.set("driver", driver);
                    }
                } else {
                    // Try to inject anon scope to allow RLS policies to match against public connections
                    try {
                        c.set("driver", await scopeDataDriver(driver, { uid: "anon", roles: ["anon"] }));
                    } catch (error) {
                        console.error("[AUTH] Error scoping default anon driver", error);
                        c.set("driver", driver);
                    }
                }
            } catch (error) {
                console.error("Default auth validation error", error);

                // Fallback to anon scope
                try {
                    c.set("driver", await scopeDataDriver(driver, { uid: "anon", roles: ["anon"] }));
                } catch (anonError) {
                    c.set("driver", driver);
                }
            }
        }

        if (enforceAuth && !c.get("user")) {
            console.error("[AUTH] Rejecting with 401. Path:", c.req.path);
            return c.json({ error: { message: "Unauthorized: Invalid or missing token", code: "UNAUTHORIZED" } }, 401);
        }

        return next();
    };
}

import { scrypt, randomBytes, timingSafeEqual } from "crypto";
import { promisify } from "util";

const scryptAsync = promisify(scrypt);

// Scrypt parameters (recommended values for 2024+)
const SALT_LENGTH = 32;
const KEY_LENGTH = 64;
const SCRYPT_PARAMS = { N: 16384, r: 8, p: 1 };

export interface PasswordValidationResult {
    valid: boolean;
    errors: string[];
}

/**
 * Password requirements:
 * - Minimum 8 characters
 * - At least 1 uppercase letter
 * - At least 1 lowercase letter
 * - At least 1 number
 */
export function validatePasswordStrength(password: string): PasswordValidationResult {
    const errors: string[] = [];

    if (password.length < 8) {
        errors.push("Password must be at least 8 characters long");
    }

    if (!/[A-Z]/.test(password)) {
        errors.push("Password must contain at least one uppercase letter");
    }

    if (!/[a-z]/.test(password)) {
        errors.push("Password must contain at least one lowercase letter");
    }

    if (!/[0-9]/.test(password)) {
        errors.push("Password must contain at least one number");
    }

    return {
        valid: errors.length === 0,
        errors
    };
}

/**
 * Hash a password using Node's built-in scrypt
 * Returns format: salt:hash (both hex encoded)
 */
export async function hashPassword(password: string): Promise<string> {
    const salt = randomBytes(SALT_LENGTH);
    const derivedKey = await scryptAsync(password, salt, KEY_LENGTH) as Buffer;
    return `${salt.toString("hex")}:${derivedKey.toString("hex")}`;
}

/**
 * Verify a password against a scrypt hash
 * Expects format: salt:hash (both hex encoded)
 */
export async function verifyPassword(password: string, storedHash: string): Promise<boolean> {
    const [saltHex, hashHex] = storedHash.split(":");
    if (!saltHex || !hashHex) {
        return false;
    }

    const salt = Buffer.from(saltHex, "hex");
    const storedKey = Buffer.from(hashHex, "hex");

    const derivedKey = await scryptAsync(password, salt, KEY_LENGTH) as Buffer;

    // Use timing-safe comparison to prevent timing attacks
    return timingSafeEqual(derivedKey, storedKey);
}

import { MiddlewareHandler } from "hono";
import { HonoEnv } from "../api/types";

/**
 * In-memory sliding-window rate limiter for Hono.
 *
 * Suitable for single-instance and moderate-scale deployments.
 * For multi-instance setups, consider a shared store
 * (e.g. PostgreSQL-backed counters or an external rate-limit service).
 */

interface RateLimitEntry {
    timestamps: number[];
}

interface RateLimiterOptions {
    /** Time window in milliseconds (default: 15 minutes) */
    windowMs?: number;
    /** Maximum requests per window (default: 100) */
    limit?: number;
    /** Key generator function. Defaults to IP-based keying. */
    keyGenerator?: (c: Parameters<MiddlewareHandler<HonoEnv>>[0]) => string;
    /** Custom message for rate limit responses */
    message?: string;
}

/**
 * Create a rate-limiting middleware.
 *
 * Uses a sliding window algorithm: only timestamps within the last
 * `windowMs` milliseconds are counted. Old entries are garbage-collected
 * every `windowMs` to prevent unbounded memory growth.
 */
export function createRateLimiter(options: RateLimiterOptions = {}): MiddlewareHandler<HonoEnv> {
    const {
        windowMs = 15 * 60 * 1000,
        limit = 100,
        keyGenerator = defaultKeyGenerator,
        message = "Too many requests, please try again later."
    } = options;

    const store = new Map<string, RateLimitEntry>();

    // Periodic cleanup to prevent memory leak from expired entries
    const cleanupInterval = setInterval(() => {
        const now = Date.now();
        for (const [key, entry] of store.entries()) {
            entry.timestamps = entry.timestamps.filter(t => now - t < windowMs);
            if (entry.timestamps.length === 0) {
                store.delete(key);
            }
        }
    }, windowMs);

    // Allow the Node.js process to exit even if the interval is still running
    if (cleanupInterval.unref) {
        cleanupInterval.unref();
    }

    return async (c, next) => {
        const key = keyGenerator(c);
        const now = Date.now();

        let entry = store.get(key);
        if (!entry) {
            entry = { timestamps: [] };
            store.set(key, entry);
        }

        // Remove timestamps outside the current window
        entry.timestamps = entry.timestamps.filter(t => now - t < windowMs);

        if (entry.timestamps.length >= limit) {
            const retryAfterMs = entry.timestamps[0] + windowMs - now;
            const retryAfterSec = Math.ceil(retryAfterMs / 1000);

            c.header("Retry-After", String(retryAfterSec));
            c.header("X-RateLimit-Limit", String(limit));
            c.header("X-RateLimit-Remaining", "0");
            c.header("X-RateLimit-Reset", String(Math.ceil((now + retryAfterMs) / 1000)));

            return c.json({
                error: {
                    message,
                    code: "RATE_LIMITED"
                }
            }, 429);
        }

        entry.timestamps.push(now);

        // Set rate limit headers
        c.header("X-RateLimit-Limit", String(limit));
        c.header("X-RateLimit-Remaining", String(limit - entry.timestamps.length));

        return next();
    };
}

/**
 * Default key generator: extract client IP from standard headers.
 */
function defaultKeyGenerator(c: Parameters<MiddlewareHandler<HonoEnv>>[0]): string {
    return (
        c.req.header("x-forwarded-for")?.split(",")[0]?.trim() ||
        c.req.header("x-real-ip") ||
        "unknown"
    );
}

/**
 * Pre-configured rate limiter for general auth endpoints (login, register).
 * 20 requests per 15 minutes per IP.
 */
export const defaultAuthLimiter = createRateLimiter({
    windowMs: 15 * 60 * 1000,
    limit: 20,
    message: "Too many authentication attempts, please try again later."
});

/**
 * Pre-configured strict rate limiter for sensitive endpoints (password reset, verification).
 * 5 requests per 15 minutes per IP.
 */
export const strictAuthLimiter = createRateLimiter({
    windowMs: 15 * 60 * 1000,
    limit: 5,
    message: "Too many requests to this sensitive endpoint, please try again later."
});

import { Hono } from "hono";
import { ApiError } from "../api/errors";
import { randomBytes, createHash } from "crypto";
import type { AuthRepository } from "./interfaces";
import { generateAccessToken, generateRefreshToken, hashRefreshToken, getRefreshTokenExpiry, getAccessTokenExpiry } from "./jwt";
import { hashPassword, verifyPassword, validatePasswordStrength } from "./password";
import { verifyGoogleIdToken, isGoogleOAuthConfigured } from "./google-oauth";
import { requireAuth } from "./middleware";
import { EmailService, EmailConfig } from "../email";
import { getPasswordResetTemplate, getEmailVerificationTemplate } from "../email/templates";
import { HonoEnv } from "../api/types";
import { defaultAuthLimiter, strictAuthLimiter } from "./rate-limiter";
import { z } from "zod";

/**
 * Shared configuration for auth and admin route factories.
 */
export interface AuthModuleConfig {
    authRepo: AuthRepository;
    emailService?: EmailService;
    emailConfig?: EmailConfig;
    /** Allow new user registration (default: false). First user can always register for bootstrap. */
    allowRegistration?: boolean;
    /** Default role ID to assign to new users (default: none). The first user always gets "admin". */
    defaultRole?: string;
}

/**
 * Helper to build standard auth response output
 */
function buildAuthResponse(
    user: { id: string; email: string; displayName?: string | null; photoUrl?: string | null },
    roleIds: string[],
    accessToken: string,
    refreshToken: string
) {
    return {
        user: {
            uid: user.id,
            email: user.email,
            displayName: user.displayName ?? null,
            photoURL: user.photoUrl ?? null,
            roles: roleIds
        },
        tokens: {
            accessToken,
            refreshToken,
            accessTokenExpiresAt: getAccessTokenExpiry()
        }
    };
}

/**
 * Generate a secure random token
 */
function generateSecureToken(): string {
    return randomBytes(40).toString("hex");
}

/**
 * Hash a token for database storage
 */
function hashToken(token: string): string {
    return createHash("sha256").update(token).digest("hex");
}

/**
 * Get password reset token expiry (1 hour from now)
 */
function getPasswordResetExpiry(): Date {
    return new Date(Date.now() + 60 * 60 * 1000); // 1 hour
}

export function createAuthRoutes(config: AuthModuleConfig): Hono<HonoEnv> {
    const router = new Hono<HonoEnv>();
    const authRepo = config.authRepo;
    const { emailService, emailConfig, allowRegistration = false } = config;

    // ── Zod input schemas ──────────────────────────────────────────────
    const registerSchema = z.object({
        email: z.string().email("Invalid email address").max(255),
        password: z.string().min(1, "Password is required").max(128),
        displayName: z.string().max(255).optional()
    });
    const loginSchema = z.object({
        email: z.string().email("Invalid email address").max(255),
        password: z.string().min(1, "Password is required").max(128)
    });
    const googleSchema = z.object({
        idToken: z.string().min(1, "ID token is required")
    });
    const forgotPasswordSchema = z.object({
        email: z.string().email("Invalid email address").max(255)
    });
    const resetPasswordSchema = z.object({
        token: z.string().min(1, "Token is required"),
        password: z.string().min(1, "Password is required").max(128)
    });
    const changePasswordSchema = z.object({
        oldPassword: z.string().min(1, "Old password is required").max(128),
        newPassword: z.string().min(1, "New password is required").max(128)
    });
    const refreshSchema = z.object({
        refreshToken: z.string().min(1, "Refresh token is required")
    });
    const logoutSchema = z.object({
        refreshToken: z.string().optional()
    });
    const updateProfileSchema = z.object({
        displayName: z.string().max(255).optional(),
        photoURL: z.string().url().max(2048).optional()
    });

    /** Parse a Zod schema against the request body, throwing ApiError on failure */
    function parseBody<T>(schema: z.ZodSchema<T>, body: unknown): T {
        const result = schema.safeParse(body);
        if (!result.success) {
            const messages = result.error.errors.map(e => `${e.path.join(".")}: ${e.message}`).join(". ");
            throw ApiError.badRequest(messages, "INVALID_INPUT");
        }
        return result.data;
    }

    /**
     * Check if email service is configured
     */
    function isEmailConfigured(): boolean {
        return !!(emailService && emailService.isConfigured());
    }

    /**
     * Check if registration is allowed (always allow first user for bootstrap)
     */
    async function isRegistrationAllowed(): Promise<boolean> {
        if (allowRegistration) return true;
        // Always allow first user registration for bootstrap
        const allUsers = await authRepo.listUsers();
        return allUsers.length === 0;
    }

    /**
     * POST /auth/register
     * Create a new account with email/password
     */
    router.post("/register", defaultAuthLimiter, async (c) => {
        const { email, password, displayName } = parseBody(registerSchema, await c.req.json());

        // Check if registration is allowed
        const registrationAllowed = await isRegistrationAllowed();
        if (!registrationAllowed) {
            throw ApiError.forbidden("Registration is disabled", "REGISTRATION_DISABLED");
        }

        // Validate password strength
        const passwordValidation = validatePasswordStrength(password);
        if (!passwordValidation.valid) {
            throw ApiError.badRequest(passwordValidation.errors.join(". "), "WEAK_PASSWORD");
        }

        // Check if email already exists
        const existingUser = await authRepo.getUserByEmail(email);
        if (existingUser) {
            throw ApiError.conflict("Email already registered", "EMAIL_EXISTS");
        }

        // Create user
        const passwordHash = await hashPassword(password);
        const user = await authRepo.createUser({
            email: email.toLowerCase(),
            passwordHash,
            displayName: displayName || undefined,
            provider: "email"
        });

        // Check if this is the first user - make them admin
        const allUsers = await authRepo.listUsers();
        const isFirstUser = allUsers.length === 1;
        if (isFirstUser) {
            await authRepo.assignDefaultRole(user.id, "admin");
        } else if (config.defaultRole) {
            await authRepo.assignDefaultRole(user.id, config.defaultRole);
        }

        // Generate tokens
        const roles = await authRepo.getUserRoles(user.id);
        const roleIds = roles.map(r => r.id);
        const accessToken = generateAccessToken(user.id, roleIds);
        const refreshToken = generateRefreshToken();

        // Store refresh token
        const userAgent = c.req.header("user-agent") || "unknown";
        const ipAddress = c.req.header("x-forwarded-for") || "unknown";

        await authRepo.createRefreshToken(
            user.id,
            hashRefreshToken(refreshToken),
            getRefreshTokenExpiry(),
            userAgent,
            ipAddress
        );

        return c.json(buildAuthResponse(user, roleIds, accessToken, refreshToken), 201);
    });

    /**
     * POST /auth/login
     * Login with email/password
     */
    router.post("/login", defaultAuthLimiter, async (c) => {
        const { email, password } = parseBody(loginSchema, await c.req.json());

        const user = await authRepo.getUserByEmail(email);
        if (!user) {
            throw ApiError.unauthorized("Invalid email or password", "INVALID_CREDENTIALS");
        }

        if (!user.passwordHash) {
            throw ApiError.unauthorized("Invalid email or password", "INVALID_CREDENTIALS");
        }

        const isValidPassword = await verifyPassword(password, user.passwordHash);
        if (!isValidPassword) {
            throw ApiError.unauthorized("Invalid email or password", "INVALID_CREDENTIALS");
        }

        // Generate tokens
        const roles = await authRepo.getUserRoles(user.id);
        const roleIds = roles.map(r => r.id);

        const accessToken = generateAccessToken(user.id, roleIds);
        const refreshToken = generateRefreshToken();

        // Store refresh token
        const userAgent = c.req.header("user-agent") || "unknown";
        const ipAddress = c.req.header("x-forwarded-for") || "unknown";

        await authRepo.createRefreshToken(
            user.id,
            hashRefreshToken(refreshToken),
            getRefreshTokenExpiry(),
            userAgent,
            ipAddress
        );

        return c.json(buildAuthResponse(user, roleIds, accessToken, refreshToken));
    });

    /**
     * POST /auth/google
     * Login/register with Google ID token
     */
    router.post("/google", defaultAuthLimiter, async (c) => {
        const { idToken } = parseBody(googleSchema, await c.req.json());

        if (!isGoogleOAuthConfigured()) {
            throw ApiError.serviceUnavailable("Google login not configured", "NOT_CONFIGURED");
        }

        const googleUser = await verifyGoogleIdToken(idToken);
        if (!googleUser) {
            throw ApiError.unauthorized("Invalid Google token", "INVALID_TOKEN");
        }

        // Find or create user
        let user = await authRepo.getUserByGoogleId(googleUser.googleId);

        if (!user) {
            // Check if email exists (link accounts)
            user = await authRepo.getUserByEmail(googleUser.email);

            if (user) {
                // Link Google to existing account
                await authRepo.updateUser(user.id, { googleId: googleUser.googleId });
            } else {
                // Create new user
                user = await authRepo.createUser({
                    email: googleUser.email.toLowerCase(),
                    displayName: googleUser.displayName || undefined,
                    photoUrl: googleUser.photoUrl || undefined,
                    provider: "google",
                    googleId: googleUser.googleId
                });
                // Check if this is the first user - make them admin
                const allUsers = await authRepo.listUsers();
                const isFirstUser = allUsers.length === 1;
                if (isFirstUser) {
                    await authRepo.assignDefaultRole(user.id, "admin");
                } else if (config.defaultRole) {
                    await authRepo.assignDefaultRole(user.id, config.defaultRole);
                }
            }
        } else {
            // Update profile info from Google
            await authRepo.updateUser(user.id, {
                displayName: googleUser.displayName || user.displayName || undefined,
                photoUrl: googleUser.photoUrl || user.photoUrl || undefined
            });
        }

        // Generate tokens
        const roles = await authRepo.getUserRoles(user.id);
        const roleIds = roles.map(r => r.id);
        const accessToken = generateAccessToken(user.id, roleIds);
        const refreshToken = generateRefreshToken();

        // Store refresh token
        const userAgent = c.req.header("user-agent") || "unknown";
        const ipAddress = c.req.header("x-forwarded-for") || "unknown";

        await authRepo.createRefreshToken(
            user.id,
            hashRefreshToken(refreshToken),
            getRefreshTokenExpiry(),
            userAgent,
            ipAddress
        );

        return c.json(buildAuthResponse(user, roleIds, accessToken, refreshToken));
    });

    /**
     * POST /auth/forgot-password
     * Request password reset email
     */
    router.post("/forgot-password", strictAuthLimiter, async (c) => {
        const { email } = parseBody(forgotPasswordSchema, await c.req.json());

        // Check if email service is configured
        if (!isEmailConfigured()) {
            throw ApiError.serviceUnavailable("Email service not configured. Password reset is not available.", "EMAIL_NOT_CONFIGURED");
        }

        // Always return success (security: don't reveal if email exists)
        // But only send email if user exists
        const user = await authRepo.getUserByEmail(email);

        if (user) {
            // Generate reset token
            const token = generateSecureToken();
            const tokenHash = hashToken(token);
            const expiresAt = getPasswordResetExpiry();

            await authRepo.createPasswordResetToken(user.id, tokenHash, expiresAt);

            // Build reset URL
            const baseUrl = emailConfig?.resetPasswordUrl || "";
            const resetUrl = `${baseUrl}/reset-password?token=${token}`;

            // Get email template
            const appName = emailConfig?.appName || "Rebase";
            const templateFn = emailConfig?.templates?.passwordReset;
            const emailContent = templateFn
                ? templateFn(resetUrl, { email: user.email, displayName: user.displayName })
                : getPasswordResetTemplate(resetUrl, { email: user.email, displayName: user.displayName }, appName);

            // Send email
            try {
                await emailService!.send({
                    to: user.email,
                    subject: emailContent.subject,
                    html: emailContent.html,
                    text: emailContent.text
                });
            } catch (emailError: unknown) {
                console.error("Failed to send password reset email:", emailError instanceof Error ? emailError.message : emailError);
                // Don't reveal email sending failure to client
            }
        }

        // Always return success
        return c.json({
            success: true,
            message: "If an account with that email exists, a password reset link has been sent."
        });
    });

    /**
     * POST /auth/reset-password
     * Reset password using token
     */
    router.post("/reset-password", strictAuthLimiter, async (c) => {
        const { token, password } = parseBody(resetPasswordSchema, await c.req.json());

        // Validate password strength
        const passwordValidation = validatePasswordStrength(password);
        if (!passwordValidation.valid) {
            throw ApiError.badRequest(passwordValidation.errors.join(". "), "WEAK_PASSWORD");
        }

        // Find valid token
        const tokenHash = hashToken(token);
        const storedToken = await authRepo.findValidPasswordResetToken(tokenHash);

        if (!storedToken) {
            throw ApiError.badRequest("Invalid or expired reset token", "INVALID_TOKEN");
        }

        // Update password
        const passwordHash = await hashPassword(password);
        await authRepo.updatePassword(storedToken.userId, passwordHash);

        // Mark token as used
        await authRepo.markPasswordResetTokenUsed(tokenHash);

        // Invalidate all refresh tokens (security: log out all sessions)
        await authRepo.deleteAllRefreshTokensForUser(storedToken.userId);

        return c.json({ success: true, message: "Password has been reset successfully" });
    });

    /**
     * POST /auth/change-password
     * Change password for authenticated user
     */
    router.post("/change-password", requireAuth, async (c) => {
        const userCtx = c.get("user") as { userId: string; roles?: string[] } | undefined;
        if (!userCtx) {
            throw ApiError.unauthorized("Not authenticated");
        }

        const { oldPassword, newPassword } = parseBody(changePasswordSchema, await c.req.json());

        // Get user
        const user = await authRepo.getUserById(userCtx.userId);
        if (!user || !user.passwordHash) {
            throw ApiError.badRequest("Cannot change password for this account", "INVALID_ACCOUNT");
        }

        // Verify old password
        const isValidOldPassword = await verifyPassword(oldPassword, user.passwordHash);
        if (!isValidOldPassword) {
            throw ApiError.unauthorized("Current password is incorrect", "INVALID_CREDENTIALS");
        }

        // Validate new password strength
        const passwordValidation = validatePasswordStrength(newPassword);
        if (!passwordValidation.valid) {
            throw ApiError.badRequest(passwordValidation.errors.join(". "), "WEAK_PASSWORD");
        }

        // Update password
        const passwordHash = await hashPassword(newPassword);
        await authRepo.updatePassword(user.id, passwordHash);

        // Invalidate all refresh tokens (security: log out all sessions)
        await authRepo.deleteAllRefreshTokensForUser(user.id);

        return c.json({ success: true, message: "Password has been changed successfully" });
    });

    /**
     * POST /auth/send-verification
     * Send email verification link (authenticated)
     */
    router.post("/send-verification", requireAuth, async (c) => {
        const userCtx = c.get("user") as { userId: string; roles?: string[] } | undefined;
        if (!userCtx) {
            throw ApiError.unauthorized("Not authenticated");
        }

        // Check if email service is configured
        if (!isEmailConfigured()) {
            throw ApiError.serviceUnavailable("Email service not configured. Email verification is not available.", "EMAIL_NOT_CONFIGURED");
        }

        const user = await authRepo.getUserById(userCtx.userId);
        if (!user) {
            throw ApiError.notFound("User not found");
        }

        if (user.emailVerified) {
            throw ApiError.badRequest("Email is already verified", "ALREADY_VERIFIED");
        }

        // Generate verification token
        const token = generateSecureToken();

        // Store hashed token in user record (raw token goes in the email URL)
        await authRepo.setVerificationToken(user.id, hashToken(token));

        // Build verification URL
        const baseUrl = emailConfig?.verifyEmailUrl || "";
        const verifyUrl = `${baseUrl}/verify-email?token=${token}`;

        // Get email template
        const appName = emailConfig?.appName || "Rebase";
        const templateFn = emailConfig?.templates?.emailVerification;
        const emailContent = templateFn
            ? templateFn(verifyUrl, { email: user.email, displayName: user.displayName })
            : getEmailVerificationTemplate(verifyUrl, { email: user.email, displayName: user.displayName }, appName);

        // Send email
        await emailService!.send({
            to: user.email,
            subject: emailContent.subject,
            html: emailContent.html,
            text: emailContent.text
        });

        return c.json({ success: true, message: "Verification email sent" });
    });

    /**
     * GET /auth/verify-email
     * Verify email address using token
     */
    router.get("/verify-email", async (c) => {
        const token = c.req.query("token");

        if (!token) {
            throw ApiError.badRequest("Verification token is required", "INVALID_INPUT");
        }

        // Find user by hashed verification token
        const user = await authRepo.getUserByVerificationToken(hashToken(token));
        if (!user) {
            throw ApiError.badRequest("Invalid or expired verification token", "INVALID_TOKEN");
        }

        // Mark email as verified
        await authRepo.setEmailVerified(user.id, true);

        return c.json({ success: true, message: "Email verified successfully" });
    });

    /**
     * POST /auth/refresh
     * Refresh access token using refresh token
     */
    router.post("/refresh", async (c) => {
        const { refreshToken } = parseBody(refreshSchema, await c.req.json());

        const tokenHash = hashRefreshToken(refreshToken);
        const storedToken = await authRepo.findRefreshTokenByHash(tokenHash);

        if (!storedToken) {
            throw ApiError.unauthorized("Invalid refresh token", "INVALID_TOKEN");
        }

        if (new Date() > storedToken.expiresAt) {
            await authRepo.deleteRefreshToken(tokenHash);
            throw ApiError.unauthorized("Refresh token expired", "TOKEN_EXPIRED");
        }

        // Generate new tokens
        const roles = await authRepo.getUserRoles(storedToken.userId);
        const roleIds = roles.map(r => r.id);

        const newAccessToken = generateAccessToken(storedToken.userId, roleIds);
        const newRefreshToken = generateRefreshToken();

        // Rotate refresh token (delete old, create new)
        const userAgent = c.req.header("user-agent") || "unknown";
        const ipAddress = c.req.header("x-forwarded-for") || "unknown";

        await authRepo.deleteRefreshToken(tokenHash);
        await authRepo.createRefreshToken(
            storedToken.userId,
            hashRefreshToken(newRefreshToken),
            getRefreshTokenExpiry(),
            userAgent,
            ipAddress
        );

        return c.json({
            tokens: {
                accessToken: newAccessToken,
                refreshToken: newRefreshToken,
                accessTokenExpiresAt: getAccessTokenExpiry()
            }
        });
    });

    /**
     * POST /auth/logout
     * Invalidate refresh token
     */
    router.post("/logout", async (c) => {
        const { refreshToken } = parseBody(logoutSchema, await c.req.json());

        if (refreshToken) {
            const tokenHash = hashRefreshToken(refreshToken);
            await authRepo.deleteRefreshToken(tokenHash);
        }

        return c.json({ success: true });
    });

    /**
     * GET /auth/sessions
     * Get active refresh tokens (sessions) for the current user
     */
    router.get("/sessions", requireAuth, async (c) => {
        const userCtx = c.get("user") as { userId: string; roles?: string[] } | undefined;
        if (!userCtx) {
            throw ApiError.unauthorized("Not authenticated");
        }

        const currentRefreshToken = c.req.header("x-refresh-token") as string;
        const currentTokenHash = currentRefreshToken ? hashRefreshToken(currentRefreshToken) : null;

        const sessions = await authRepo.listRefreshTokensForUser(userCtx.userId);

        const mappedSessions = sessions.map(s => ({
            id: s.id,
            userAgent: s.userAgent,
            ipAddress: s.ipAddress,
            createdAt: s.createdAt,
            isCurrentSession: currentTokenHash ? s.tokenHash === currentTokenHash : false
        }));

        return c.json({ sessions: mappedSessions });
    });

    /**
     * DELETE /auth/sessions
     * Delete all refresh tokens for the current user (remote logout every device)
     */
    router.delete("/sessions", requireAuth, async (c) => {
        const userCtx = c.get("user") as { userId: string; roles?: string[] } | undefined;
        if (!userCtx) {
            throw ApiError.unauthorized("Not authenticated");
        }

        await authRepo.deleteAllRefreshTokensForUser(userCtx.userId);
        return c.json({ success: true, message: "All sessions revoked successfully" });
    });

    /**
     * DELETE /auth/sessions/:id
     * Delete a specific refresh token (remote logout)
     */
    router.delete("/sessions/:id", requireAuth, async (c) => {
        const userCtx = c.get("user") as { userId: string; roles?: string[] } | undefined;
        if (!userCtx) {
            throw ApiError.unauthorized("Not authenticated");
        }

        const id = c.req.param("id");
        if (!id) {
            throw ApiError.badRequest("Session ID is required", "INVALID_INPUT");
        }

        await authRepo.deleteRefreshTokenById(id, userCtx.userId);
        return c.json({ success: true, message: "Session revoked successfully" });
    });

    /**
     * GET /auth/me
     * Get current authenticated user
     */
    router.get("/me", requireAuth, async (c) => {
        const userCtx = c.get("user") as { userId: string; roles?: string[] } | undefined;
        if (!userCtx) {
            throw ApiError.unauthorized("Not authenticated");
        }

        const result = await authRepo.getUserWithRoles(userCtx.userId);
        if (!result) {
            throw ApiError.notFound("User not found");
        }

        return c.json({
            user: {
                uid: result.user.id,
                email: result.user.email,
                displayName: result.user.displayName,
                photoURL: result.user.photoUrl,
                emailVerified: result.user.emailVerified,
                roles: result.roles.map(r => r.id)
            }
        });
    });

    /**
     * PATCH /auth/me
     * Update current authenticated user profile
     */
    router.patch("/me", requireAuth, async (c) => {
        const userCtx = c.get("user") as { userId: string; roles?: string[] } | undefined;
        if (!userCtx) {
            throw ApiError.unauthorized("Not authenticated");
        }

        const { displayName, photoURL } = parseBody(updateProfileSchema, await c.req.json());

        const updatedUser = await authRepo.updateUser(userCtx.userId, {
            displayName: displayName !== undefined ? displayName : undefined,
            photoUrl: photoURL !== undefined ? photoURL : undefined,
        });

        if (!updatedUser) {
            throw ApiError.notFound("User not found");
        }

        const result = await authRepo.getUserWithRoles(userCtx.userId);
        if (!result) {
            throw ApiError.notFound("User not found");
        }

        return c.json({
            user: {
                uid: result.user.id,
                email: result.user.email,
                displayName: result.user.displayName,
                photoURL: result.user.photoUrl,
                emailVerified: result.user.emailVerified,
                roles: result.roles.map(r => r.id)
            }
        });
    });

    /**
     * GET /auth/config
     * Get public auth configuration (for frontend to know what's available)
     */
    router.get("/config", defaultAuthLimiter, async (c) => {
        const allUsers = await authRepo.listUsers();
        const needsSetup = allUsers.length === 0;
        const registrationAllowed = needsSetup || allowRegistration;
        return c.json({
            needsSetup,
            registrationEnabled: registrationAllowed,
            googleEnabled: isGoogleOAuthConfigured(),
            emailServiceEnabled: isEmailConfigured()
        });
    });

    return router;
}

import { EntityCollection } from "@rebasepro/types";
import * as fs from "fs";
import * as path from "path";
import { pathToFileURL } from "url";

/**
 * Asynchronously load collection files from a directory for backend initialization
 */
export async function loadCollectionsFromDirectory(directory: string): Promise<EntityCollection[]> {
    const collections: EntityCollection[] = [];
    try {
        if (!fs.existsSync(directory)) {
            console.warn(`[loadCollectionsFromDirectory] Collections directory not found: ${directory}`);
            return collections;
        }

        const files = fs.readdirSync(directory);
        for (const file of files) {
            // Only load .ts and .js files, ignore test files and declaration files
            if ((file.endsWith('.ts') || file.endsWith('.js')) &&
                !file.includes('.test.') &&
                !file.endsWith('.d.ts') &&
                file !== 'index.ts' && file !== 'index.js') {

                const filePath = path.join(directory, file);
                try {
                    const fileUrl = pathToFileURL(filePath).href;

                    // Use new Function to compile dynamic import natively and bypass tsc converting import() to require()
                    const dynamicImport = new Function('url', 'return import(url)');
                    const module = await dynamicImport(fileUrl);

                    // Expect the collection to be the default export
                    if (module && module.default) {
                        collections.push(module.default);
                    } else {
                        console.warn(`[loadCollectionsFromDirectory] File ${file} does not have a default export. Skipping.`);
                    }
                } catch (err: unknown) {
                    const message = err instanceof Error ? err.message : String(err);
                    console.error(`[loadCollectionsFromDirectory] Failed to load collection from ${file}: ${message}`);
                }
            }
        }
    } catch (err) {
        console.error(`[loadCollectionsFromDirectory] Error reading collections directory: ${err}`);
    }
    return collections;
}

