export async function initializeRebaseBackend(config: RebaseBackendConfig): Promise<RebaseBackendInstance> {
    try {
        return await _initializeRebaseBackend(config);
    } catch (error: unknown) {
        console.error("❌ Critical error during Rebase Backend initialization:", error);

        const basePath = config.basePath || "/api";
        config.app.use(`${basePath}/*`, async (c) => {
            return c.json({
                error: {
                    message: "Backend initialization failed. Please check the backend server logs.",
                    code: "backend-init-failed"
                }
            }, 503);
        });

        return {
            __failed: true,
            driverRegistry: DefaultDriverRegistry.create({}),
            driver: {} as unknown as DataDriver,
            realtimeServices: {},
            realtimeService: {} as unknown as RealtimeProvider,
        } as unknown as RebaseBackendInstance;
    }
}

async function _initializeRebaseBackend(config: RebaseBackendConfig): Promise<RebaseBackendInstance> {
    if (config.logging?.level) {
        configureLogLevel(config.logging.level);
    } else {
        configureLogLevel();
    }

    console.log("🔥 Initializing Rebase Backend (Bootstrapper Protocol V2)");

    const collectionRegistry = new BackendCollectionRegistry();
    let activeCollections = config.collections || [];
    if (config.collectionsDir && activeCollections.length === 0) {
        activeCollections = await loadCollectionsFromDirectory(config.collectionsDir);
        console.log(`📁 Auto-discovered ${activeCollections.length} collections from ${config.collectionsDir}`);
    }

    const realtimeServices: Record<string, RealtimeProvider> = {};
    const delegates: Record<string, DataDriver> = {};
    const bootstrappers = config.bootstrappers || [];

    if (bootstrappers.length === 0) {
        throw new Error("No bootstrappers provided. Cannot initialize database drivers.");
    }

    let defaultDriverId = DEFAULT_DRIVER_ID;

    let defaultDriverResult: import("@rebasepro/types").InitializedDriver | undefined = undefined;

    // 1. Initialize all drivers
    for (const bootstrapper of bootstrappers) {
        const b = bootstrapper as BackendBootstrapper & { id?: string; isDefault?: boolean };
        console.log(`📦 Running bootstrapper for driver: "${b.id || bootstrapper.type}"`);
        if (b.isDefault) {
            defaultDriverId = b.id || bootstrapper.type;
        }

        const driverResult = await bootstrapper.initializeDriver({ collections: activeCollections, collectionRegistry });
        delegates[b.id || bootstrapper.type] = driverResult.driver;

        if ((b.id || bootstrapper.type) === defaultDriverId || !defaultDriverResult) {
            defaultDriverResult = driverResult;
        }

        if (bootstrapper.initializeRealtime) {
            const realtime = await bootstrapper.initializeRealtime({}, driverResult);
            realtimeServices[b.id || bootstrapper.type] = realtime as RealtimeProvider;
        }
    }

    const driverRegistry = DefaultDriverRegistry.create(delegates);
    activeCollections.forEach(collection => collectionRegistry.register(collection));

    const defaultDriver = driverRegistry.getOrDefault(defaultDriverId);
    if (!defaultDriver || !defaultDriverResult) {
        throw new Error("Default driver not initialized by bootstrappers");
    }
    const defaultBootstrapper = bootstrappers.find(b => (b as BackendBootstrapper & { id?: string }).id === defaultDriverId || b.type === defaultDriverId) || bootstrappers[0];
    const defaultRealtimeService = defaultDriverResult.realtimeProvider;

    // 2. Initialize Auth & History via the default driver's bootstrapper
    let authConfigResult: BootstrappedAuth | undefined = undefined;
    if (config.auth) {
        // Secure JWT setup proactively within core package memory to eliminate dual-package hazards
        const safeAuthConfig = config.auth;
        if (safeAuthConfig.jwtSecret) {
            configureJwt({
                secret: safeAuthConfig.jwtSecret,
                accessExpiresIn: safeAuthConfig.accessExpiresIn || "1h",
                refreshExpiresIn: safeAuthConfig.refreshExpiresIn || "30d"
            });
        }

        if (defaultBootstrapper.initializeAuth) {
            console.log("🔐 Bootstrapping authentication via driver protocol...");
            authConfigResult = await defaultBootstrapper.initializeAuth(config.auth, defaultDriverResult);
            console.log("✅ Authentication initialized");
        } else {
            console.warn("⚠️ Auth requested but default bootstrapper does not support initializeAuth");
        }
    }

    let historyConfigResult: Record<string, unknown> | undefined = undefined;
    if (config.history) {
        if (defaultBootstrapper.initializeHistory) {
            console.log("📜 Bootstrapping entity history via driver protocol...");
            historyConfigResult = await defaultBootstrapper.initializeHistory(config.history, defaultDriverResult);
            console.log("✅ Entity history initialized");
        } else {
            console.warn("⚠️ History requested but default bootstrapper does not support initializeHistory");
        }
    }

    // 3. Initialize Storage
    let storageRegistry: StorageRegistry | undefined;
    let storageController: StorageController | undefined;

    if (config.storage) {
        console.log("📁 Configuring storage...");
        const controllers: Record<string, StorageController> = {};

        if (typeof config.storage === "object" && "type" in config.storage) {
            const controller = createStorageController(config.storage as BackendStorageConfig);
            controllers[DEFAULT_STORAGE_ID] = controller;
        } else {
            for (const [storageId, storageConfig] of Object.entries(config.storage as Record<string, BackendStorageConfig>)) {
                controllers[storageId] = createStorageController(storageConfig);
            }
        }

        if (Object.keys(controllers).length > 0) {
            storageRegistry = DefaultStorageRegistry.create(controllers);
            storageController = storageRegistry.getDefault();
            console.log(`✅ Initialized ${Object.keys(controllers).length} storage backend(s)`);
        }
    }

    const basePath = config.basePath || "/api";

    // 4. Mount API Routes
    if (config.auth && authConfigResult) {
        const authRoutes = createAuthRoutes({
            authRepo: authConfigResult.authRepository as import("./auth/interfaces").AuthRepository ?? authConfigResult.userService as import("./auth/interfaces").AuthRepository,
            emailService: authConfigResult.emailService as import("./email").EmailService,
            emailConfig: config.auth.email,
            allowRegistration: config.auth.allowRegistration ?? false,
            defaultRole: config.auth.defaultRole
        });
        config.app.route(`${basePath}/auth`, authRoutes);

        const adminRoutes = createAdminRoutes({ 
            authRepo: authConfigResult.authRepository as import("./auth/interfaces").AuthRepository ?? authConfigResult.userService as import("./auth/interfaces").AuthRepository,
            emailService: authConfigResult.emailService as import("./email").EmailService,
            emailConfig: config.auth.email,
        });
        config.app.route(`${basePath}/admin`, adminRoutes);
    }

    if (config.collectionsDir) {
        if (process.env.NODE_ENV !== "production") {
            const { createSchemaEditorRoutes } = await import("./api/schema-editor-routes");
            const schemaEditorRoutes = createSchemaEditorRoutes(config.collectionsDir);

            if (config.auth?.requireAuth !== false && !!config.auth?.jwtSecret) {
                schemaEditorRoutes.use("/*", requireAuth, requireAdmin);
            }

            config.app.route(`${basePath}/schema-editor`, schemaEditorRoutes);
            console.log(`✅ Schema Editor mounted at ${basePath}/schema-editor`);
        }
    }

    if (storageController) {
        const storageRoutes = createStorageRoutes({
            controller: storageController,
            requireAuth: config.auth?.requireAuth ?? true
        });
        config.app.route(`${basePath}/storage`, storageRoutes);
    }

    if (activeCollections.length > 0) {
        const dataRouter = new Hono<HonoEnv>();

        dataRouter.use("/*", createAuthMiddleware({
            driver: defaultDriver,
            requireAuth: false // true BaaS — delegate completely to Postgres RLS
        }));

        const restGenerator = new RestApiGenerator(activeCollections, defaultDriver);
        dataRouter.route("/", restGenerator.generateRoutes());

        if (historyConfigResult && historyConfigResult.historyService) {
            const historyRoutes = createHistoryRoutes({
                historyService: historyConfigResult.historyService as unknown,
                registry: collectionRegistry,
                driver: defaultDriver
            });
            dataRouter.route("/", historyRoutes);
        }

        config.app.route(`${basePath}/data`, dataRouter);
    }

    // 5. Mount Custom Functions
    if (config.functionsDir) {
        const { loadFunctionsFromDirectory } = await import("./functions/function-loader");
        const { createFunctionRoutes } = await import("./functions/function-routes");

        const loadedFunctions = await loadFunctionsFromDirectory(config.functionsDir);

        if (loadedFunctions.length > 0) {
            const functionsRouter = new Hono<HonoEnv>();

            // Apply auth middleware — delegates to RLS, per-route auth is up to the function
            functionsRouter.use("/*", createAuthMiddleware({
                driver: defaultDriver,
                requireAuth: false
            }));

            const fnRoutes = createFunctionRoutes(loadedFunctions);
            functionsRouter.route("/", fnRoutes);
            config.app.route(`${basePath}/functions`, functionsRouter);
            console.log(`⚡ Mounted ${loadedFunctions.length} custom function(s) at ${basePath}/functions`);
        }
    }

    if ((defaultBootstrapper as BackendBootstrapper & { initializeWebsockets?: Function }).initializeWebsockets) {
        await (defaultBootstrapper as BackendBootstrapper & { initializeWebsockets: Function }).initializeWebsockets(config.server, defaultRealtimeService, defaultDriver, config.auth);
    }

    console.log("✅ Rebase Backend Initialized");

    return {
        driverRegistry,
        driver: defaultDriver,
        realtimeServices,
        realtimeService: defaultRealtimeService as RealtimeProvider,
        auth: authConfigResult,
        history: historyConfigResult,
        storageRegistry,
        storageController,
        collectionRegistry
    };
}

/**
 * Driver Registry
 *
 * Manages multiple driver delegates for Rebase backend.
 * Allows different databases for different collections.
 *
 * Usage:
 * - Single DB: Pass a single DataDriver → maps to "(default)"
 * - Multiple DBs: Pass a map of { dbId: DataDriver }
 * - Collections use `databaseId` property to specify which driver to use
 * - Collections without `databaseId` fallback to "(default)"
 */

import { DataDriver } from "@rebasepro/types";

/**
 * The default driver identifier used when:
 * - A single driver is provided (not a map)
 * - A collection doesn't specify a databaseId
 */
export const DEFAULT_DRIVER_ID = "(default)";

/**
 * Registry for managing multiple driver delegates
 */
export interface DriverRegistry {
    /**
     * Register a driver delegate with an ID
     * @param id - Unique identifier for this driver (e.g., "analytics", "users")
     * @param delegate - The DataDriver instance
     */
    register(id: string, delegate: DataDriver): void;

    /**
     * Get the default driver delegate (id = "(default)")
     * @throws Error if no default driver is registered
     */
    getDefault(): DataDriver;

    /**
     * Get a driver delegate by ID
     * @param id - Driver identifier, or undefined/null for default
     * @returns The DataDriver, or undefined if not found
     */
    get(id: string | undefined | null): DataDriver | undefined;

    /**
     * Get a driver delegate by ID, with fallback to default
     * @param id - Driver identifier, or undefined/null for default
     * @returns The DataDriver (falls back to default if id not found)
     * @throws Error if neither the specified nor default driver exists
     */
    getOrDefault(id: string | undefined | null): DataDriver;

    /**
     * Check if a driver with the given ID exists
     */
    has(id: string): boolean;

    /**
     * List all registered driver IDs
     */
    list(): string[];

    /**
     * Get the number of registered drivers
     */
    size(): number;
}

/**
 * Default implementation of DriverRegistry
 */
export class DefaultDriverRegistry implements DriverRegistry {
    private delegates = new Map<string, DataDriver>();

    /**
     * Create a DriverRegistry from either a single delegate or a map
     * @param input - Single DataDriver (maps to "(default)") or Record<string, DataDriver>
     */
    static create(
        input: DataDriver | Record<string, DataDriver>
    ): DefaultDriverRegistry {
        const registry = new DefaultDriverRegistry();

        if (isDataDriverDelegate(input)) {
            // Single delegate → register as "(default)"
            registry.register(DEFAULT_DRIVER_ID, input);
        } else {
            // Map of delegates → register each
            for (const [id, delegate] of Object.entries(input)) {
                registry.register(id, delegate);
            }
            // Ensure there's a default if not explicitly provided
            if (!registry.has(DEFAULT_DRIVER_ID) && registry.size() > 0) {
                // If no explicit "(default)", use the first one as default
                const firstId = Object.keys(input)[0];
                console.warn(
                    `[DriverRegistry] No "${DEFAULT_DRIVER_ID}" driver provided. ` +
                    `Using "${firstId}" as the default.`
                );
                registry.register(DEFAULT_DRIVER_ID, input[firstId]);
            }
        }

        return registry;
    }

    register(id: string, delegate: DataDriver): void {
        if (this.delegates.has(id)) {
            console.warn(`[DriverRegistry] Overwriting driver with id "${id}"`);
        }
        this.delegates.set(id, delegate);
    }

    getDefault(): DataDriver {
        const delegate = this.delegates.get(DEFAULT_DRIVER_ID);
        if (!delegate) {
            throw new Error(
                `[DriverRegistry] No default driver registered. ` +
                `Register one with id "${DEFAULT_DRIVER_ID}" or pass a single DataDriver.`
            );
        }
        return delegate;
    }

    get(id: string | undefined | null): DataDriver | undefined {
        if (id === undefined || id === null) {
            return this.delegates.get(DEFAULT_DRIVER_ID);
        }
        return this.delegates.get(id);
    }

    getOrDefault(id: string | undefined | null): DataDriver {
        // If no ID specified, return default
        if (id === undefined || id === null) {
            return this.getDefault();
        }

        // Try to get by ID
        const delegate = this.delegates.get(id);
        if (delegate) {
            return delegate;
        }

        // Fallback to default with warning
        console.warn(
            `[DriverRegistry] Driver "${id}" not found, falling back to "${DEFAULT_DRIVER_ID}"`
        );
        return this.getDefault();
    }

    has(id: string): boolean {
        return this.delegates.has(id);
    }

    list(): string[] {
        return Array.from(this.delegates.keys());
    }

    size(): number {
        return this.delegates.size;
    }
}

/**
 * Type guard to check if an object is a DataDriver
 */
function isDataDriverDelegate(obj: unknown): obj is DataDriver {
    if (typeof obj !== "object" || obj === null) {
        return false;
    }
    const delegate = obj as DataDriver;
    // Check for required DataDriver properties
    return (
        typeof delegate.key === "string" &&
        typeof delegate.fetchCollection === "function" &&
        typeof delegate.fetchEntity === "function" &&
        typeof delegate.saveEntity === "function" &&
        typeof delegate.deleteEntity === "function"
    );
}

/**
 * Local filesystem storage controller
 */

import * as fs from 'fs';
import * as path from 'path';
import { promisify } from 'util';
import {
    StorageController,
    LocalStorageConfig,
    DEFAULT_MAX_FILE_SIZE
} from './types';
import {
    UploadFileProps,
    UploadFileResult,
    DownloadConfig,
    DownloadMetadata,
    StorageListResult,
    StorageReference
} from '@rebasepro/types';

const mkdir = promisify(fs.mkdir);
const writeFile = promisify(fs.writeFile);
const readFile = promisify(fs.readFile);
const unlink = promisify(fs.unlink);
const readdir = promisify(fs.readdir);
const stat = promisify(fs.stat);
const access = promisify(fs.access);

/**
 * Remove initial and trailing slashes from a path.
 * Handles paths like "/images/", "images/", "/images" → "images"
 */
function normalizeStoragePath(s: string): string {
    let result = s;
    while (result.startsWith('/')) {
        result = result.slice(1);
    }
    while (result.endsWith('/')) {
        result = result.slice(0, -1);
    }
    return result;
}

/**
 * Local filesystem storage implementation
 * Stores files in a directory structure: {basePath}/{bucket}/{path}
 */
export class LocalStorageController implements StorageController {
    private config: LocalStorageConfig;
    private basePath: string;

    constructor(config: LocalStorageConfig) {
        this.config = config;
        this.basePath = path.resolve(config.basePath);
    }

    getType(): 'local' {
        return 'local';
    }

    /**
     * Ensure directory exists, creating it if necessary
     */
    private async ensureDir(dirPath: string): Promise<void> {
        try {
            await mkdir(dirPath, { recursive: true });
        } catch (error: unknown) {
            if (error instanceof Error && (error as NodeJS.ErrnoException).code !== 'EEXIST') {
                throw error;
            }
        }
    }

    /**
     * Get the full filesystem path for a storage path.
     * Includes a path traversal guard to prevent escaping the base directory.
     */
    private getFullPath(storagePath: string, bucket?: string): string {
        const parts = bucket ? [this.basePath, bucket, storagePath] : [this.basePath, storagePath];
        const resolved = path.resolve(path.join(...parts));
        if (!resolved.startsWith(this.basePath + path.sep) && resolved !== this.basePath) {
            throw new Error("Path traversal detected: resolved storage path is outside the base directory.");
        }
        return resolved;
    }

    /**
     * Validate file before upload
     */
    private validateFile(file: File): void {
        const maxSize = this.config.maxFileSize ?? DEFAULT_MAX_FILE_SIZE;
        if (file.size > maxSize) {
            throw new Error(`File size ${file.size} exceeds maximum allowed size ${maxSize}`);
        }

        if (this.config.allowedMimeTypes && this.config.allowedMimeTypes.length > 0) {
            if (!this.config.allowedMimeTypes.includes(file.type)) {
                throw new Error(`File type ${file.type} is not allowed. Allowed types: ${this.config.allowedMimeTypes.join(', ')}`);
            }
        }
    }

    async uploadFile({
        file,
        fileName,
        path: storagePath,
        metadata,
        bucket
    }: UploadFileProps): Promise<UploadFileResult> {
        this.validateFile(file);

        // Always use a bucket (default to 'default')
        const usedBucket = bucket ?? 'default';
        const usedFileName = fileName ?? file.name;
        // Normalize storage path to remove leading/trailing slashes
        const normalizedPath = storagePath ? normalizeStoragePath(storagePath) : '';
        const fullStoragePath = normalizedPath ? `${normalizedPath}/${usedFileName}` : usedFileName;
        const fullPath = this.getFullPath(fullStoragePath, usedBucket);

        // Ensure parent directory exists
        await this.ensureDir(path.dirname(fullPath));

        // Convert File to Buffer and write
        const arrayBuffer = await file.arrayBuffer();
        const buffer = Buffer.from(arrayBuffer);
        await writeFile(fullPath, buffer);

        // Always save metadata file with at least contentType (required for preview)
        const metadataPath = `${fullPath}.metadata.json`;
        await writeFile(metadataPath, JSON.stringify({
            ...(metadata || {}),
            contentType: file.type,
            size: file.size,
            uploadedAt: new Date().toISOString()
        }, null, 2));

        return {
            path: fullStoragePath,
            bucket: usedBucket,
            storageUrl: `local://${usedBucket}/${fullStoragePath}`
        };
    }

    async getDownloadURL(storagePath: string, bucket?: string): Promise<DownloadConfig> {
        // Handle local:// URLs
        let resolvedPath = storagePath;
        let resolvedBucket = bucket;

        if (storagePath.startsWith('local://')) {
            const withoutProtocol = storagePath.substring('local://'.length);
            const firstSlash = withoutProtocol.indexOf('/');
            if (firstSlash > 0) {
                resolvedBucket = withoutProtocol.substring(0, firstSlash);
                resolvedPath = withoutProtocol.substring(firstSlash + 1);
            }
        }

        // Normalize path to handle leading/trailing slashes
        resolvedPath = normalizeStoragePath(resolvedPath);
        const fullPath = this.getFullPath(resolvedPath, resolvedBucket);

        try {
            await access(fullPath, fs.constants.R_OK);
        } catch {
            return {
                url: null,
                fileNotFound: true
            };
        }

        // Read metadata if available
        let metadata: DownloadMetadata | undefined;
        const metadataPath = `${fullPath}.metadata.json`;
        try {
            const metadataContent = await readFile(metadataPath, 'utf-8');
            const savedMetadata = JSON.parse(metadataContent);
            const fileStat = await stat(fullPath);

            metadata = {
                bucket: resolvedBucket ?? 'default',
                fullPath: resolvedPath,
                name: path.basename(resolvedPath),
                size: fileStat.size,
                contentType: savedMetadata.contentType || 'application/octet-stream',
                customMetadata: savedMetadata
            };
        } catch {
            // No metadata file, create basic metadata from stat
            try {
                const fileStat = await stat(fullPath);
                metadata = {
                    bucket: resolvedBucket ?? 'default',
                    fullPath: resolvedPath,
                    name: path.basename(resolvedPath),
                    size: fileStat.size,
                    contentType: 'application/octet-stream',
                    customMetadata: {}
                };
            } catch {
                // Stat failed
            }
        }

        // Return a relative URL that will be served by the storage routes
        const bucketPath = resolvedBucket ? `${resolvedBucket}/` : '';
        const url = `/api/storage/file/${bucketPath}${resolvedPath}`;

        return {
            url,
            metadata
        };
    }

    async getFile(storagePath: string, bucket?: string): Promise<File | null> {
        // Handle local:// URLs
        let resolvedPath = storagePath;
        let resolvedBucket = bucket;

        if (storagePath.startsWith('local://')) {
            const withoutProtocol = storagePath.substring('local://'.length);
            const firstSlash = withoutProtocol.indexOf('/');
            if (firstSlash > 0) {
                resolvedBucket = withoutProtocol.substring(0, firstSlash);
                resolvedPath = withoutProtocol.substring(firstSlash + 1);
            }
        }

        // Normalize path to handle leading/trailing slashes
        resolvedPath = normalizeStoragePath(resolvedPath);
        const fullPath = this.getFullPath(resolvedPath, resolvedBucket);

        try {
            await access(fullPath, fs.constants.R_OK);
            const buffer = await readFile(fullPath);

            // Try to get content type from metadata
            let contentType = 'application/octet-stream';
            try {
                const metadataPath = `${fullPath}.metadata.json`;
                const metadataContent = await readFile(metadataPath, 'utf-8');
                const metadata = JSON.parse(metadataContent);
                contentType = metadata.contentType || contentType;
            } catch {
                // No metadata, use default content type
            }

            const blob = new Blob([buffer], { type: contentType });
            return new File([blob], path.basename(resolvedPath), { type: contentType });
        } catch {
            return null;
        }
    }

    async deleteFile(storagePath: string, bucket?: string): Promise<void> {
        // Handle local:// URLs
        let resolvedPath = storagePath;
        let resolvedBucket = bucket;

        if (storagePath.startsWith('local://')) {
            const withoutProtocol = storagePath.substring('local://'.length);
            const firstSlash = withoutProtocol.indexOf('/');
            if (firstSlash > 0) {
                resolvedBucket = withoutProtocol.substring(0, firstSlash);
                resolvedPath = withoutProtocol.substring(firstSlash + 1);
            }
        }

        // Normalize path to handle leading/trailing slashes
        resolvedPath = normalizeStoragePath(resolvedPath);
        const fullPath = this.getFullPath(resolvedPath, resolvedBucket);

        try {
            await unlink(fullPath);
            // Also delete metadata file if exists
            try {
                await unlink(`${fullPath}.metadata.json`);
            } catch {
                // Metadata file might not exist
            }
        } catch (error: unknown) {
            if (error instanceof Error && (error as NodeJS.ErrnoException).code !== 'ENOENT') {
                throw error;
            }
            // File doesn't exist, nothing to delete
        }
    }

    async list(storagePath: string, options?: {
        bucket?: string;
        maxResults?: number;
        pageToken?: string;
    }): Promise<StorageListResult> {
        // Normalize path to handle leading/trailing slashes
        const normalizedPath = normalizeStoragePath(storagePath);
        const fullPath = this.getFullPath(normalizedPath, options?.bucket);
        const items: StorageReference[] = [];
        const prefixes: StorageReference[] = [];

        try {
            await access(fullPath, fs.constants.R_OK);
            const entries = await readdir(fullPath, { withFileTypes: true });

            let count = 0;
            const maxResults = options?.maxResults ?? 1000;
            const startIndex = options?.pageToken ? parseInt(options.pageToken, 10) : 0;

            for (let i = startIndex; i < entries.length && count < maxResults; i++) {
                const entry = entries[i];

                // Skip metadata files
                if (entry.name.endsWith('.metadata.json')) {
                    continue;
                }

                const entryPath = storagePath ? `${storagePath}/${entry.name}` : entry.name;
                const bucket = options?.bucket ?? 'default';

                const ref: StorageReference = {
                    bucket,
                    fullPath: entryPath,
                    name: entry.name,
                    parent: null as never, // Simplified - not fully implementing parent chain
                    root: null as never,
                    toString: () => `local://${bucket}/${entryPath}`
                };

                if (entry.isDirectory()) {
                    prefixes.push(ref);
                } else {
                    items.push(ref);
                }
                count++;
            }

            const nextPageToken = startIndex + count < entries.length
                ? String(startIndex + count)
                : undefined;

            return {
                items,
                prefixes,
                nextPageToken
            };
        } catch (error: unknown) {
            const code = error?.code;
            if (code === 'ENOENT' || code === 'ENOTDIR') {
                return { items: [], prefixes: [] };
            }
            throw error;
        }
    }

    /**
     * Get the absolute filesystem path for serving files
     * Used by the storage routes to serve files directly
     */
    getAbsolutePath(storagePath: string, bucket?: string): string {
        return this.getFullPath(storagePath, bucket);
    }

    /**
     * Get the base path for the storage
     */
    getBasePath(): string {
        return this.basePath;
    }
}

/**
 * S3-compatible storage controller (works with AWS S3 and MinIO)
 */

import {
    S3Client,
    PutObjectCommand,
    GetObjectCommand,
    DeleteObjectCommand,
    ListObjectsV2Command,
    HeadObjectCommand,
    _Object,
    CommonPrefix
} from '@aws-sdk/client-s3';
import { getSignedUrl } from '@aws-sdk/s3-request-presigner';
import {
    StorageController,
    S3StorageConfig,
    DEFAULT_MAX_FILE_SIZE
} from './types';
import {
    UploadFileProps,
    UploadFileResult,
    DownloadConfig,
    DownloadMetadata,
    StorageListResult,
    StorageReference
} from '@rebasepro/types';

/**
 * S3-compatible storage implementation
 * Works with AWS S3 and MinIO (with forcePathStyle option)
 */
export class S3StorageController implements StorageController {
    private config: S3StorageConfig;
    private client: S3Client;

    constructor(config: S3StorageConfig) {
        this.config = config;
        this.client = new S3Client({
            region: config.region || 'us-east-1',
            endpoint: config.endpoint,
            forcePathStyle: config.forcePathStyle ?? !!config.endpoint, // Auto-enable for custom endpoints (MinIO)
            credentials: {
                accessKeyId: config.accessKeyId,
                secretAccessKey: config.secretAccessKey
            }
        });
    }

    getType(): 's3' {
        return 's3';
    }

    /**
     * Validate file before upload
     */
    private validateFile(file: File): void {
        const maxSize = this.config.maxFileSize ?? DEFAULT_MAX_FILE_SIZE;
        if (file.size > maxSize) {
            throw new Error(`File size ${file.size} exceeds maximum allowed size ${maxSize}`);
        }

        if (this.config.allowedMimeTypes && this.config.allowedMimeTypes.length > 0) {
            if (!this.config.allowedMimeTypes.includes(file.type)) {
                throw new Error(`File type ${file.type} is not allowed. Allowed types: ${this.config.allowedMimeTypes.join(', ')}`);
            }
        }
    }

    /**
     * Get the bucket name - either from parameter or config
     */
    private getBucket(bucket?: string): string {
        return bucket ?? this.config.bucket;
    }

    async uploadFile({
        file,
        fileName,
        path: storagePath,
        metadata,
        bucket
    }: UploadFileProps): Promise<UploadFileResult> {
        this.validateFile(file);

        const usedFileName = fileName ?? file.name;
        const key = storagePath ? `${storagePath}/${usedFileName}` : usedFileName;
        const usedBucket = this.getBucket(bucket);

        // Convert File to Buffer
        const arrayBuffer = await file.arrayBuffer();
        const buffer = Buffer.from(arrayBuffer);

        const command = new PutObjectCommand({
            Bucket: usedBucket,
            Key: key,
            Body: buffer,
            ContentType: file.type,
            Metadata: metadata ? this.flattenMetadata(metadata) : undefined
        });

        await this.client.send(command);

        return {
            path: key,
            bucket: usedBucket,
            storageUrl: `s3://${usedBucket}/${key}`
        };
    }

    /**
     * Flatten nested metadata to string values (S3 requirement)
     */
    private flattenMetadata(metadata: Record<string, unknown>): Record<string, string> {
        const flattened: Record<string, string> = {};
        for (const [key, value] of Object.entries(metadata)) {
            if (typeof value === 'string') {
                flattened[key] = value;
            } else if (value !== undefined && value !== null) {
                flattened[key] = JSON.stringify(value);
            }
        }
        return flattened;
    }

    async getDownloadURL(storagePath: string, bucket?: string): Promise<DownloadConfig> {
        // Handle s3:// URLs
        let resolvedPath = storagePath;
        let resolvedBucket = this.getBucket(bucket);

        if (storagePath.startsWith('s3://')) {
            const withoutProtocol = storagePath.substring('s3://'.length);
            const firstSlash = withoutProtocol.indexOf('/');
            if (firstSlash > 0) {
                resolvedBucket = withoutProtocol.substring(0, firstSlash);
                resolvedPath = withoutProtocol.substring(firstSlash + 1);
            }
        }

        try {
            // First check if the object exists and get metadata
            const headCommand = new HeadObjectCommand({
                Bucket: resolvedBucket,
                Key: resolvedPath
            });

            const headResult = await this.client.send(headCommand);

            // Generate a signed URL
            const getCommand = new GetObjectCommand({
                Bucket: resolvedBucket,
                Key: resolvedPath
            });

            const expiresIn = this.config.signedUrlExpiration ?? 3600;
            const url = await getSignedUrl(this.client, getCommand, { expiresIn });

            const metadata: DownloadMetadata = {
                bucket: resolvedBucket,
                fullPath: resolvedPath,
                name: resolvedPath.split('/').pop() || resolvedPath,
                size: headResult.ContentLength || 0,
                contentType: headResult.ContentType || 'application/octet-stream',
                customMetadata: headResult.Metadata || {}
            };

            return {
                url,
                metadata
            };
        } catch (error: unknown) {
            const s3Error = error as { name?: string; $metadata?: { httpStatusCode?: number } };
            if (s3Error.name === 'NotFound' || s3Error.$metadata?.httpStatusCode === 404) {
                return {
                    url: null,
                    fileNotFound: true
                };
            }
            throw error;
        }
    }

    async getFile(storagePath: string, bucket?: string): Promise<File | null> {
        // Handle s3:// URLs
        let resolvedPath = storagePath;
        let resolvedBucket = this.getBucket(bucket);

        if (storagePath.startsWith('s3://')) {
            const withoutProtocol = storagePath.substring('s3://'.length);
            const firstSlash = withoutProtocol.indexOf('/');
            if (firstSlash > 0) {
                resolvedBucket = withoutProtocol.substring(0, firstSlash);
                resolvedPath = withoutProtocol.substring(firstSlash + 1);
            }
        }

        try {
            const command = new GetObjectCommand({
                Bucket: resolvedBucket,
                Key: resolvedPath
            });

            const response = await this.client.send(command);

            if (!response.Body) {
                return null;
            }

            // Convert stream to buffer
            const chunks: Uint8Array[] = [];
            // @ts-ignore - Body is a ReadableStream in Node.js
            for await (const chunk of response.Body) {
                chunks.push(chunk);
            }
            const buffer = Buffer.concat(chunks);

            const contentType = response.ContentType || 'application/octet-stream';
            const fileName = resolvedPath.split('/').pop() || resolvedPath;

            const blob = new Blob([buffer], { type: contentType });
            return new File([blob], fileName, { type: contentType });
        } catch (error: unknown) {
            const s3Error = error as { name?: string; $metadata?: { httpStatusCode?: number } };
            if (s3Error.name === 'NoSuchKey' || s3Error.$metadata?.httpStatusCode === 404) {
                return null;
            }
            throw error;
        }
    }

    async deleteFile(storagePath: string, bucket?: string): Promise<void> {
        // Handle s3:// URLs
        let resolvedPath = storagePath;
        let resolvedBucket = this.getBucket(bucket);

        if (storagePath.startsWith('s3://')) {
            const withoutProtocol = storagePath.substring('s3://'.length);
            const firstSlash = withoutProtocol.indexOf('/');
            if (firstSlash > 0) {
                resolvedBucket = withoutProtocol.substring(0, firstSlash);
                resolvedPath = withoutProtocol.substring(firstSlash + 1);
            }
        }

        const command = new DeleteObjectCommand({
            Bucket: resolvedBucket,
            Key: resolvedPath
        });

        await this.client.send(command);
    }

    async list(storagePath: string, options?: {
        bucket?: string;
        maxResults?: number;
        pageToken?: string;
    }): Promise<StorageListResult> {
        const resolvedBucket = this.getBucket(options?.bucket);

        const command = new ListObjectsV2Command({
            Bucket: resolvedBucket,
            Prefix: storagePath || undefined,
            MaxKeys: options?.maxResults ?? 1000,
            ContinuationToken: options?.pageToken,
            Delimiter: '/' // This gives us folder-like behavior
        });

        const response = await this.client.send(command);

        const items: StorageReference[] = (response.Contents || []).map(obj => ({
            bucket: resolvedBucket,
            fullPath: obj.Key || '',
            name: (obj.Key || '').split('/').pop() || '',
            parent: null as never,
            root: null as never,
            toString: () => `s3://${resolvedBucket}/${obj.Key}`
        }));

        const prefixes: StorageReference[] = (response.CommonPrefixes || []).map(prefix => ({
            bucket: resolvedBucket,
            fullPath: prefix.Prefix || '',
            name: (prefix.Prefix || '').replace(/\/$/, '').split('/').pop() || '',
            parent: null as never,
            root: null as never,
            toString: () => `s3://${resolvedBucket}/${prefix.Prefix}`
        }));

        return {
            items,
            prefixes,
            nextPageToken: response.NextContinuationToken
        };
    }
}

/**
 * Storage module for Rebase backend
 *
 * Provides file storage functionality with support for:
 * - Local filesystem storage (default, zero config)
 * - S3-compatible storage (AWS S3, MinIO)
 */

export * from './types';
export { LocalStorageController } from './LocalStorageController';
export { S3StorageController } from './S3StorageController';
export { createStorageRoutes } from './routes';
export type { StorageRoutesConfig } from './routes';
export * from './storage-registry';

import { BackendStorageConfig, StorageController } from './types';
import { LocalStorageController } from './LocalStorageController';
import { S3StorageController } from './S3StorageController';

/**
 * Factory function to create a storage controller based on configuration
 */
export function createStorageController(config: BackendStorageConfig): StorageController {
    switch (config.type) {
        case 'local':
            return new LocalStorageController(config);
        case 's3':
            return new S3StorageController(config);
        default:
            throw new Error(`Unknown storage type: ${(config as Record<string, unknown>).type}`);
    }
}

/**
 * Storage REST API routes using Hono
 */

import { Hono } from 'hono';
import * as fs from 'fs';
import { StorageController } from './types';
import { LocalStorageController } from './LocalStorageController';
import { requireAuth as jwtRequireAuth, optionalAuth } from '../auth/middleware';
import { ApiError } from '../api/errors';
import { HonoEnv } from '../api/types';

export interface StorageRoutesConfig {
    controller: StorageController;
    /** Base path for storage routes (default: '/api/storage') */
    basePath?: string;
    /** Require authentication for write operations (default: true) */
    requireAuth?: boolean;
    /** Allow unauthenticated read access to stored files (default: false).
     *  When false and requireAuth is true, reads also require authentication. */
    publicRead?: boolean;
}

/**
 * Create storage REST API routes
 */
export function createStorageRoutes(config: StorageRoutesConfig): Hono<HonoEnv> {
    const router = new Hono<HonoEnv>();
    const { controller, requireAuth = true, publicRead = false } = config;

    // Use actual JWT auth middleware from auth module
    const writeAuthMiddleware = requireAuth ? jwtRequireAuth : optionalAuth;

    // For read operations: respect publicRead config.
    const readAuthMiddleware = (publicRead || !requireAuth) ? optionalAuth : jwtRequireAuth;

    /**
     * Parse bucket and path from a combined file path.
     */
    const parseBucketAndPath = (filePath: string): { bucket: string; resolvedPath: string } => {
        const parts = filePath.split('/');

        // Only recognize 'default' as an explicit bucket prefix
        if (parts.length > 1 && parts[0].toLowerCase() === 'default') {
            return {
                bucket: 'default',
                resolvedPath: parts.slice(1).join('/')
            };
        }

        // All other paths use 'default' bucket with the full path
        return {
            bucket: 'default',
            resolvedPath: filePath
        };
    };

    /**
     * POST /upload - Upload a file
     * Body: multipart/form-data with 'file' field
     * Request body can also contain metadata keys 'metadata_*'
     */
    router.post('/upload', writeAuthMiddleware, async (c) => {
        const body = await c.req.parseBody();
        const uploadedFile = body['file'];

        if (!uploadedFile || typeof uploadedFile === 'string') {
            throw ApiError.badRequest('No file provided');
        }

        const storagePath = typeof body['path'] === 'string' ? body['path'] : '';
        const bucket = typeof body['bucket'] === 'string' ? body['bucket'] : undefined;
        let fileName = typeof body['fileName'] === 'string' ? body['fileName'] : undefined;

        if (!fileName) {
            fileName = uploadedFile.name;
        }

        // Extract custom metadata from request body
        const metadata: Record<string, unknown> = {};
        for (const [key, value] of Object.entries(body)) {
            if (key.startsWith('metadata_')) {
                metadata[key.replace('metadata_', '')] = value;
            }
        }

        const result = await controller.uploadFile({
            file: uploadedFile,
            fileName: fileName || 'unnamed',
            path: storagePath,
            metadata: Object.keys(metadata).length > 0 ? metadata : undefined,
            bucket
        });

        return c.json({
            success: true,
            data: result
        }, 201);
    });

    /**
     * GET /file/* - Download/serve a file
     * Path: /file/{bucket}/{path} or /file/{path}
     */
    router.get('/file/*', readAuthMiddleware, async (c) => {
        const rawPath = c.req.path.replace(new RegExp(`^.*/file/`), '');
        if (!rawPath) {
            throw ApiError.badRequest('File path required');
        }

        const filePath = decodeURIComponent(rawPath);

        // For local storage, serve the file directly
        if (controller.getType() === 'local') {
            const localController = controller as LocalStorageController;
            const { bucket, resolvedPath } = parseBucketAndPath(filePath);

            const absolutePath = localController.getAbsolutePath(resolvedPath, bucket);

            // Check if file exists
            if (!fs.existsSync(absolutePath)) {
                throw ApiError.notFound('File not found');
            }

            // Get content type from metadata or infer from extension
            let contentType = 'application/octet-stream';
            const metadataPath = `${absolutePath}.metadata.json`;
            if (fs.existsSync(metadataPath)) {
                try {
                    const metadata = JSON.parse(fs.readFileSync(metadataPath, 'utf-8'));
                    contentType = metadata.contentType || contentType;
                } catch {
                    // Ignore metadata errors
                }
            }

            c.header('Content-Type', contentType);
            // In a better scenario, we should pipe the stream instead of reading whole file
            const fileContent = fs.readFileSync(absolutePath);
            return c.body(new Uint8Array(fileContent)); 
        }

        // For S3 storage, redirect to signed URL
        const downloadConfig = await controller.getDownloadURL(filePath);
        if (downloadConfig.fileNotFound || !downloadConfig.url) {
            throw ApiError.notFound('File not found');
        }

        return c.redirect(downloadConfig.url);
    });

    /**
     * GET /metadata/* - Get file metadata
     */
    router.get('/metadata/*', readAuthMiddleware, async (c) => {
        const rawPath = c.req.path.replace(new RegExp(`^.*/metadata/`), '');
        if (!rawPath) {
            throw ApiError.badRequest('File path required');
        }

        const filePath = decodeURIComponent(rawPath);
        const { bucket, resolvedPath } = parseBucketAndPath(filePath);

        const downloadConfig = await controller.getDownloadURL(resolvedPath, bucket);

        if (downloadConfig.fileNotFound) {
            throw ApiError.notFound('File not found');
        }

        return c.json({
            success: true,
            data: downloadConfig.metadata
        });
    });

    /**
     * DELETE /file/* - Delete a file
     */
    router.delete('/file/*', writeAuthMiddleware, async (c) => {
        const rawPath = c.req.path.replace(new RegExp(`^.*/file/`), '');
        if (!rawPath) {
            throw ApiError.badRequest('File path required');
        }

        const filePath = decodeURIComponent(rawPath);
        const { bucket, resolvedPath } = parseBucketAndPath(filePath);

        await controller.deleteFile(resolvedPath, bucket);

        return c.json({
            success: true,
            message: 'File deleted'
        });
    });

    /**
     * GET /list - List files in a path
     */
    router.get('/list', writeAuthMiddleware, async (c) => {
        const storagePath = c.req.query('path') || '';
        const bucket = c.req.query('bucket');
        const maxResults = c.req.query('maxResults');
        const pageToken = c.req.query('pageToken');

        const result = await controller.list(
            storagePath,
            {
                bucket,
                maxResults: maxResults ? parseInt(maxResults, 10) : undefined,
                pageToken
            }
        );

        return c.json({
            success: true,
            data: result
        });
    });

    return router;
}

/**
 * Storage Registry
 *
 * Manages multiple storage controllers for Rebase backend.
 * Allows different storage backends for different use cases.
 *
 * Usage:
 * - Single storage: Pass a single StorageController → maps to "(default)"
 * - Multiple storages: Pass a map of { storageId: StorageController }
 * - String properties use `storageId` in their config to specify which storage to use
 * - Properties without `storageId` fallback to "(default)"
 */

import { StorageController } from "./types";

/**
 * The default storage identifier used when:
 * - A single storage controller is provided (not a map)
 * - A property doesn't specify a storageId
 */
export const DEFAULT_STORAGE_ID = "(default)";

/**
 * Registry for managing multiple storage controllers
 */
export interface StorageRegistry {
    /**
     * Register a storage controller with an ID
     * @param id - Unique identifier for this storage (e.g., "media", "backups")
     * @param controller - The StorageController instance
     */
    register(id: string, controller: StorageController): void;

    /**
     * Get the default storage controller (id = "(default)")
     * @throws Error if no default storage is registered
     */
    getDefault(): StorageController;

    /**
     * Get a storage controller by ID
     * @param id - Storage identifier, or undefined/null for default
     * @returns The StorageController, or undefined if not found
     */
    get(id: string | undefined | null): StorageController | undefined;

    /**
     * Get a storage controller by ID, with fallback to default
     * @param id - Storage identifier, or undefined/null for default
     * @returns The StorageController (falls back to default if id not found)
     * @throws Error if neither the specified nor default storage exists
     */
    getOrDefault(id: string | undefined | null): StorageController;

    /**
     * Check if a storage with the given ID exists
     */
    has(id: string): boolean;

    /**
     * List all registered storage IDs
     */
    list(): string[];

    /**
     * Get the number of registered storage controllers
     */
    size(): number;
}

/**
 * Default implementation of StorageRegistry
 */
export class DefaultStorageRegistry implements StorageRegistry {
    private controllers = new Map<string, StorageController>();

    /**
     * Create a StorageRegistry from either a single controller or a map
     * @param input - Single StorageController (maps to "(default)") or Record<string, StorageController>
     */
    static create(
        input: StorageController | Record<string, StorageController>
    ): DefaultStorageRegistry {
        const registry = new DefaultStorageRegistry();

        if (isStorageController(input)) {
            // Single controller → register as "(default)"
            registry.register(DEFAULT_STORAGE_ID, input);
        } else {
            // Map of controllers → register each
            for (const [id, controller] of Object.entries(input)) {
                if (isStorageController(controller)) {
                    registry.register(id, controller);
                }
            }
            // Ensure there's a default if not explicitly provided
            if (!registry.has(DEFAULT_STORAGE_ID) && registry.size() > 0) {
                // If no explicit "(default)", use the first one as default
                const firstId = Object.keys(input).find(k => isStorageController(input[k]));
                if (firstId) {
                    console.warn(
                        `[StorageRegistry] No "${DEFAULT_STORAGE_ID}" storage provided. ` +
                        `Using "${firstId}" as the default.`
                    );
                    registry.register(DEFAULT_STORAGE_ID, input[firstId]);
                }
            }
        }

        return registry;
    }

    register(id: string, controller: StorageController): void {
        if (this.controllers.has(id)) {
            console.warn(`[StorageRegistry] Overwriting storage with id "${id}"`);
        }
        this.controllers.set(id, controller);
    }

    getDefault(): StorageController {
        const controller = this.controllers.get(DEFAULT_STORAGE_ID);
        if (!controller) {
            throw new Error(
                `[StorageRegistry] No default storage registered. ` +
                `Register one with id "${DEFAULT_STORAGE_ID}" or pass a single StorageController.`
            );
        }
        return controller;
    }

    get(id: string | undefined | null): StorageController | undefined {
        if (id === undefined || id === null) {
            return this.controllers.get(DEFAULT_STORAGE_ID);
        }
        return this.controllers.get(id);
    }

    getOrDefault(id: string | undefined | null): StorageController {
        // If no ID specified, return default
        if (id === undefined || id === null) {
            return this.getDefault();
        }

        // Try to get by ID
        const controller = this.controllers.get(id);
        if (controller) {
            return controller;
        }

        // Fallback to default with warning
        console.warn(
            `[StorageRegistry] Storage "${id}" not found, falling back to "${DEFAULT_STORAGE_ID}"`
        );
        return this.getDefault();
    }

    has(id: string): boolean {
        return this.controllers.has(id);
    }

    list(): string[] {
        return Array.from(this.controllers.keys());
    }

    size(): number {
        return this.controllers.size;
    }
}

/**
 * Type guard to check if an object is a StorageController
 * vs a Record<string, StorageController> (multiple storages)
 */
function isStorageController(obj: unknown): obj is StorageController {
    if (typeof obj !== "object" || obj === null) {
        return false;
    }
    const controller = obj as StorageController;
    // Check for required StorageController properties
    return (
        typeof controller.uploadFile === "function" &&
        typeof controller.getDownloadURL === "function" &&
        typeof controller.deleteFile === "function" &&
        typeof controller.list === "function" &&
        typeof controller.getType === "function"
    );
}

/**
 * Storage configuration and types for Rebase backend
 */

import { StorageSource, UploadFileProps, UploadFileResult, DownloadConfig, StorageListResult, StorageReference } from "@rebasepro/types";

/**
 * Local filesystem storage configuration
 */
export interface LocalStorageConfig {
    type: 'local';
    /** Base directory for file storage (e.g., './uploads') */
    basePath: string;
    /** Maximum file size in bytes (default: 50MB) */
    maxFileSize?: number;
    /** Allowed MIME types (if not set, all types allowed) */
    allowedMimeTypes?: string[];
    /** Base URL for generating download URLs (default: auto-detected from request) */
    baseUrl?: string;
}

/**
 * S3-compatible storage configuration (works with AWS S3 and MinIO)
 */
export interface S3StorageConfig {
    type: 's3';
    /** S3 bucket name */
    bucket: string;
    /** AWS region (e.g., 'us-east-1') */
    region?: string;
    /** Custom endpoint URL (required for MinIO) */
    endpoint?: string;
    /** AWS access key ID */
    accessKeyId: string;
    /** AWS secret access key */
    secretAccessKey: string;
    /** Use path-style URLs (required for MinIO) */
    forcePathStyle?: boolean;
    /** Maximum file size in bytes (default: 50MB) */
    maxFileSize?: number;
    /** Allowed MIME types (if not set, all types allowed) */
    allowedMimeTypes?: string[];
    /** URL expiration time in seconds for signed URLs (default: 3600) */
    signedUrlExpiration?: number;
}

/**
 * Storage configuration - either local filesystem or S3-compatible
 */
export type BackendStorageConfig = LocalStorageConfig | S3StorageConfig;

/**
 * Storage controller interface for backend implementations
 */
export interface StorageController {
    /**
     * Upload a file
     */
    uploadFile(props: UploadFileProps): Promise<UploadFileResult>;

    /**
     * Get a download URL for a file
     */
    getDownloadURL(path: string, bucket?: string): Promise<DownloadConfig>;

    /**
     * Get file as a File object
     */
    getFile(path: string, bucket?: string): Promise<File | null>;

    /**
     * Delete a file
     */
    deleteFile(path: string, bucket?: string): Promise<void>;

    /**
     * List files in a path
     */
    list(path: string, options?: {
        bucket?: string;
        maxResults?: number;
        pageToken?: string;
    }): Promise<StorageListResult>;

    /**
     * Get the storage configuration type
     */
    getType(): 'local' | 's3';
}

/**
 * Default maximum file size (50MB)
 */
export const DEFAULT_MAX_FILE_SIZE = 50 * 1024 * 1024;

